import type { CatalogSong } from '../types.js';

export const OPEN_HYMNAL: CatalogSong[] = [{"id":"oh-a-child-of-the-king","title":"A Child of The King","language":"en","writers":"Harriet E. Buell, 1877, alt","music":"John Bunnell Sumner","year":1877,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"BINGHAMTON","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nMy Father is rich in houses and lands,\nHe holdeth the wealth of the world in His hands!\nOf rubies and diamonds of silver and gold His coffers are full,\n— He has riches untold.\n\nChorus\nI'm a child of the King, a child of the King:\nWith Jesus my Savior I'm a child of the King.\n\nVerse 2\nMy Father's own Son, the Savior of men,\nOnce wander'd o'er earth as the poorest of men,\nBut now He is reigning forever on high,\nAnd will give me a home in heaven by and by.\n\nVerse 3\nI once was an outcast stranger on earth,\nA sinner by choice, and an alien by birth!\nBut I've been adopted, my name's written down,\n— An heir to a mansion, a robe, and a crown.\n\nVerse 4\nA tent or a cottage, why should I care?\nThey're building a palace for me over there!\nTho' exiled from home, yet, still I may sing:\nAll glory to God,\nI'm the child of a King.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-a-great-and-mighty-wonder","title":"A Great and Mighty Wonder","language":"en","writers":"Germanus of Constantinople (634-734). Translated by John Mason Neale","music":"German from Köln","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ES IST EIN ROS ENTSPRUNGEN (RHYTHMIC)","themes":["Hymn"],"lyrics":"Verse 1\nA great and mighty wonder, a full and holy cure:\nThe virgin bears the Infant with virgin honor pure!\n\nChorus\nRepeat the hymn again:\n\"To God on high be glory And peace on earth to men!\"\n\nVerse 2\nThe Word becomes incarnate and yet remains on high,\nAnd cherubim sing anthems to shepherds from the sky.\n\nVerse 3\nWhile thus they sing your Monarch, those bright angelic bands,\nRejoice, ye vales and mountains, ye oceans, clap your hands.\n\nVerse 4\nSince all He comes to ransom, by all be He adored,\nThe Infant born in Bethl'em, the Savior and the Lord.\n\nVerse 5\nAnd idol forms shall perish, and error shall decay,\nAnd Christ shall wield His scepter, our Lord and God for aye.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-a-lamb-goes-uncomplaining-forth","title":"A Lamb Goes Uncomplaining Forth","language":"en","writers":"Paul Gerhardt, 1648. Translation composite","music":"Wolfgang Dachstein","year":1648,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"AN WASSERFLÜSSEN BABYLON","themes":["Hymn","Lent"],"lyrics":"Verse 1\nA Lamb goes uncomplaining forth,\nThe guilt of all men bearing;\nAnd laden with the sins of earth,\nNone else the burden sharing!\nGoes patient on, grow weak and faint,\nTo slaughter led without complaint,\nThat spotless life to offer;\nBears shame and stripes, and wounds and death,\nAnguish and mockery, and saith,\n\"Willing all this I suffer.\"\n\nVerse 2\nThis Lamb is Christ, the soul's great Friend,\nThe Lamb of God, our Savior;\nHim God the Father chose to send To gain for us His favor.\n\"Go forth, My Son,\" the Father saith,\n\"And free men from the fear of death,\nFrom guilt and condemnation.\nThe wrath and stripes are hard to bear,\nBut by Thy Passion men shall share The fruit of Thy salvation.\"\n\nVerse 3\n\"Yea, Father, yea, most willingly I'll bear what Thou commandest;\nMy will conforms to Thy decree,\nI do what Thou demandest.\" O wondrous Love, what hast Thou done!\nThe Father offers up His Son!\nThe Son, content, descendeth!\nO Love, how strong Thou art to save!\nThou beddest Him within the grave Whose word the mountains rendeth.\n\nVerse 4\nThou lay'st Him, Love, upon the cross,\nWith nails and spear Him bruising;\nThou slay'st Him as a lamb,\nHis loss from soul and body oozing;\nFrom body 'tis the crimson flood\nOf precious sacrificial blood From soul,\nthe strength of anguish:\nMy gain it is; sweet Lamb to Thee What can I give,\nwhose love to me For me doth make Thee languish?\n\nVerse 5\nLord, all my life I'll cleave to Thee,\nThy love fore'er beholding,\nThee ever, as Thou ever me,\nWith loving arms enfolding.\nYea, Thou shalt be my Beaconlight,\nTo guide me safe through death's dark night.\nAnd cheer my heart in sorrow;\nHenceforth myself and all that's mine To Thee, my Savior,\nI consign, From whom all things I borrow.\n\nVerse 6\nFrom morn till eve my theme shall be\nThy mercy's wondrous measure;\nTo sacrifice myself for Thee\nShall be my aim and pleasure.\nMy stream of life shall ever be\nA current flowing ceaselessly,\nThy constant praise outpouring.\nI'll treasure in my memory,\nO Lord, all Thou hast done for me,\nThy gracious love adoring.\n\nVerse 7\nEnlarge, my heart's own shrine, and swell,\nTo thee shall now be given\nA treasure that doth far excel\nThe worth of earth and heaven.\nAway with the Arabian gold,\nWith treasures of an earthly mold!\nI've found a better jewel.\nMy priceless treasure, Lord my God,\nIs Thy most holy, precious blood,\nWhich flowed from wounds so cruel.\n\nVerse 8\nThis treasure ever I'll employ,\nThis every aid shall yield me;\nIn sorrow it shall be my joy,\nIn conflict it shall shield me;\nIn joy, the music of my feast,\nAnd when all else has lost its zest,\nThis manna still shall feed me;\nIn thirst my drink; in want my food;\nMy company in solitude,\nTo comfort and to lead me.\n\nVerse 9\nOf death I am no more afraid,\nNew life from Thee is flowing;\nThy cross affords me cooling shade\nWhen noonday's sun is glowing.\nWhen by my grief I am oppressed,\nOn Thee my weary soul shall rest\nSerenely as on pillows.\nThou art my Anchor when by woe\nMy bark is driven to and fro\nOn trouble's surging billows.\n\nVerse 10\nAnd when Thy glory I shall see\nAnd taste Thy kingdom's pleasure,\nThy blood my royal robe shall be,\nMy joy beyond all measure.\nWhen I appear before Thy throne,\nThy righteousness shall be my crown-\nWith these I need not hide me.\nAnd there, in garments richly wrought\nAs Thine own bride, I shall be brought\nTo stand in joy beside Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10"],"source":"Open Hymnal Project"},{"id":"oh-a-mighty-fortress-is-our-god","title":"A Mighty Fortress Is Our God","language":"en","writers":"Martin Luther, 1529. Translation Frederic Henry Hedge","music":"Martin Luther","year":1529,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"EIN FESTE BURG (ISORHYTHMIC)","themes":["Hymn"],"lyrics":"Verse 1\nA mighty fortress is our God, a bulwark never failing;\nOur helper He, amid the flood of mortal ills prevailing:\nFor still our ancient foe doth seek to work us woe;\nHis craft and pow'r are great, and, armed with cruel hate,\nOn earth is not his equal.\n\nVerse 2\nDid we in our own strength confide, our striving would be losing;\nWere not the right Man on our side, the Man of God's own choosing:\nDost ask who that may be?\nChrist Jesus, it is He;\nLord Sabaoth, His name, from age to age the same,\nAnd He must win the battle.\n\nVerse 3\nAnd though this world, with devils filled, should threaten to undo us,\nWe will not fear, for God hath willed His truth to triumph through us:\nThe Prince of Darkness grim, we tremble not for him;\nHis rage we can endure, for lo, his doom is sure,\nOne little word shall fell him.\n\nVerse 4\nThat word above all earthly pow'rs, no thanks to them, abideth;\nThe Spirit and the gifts are ours through Him who with us sideth:\nLet goods and kindred go, this mortal life also;\nThe body they may kill:\nGod's truth abideth still,\nHis kingdom is forever.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-abide-o-dearest-jesus","title":"Abide, O Dearest Jesus","language":"en","writers":"Joshua Stegmann, 1628. Translated by August Crull","music":"Melchior Vulpius","year":1628,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"CHRISTUS DER IST MEIN LEBEN","themes":["Hymn"],"lyrics":"Verse 1\nAbide, O dearest Jesus,\nAmong us with Thy grace,\nThat Satan may not harm us,\nNor we to sin give place.\n\nVerse 2\nAbide, O dear Redeemer,\nAmong us with Thy Word,\nAnd thus now and hereafter True peace and joy afford.\n\nVerse 3\nAbide with heav'nly brightness Among us, precious Light;\nThy truth direct, and keep us From error's gloomy night.\n\nVerse 4\nAbide with richest blessings Among us, bounteous Lord;\nLet us in grace and wisdom Grow daily through Thy Word.\n\nVerse 5\nAbide with Thy protection Among us,\nLord, our Strength,\nLest world and Satan fell us And overcome at length.\n\nVerse 6\nAbide, O faithful Savior, Among us with Thy love;\nGrant steadfastness, and help us To reach our home above.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-abide-with-me","title":"Abide With Me","language":"en","writers":"Henry F. Lyte","music":"William H. Monk","year":1847,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"EVENTIDE","themes":["Hymn","Evening"],"lyrics":"Verse 1\nAbide with me; fast falls the eventide;\nThe darkness deepens; Lord with me abide.\nWhen other helpers fail and comforts flee,\nHelp of the helpless,\nO abide with me.\n\nVerse 2\nSwift to its close ebbs out life's little day;\nEarth's joys grow dim; its glories pass away;\nChange and decay in all around I see;\nO Thou who changest not, abide with me.\n\nVerse 3\nNot a brief glance I beg, a passing word;\nBut as Thou dwell'st with Thy disciples,\nLord, Familiar, condescending, patient, free.\nCome not to sojourn, but abide with me.\n\nVerse 4\nCome not in terrors, as the King of kings,\nBut kind and good, with healing in Thy wings,\nTears for all woes, a heart for every plea?\nCome, Friend of sinners, and thus bide with me.\n\nVerse 5\nThou on my head in early youth didst smile;\nAnd, though rebellious and perverse meanwhile,\nThou hast not left me, oft as I left Thee,\nOn to the close,\nO Lord, abide with me.\n\nVerse 6\nI need Thy presence every passing hour.\nWhat but Thy grace can foil the tempter's power?\nWho, like Thyself, my guide and stay can be?\nThrough cloud and sunshine, Lord, abide with me.\n\nVerse 7\nI fear no foe, with Thee at hand to bless;\nIlls have no weight, and tears no bitterness.\nWhere is death's sting? Where, grave, thy victory?\nI triumph still, if Thou abide with me.\n\nVerse 8\nHold Thou Thy cross before my closing eyes;\nShine through the gloom and point me to the skies.\nHeaven's morning breaks, and earth's vain shadows flee;\nIn life, in death, O Lord, abide with me.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-all-creatures-of-our-god-and-king","title":"All Creatures of Our God and King","language":"en","writers":"Francis of Assisi circa 1225. Translated by William H. Draper","music":"from Geistliche Kirchengesäng, Köln","year":1225,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"LASST UNS ERFREUEN","themes":["Hymn"],"lyrics":"Verse 1\nAll creatures of our God and King Lift up your voice and with us sing,\nAlleluia! Alleluia! Thou burning sun with golden beam,\nThou silver moon with softer gleam! O praise Him!\n\nChorus\nO praise Him! Alleluia! Alleluia! Alleluia!\n\nVerse 2\nThou rushing wind that art so strong\nYe clouds that sail in Heaven along,\nO praise Him! Alleluia!\nThou rising moon, in praise rejoice,\nYe lights of evening, find a voice!\n\nVerse 3\nThou flowing water, pure and clear,\nMake music for thy Lord to hear,\nO praise Him! Alleluia!\nThou fire so masterful and bright,\nThat givest man both warmth and light.\n\nVerse 4\nDear mother earth, who day by day Unfoldest blessings on our way,\nO praise Him! Alleluia!\nThe flowers and fruits that in thee grow,\nLet them His glory also show.\n\nVerse 5\nAnd all ye men of tender heart,\nForgiving others, take your part,\nO sing ye! Alleluia!\nYe who long pain and sorrow bear,\nPraise God and on Him cast your care!\n\nVerse 6\nAnd thou most kind and gentle Death,\nWaiting to hush our latest breath,\nO praise Him! Alleluia!\nThou leadest home the child of God,\nAnd Christ our Lord the way hath trod.\n\nVerse 7\nLet all things their Creator bless,\nAnd worship Him in humbleness,\nO praise Him! Alleluia!\nPraise, praise the Father, praise the Son,\nAnd praise the Spirit, Three in One!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus","Verse 7","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-all-depends-on-our-possessing","title":"All Depends On Our Possessing","language":"en","writers":"unknown circa 1673. Translated by Catherine Winkworth","music":"Johann Balthasar König","year":1673,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ALLES IST AN GOTTES SEGEN","themes":["Hymn"],"lyrics":"Verse 1\nAll depends on our possessing God's abundant grace and blessing,\nThough all earthly wealth depart.\nHe who trusts with faith unshaken In His\nGod is not forsaken And e'er keeps a dauntless heart.\n\nVerse 2\nHe who hitherto hath fed me And to many joys hath led me,\nIs and ever shall be mine.\nHe who did so gently school me,\nHe who still doth guide and rule me,\nWill remain my Help divine.\n\nVerse 3\nMany spend their lives in fretting\nOver trifles and in getting Things that have no solid ground.\nI shall strive to win a treasure\nThat will bring me lasting pleasure And that now is seldom found.\n\nVerse 4\nWhen with sorrow I am stricken,\nHope my heart anew will quicken,\nAll my longing shall be stilled.\nTo His loving-kindness tender Soul and body I surrender;\nFor in Him alone I build.\n\nVerse 5\nWell He knows what best to grant me;\nAll the longing hopes that haunt me,\nJoy and sorrow, have their day.\nI shall doubt His wisdom never,\nAs God wills, so be it ever,\nI to Him commit my way.\n\nVerse 6\nIf on earth my days He lengthen,\nHe my weary soul will strengthen;\nAll my trust in Him I place.\nEarthly wealth is not abiding,\nLike a stream away is gliding;\nSafe I anchor in His grace.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-all-glory-laud-and-honor","title":"All Glory, Laud, and Honor","language":"en","writers":"Theodulf of Orleans, circa 820. Translated by John Mason Neale","music":"Melchior Teschner","year":1851,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"VALET WILL ICH DIR GEBEN","themes":["Hymn"],"lyrics":"Verse 1\nAll glory, laud and honor,\nTo Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThou art the King of Israel,\nThou David's royal Son,\nWho in the Lord's Name comest,\nThe King and Blessed One.\n\nVerse 2\nAll glory, laud and honor,\nTo Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThe company of angels Are praising Thee on High,\nAnd mortal men and all things Created make reply.\n\nVerse 3\nAll glory, laud and honor,\nTo Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThe people of the Hebrews With palms before Thee went;\nOur prayer and praise and anthems Before Thee we present.\n\nVerse 4\nAll glory, laud and honor,\nTo Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nTo Thee, before Thy passion,\nThey sang their hymns of praise;\nTo Thee, now high exalted,\nOur melody we raise.\n\nVerse 5\nAll glory, laud and honor,\nTo Thee, Redeemer, King,\nTo Whom the lips of children Made sweet hosannas ring.\nThou didst accept their praises;\nAccept the prayers we bring,\nWho in all good delightest,\nThou good and gracious King.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-all-hail-the-power-of-jesus-name","title":"All Hail The Power Of Jesus' Name","language":"en","writers":"Edward Perronet","music":"Oliver Holden","year":1780,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"CORONATION","themes":["Hymn"],"lyrics":"Verse 1\nAll hail the pow'r of Jesus' Name!\nLet angels prostrate fall;\nBring forth the royal diadem, and crown Him Lord of all.\nBring forth the royal diadem, and crown Him Lord of all.\n\nVerse 2\nLet highborn seraphs tune the lyre, and as they tune it,\nfall Before His face Who tunes their choir, and crown Him Lord of all.\nBefore His face Who tunes their choir, and crown Him Lord of all.\n\nVerse 3\nCrown Him, ye morning stars of light, who fixed this floating ball;\nNow hail the strength of Israel's might, and crown Him Lord of all.\nNow hail the strength of Israel's might, and crown Him Lord of all.\n\nVerse 4\nCrown Him, ye martyrs of your God, who from His altar call;\nExtol the Stem of Jesse's Rod, and crown Him Lord of all.\nExtol the Stem of Jesse's Rod, and crown Him Lord of all.\n\nVerse 5\nYe seed of Israel's chosen race, ye ransomed from the fall,\nHail Him Who saves you by His grace, and crown Him Lord of all.\nHail Him Who saves you by His grace, and crown Him Lord of all.\n\nVerse 6\nHail Him, ye heirs of David's line, whom David Lord did call,\nThe God incarnate, Man divine, and crown Him Lord of all,\nThe God incarnate, Man divine, and crown Him Lord of all.\n\nVerse 7\nSinners, whose love can ne'er forget the wormwood and the gall,\nGo spread your trophies at His feet, and crown Him Lord of all.\nGo spread your trophies at His feet, and crown Him Lord of all.\n\nVerse 8\nLet every tribe and every tongue before Him prostrate fall\nAnd shout in universal song the crownèd Lord of all.\nAnd shout in universal song the crownèd Lord of all.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-all-my-heart-this-night-rejoices","title":"All My Heart This Night Rejoices","language":"en","writers":"Paul Gerhardt, 1656. Translated by Catherine Winkworth","music":"Johann Georg Ebeling","year":1656,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"EBELING","themes":["Hymn","Evening"],"lyrics":"Verse 1\nAll my heart this night rejoices,\nAs I hear, Far and near,\nSweetest angel voices; \"Christ is born,\" their choirs are singing,\nTill the air Ev'rywhere Now with joy is ringing.\n\nVerse 2\nFor it dawns,-the promised morrow Of His birth\nWho the earth Rescues from her sorrow.\nGod to wear our form descendeth,\nOf His grace To our race Here His Son He lendeth:\n\nVerse 3\nYea, so truly for us careth,\nThat His Son All we've done As our off'ring beareth;\nAs our Lamb who, dying for us,\nBears our load, And to God Doth in peace restore us.\n\nVerse 4\nHark! a voice from yonder manger,\nSoft and sweet, Doth entreat,\n\"Flee from woe and danger;\nBrethren come, from all doth grieve you You are freed,\nAll you need I will surely give you.\"\n\nVerse 5\nCome then, let us hasten yonder;\nHere let all, Great and small,\nKneel in awe and wonder.\nLove Him who with love is yearning;\nHail the Star That from far Bright with hope is burning!\n\nVerse 6\nYe who pine in weary sadness, Weep no more, For the door\nNow is found of gladness. Cling to Him for He will guide you\nWhere no cross, Pain or loss, Can again betide you.\n\nVerse 7\nHither come, ye heavy- hearted, Who for sin Deep within,\nLong and sore have smarted; For the poison'd wounds you're feeling\nHelp is near, One is here Mighty for their healing!\n\nVerse 8\nHither come, ye poor and wretched; Know His will Is to fill\nEvery hand outstretched; Here are riches without measure,\nHere forget All regret, Fill your hearts with treasure.\n\nVerse 9\nBlessed Savior, let me find Thee! Keep Thou me Close to Thee,\nCast me not behind Thee! Life of life, my heart Thou stillest,\nCalm I rest On Thy breast, All this void Thou fillest.\n\nVerse 10\nThee, dear Lord, with heed I'll cherish, Live to Thee, And with Thee\nDying, shall not perish; But shall dwell with Thee for ever,\nFar on high In the joy That can alter never.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10"],"source":"Open Hymnal Project"},{"id":"oh-all-praise-to-thee-my-god-this-night","title":"All Praise To Thee, My God, This Night","language":"en","writers":"Thomas Ken","music":"Canon' Thomas Tallis","year":1674,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"TALLIS","themes":["Hymn","Evening"],"lyrics":"Verse 1\nAll praise to Thee, my God, this night,\nFor all the blessings of the light!\nKeep me, O keep me,\nKing of kings, Beneath Thine own almighty wings.\n\nVerse 2\nForgive me, Lord, for Thy dear Son,\nThe ill that I this day have done,\nThat with the world, myself, and Thee,\nI, ere I sleep, at peace may be.\n\nVerse 3\nTeach me to live, that I may dread The grave as little as my bed.\nTeach me to die, that so I may Rise glorious at the judgment day.\n\nVerse 4\nO may my soul on Thee repose,\nAnd with sweet sleep mine eyelids close,\nSleep that may me more vig'rous make To serve my God when I awake.\n\nVerse 5\nWhen in the night I sleepless lie,\nMy soul with heav'nly thoughts supply;\nLet no ill dreams disturb my rest,\nNo pow'rs of darkness me molest.\n\nVerse 6\nO when shall I, in endless day,\nFor ever chase dark sleep away,\nAnd hymns divine with angels sing,\nAll praise to thee, eternal King?\n\nVerse 7\nPraise God, from Whom all blessings flow;\nPraise Him, all creatures here below;\nPraise Him above, ye heavenly host;\nPraise Father, Son, and Holy Ghost.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-all-praise-to-jesus-hallowed-name","title":"All Praise to Jesus' Hallowed Name","language":"en","writers":"verse 1, ancient German. verses 2-7, Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"ancient German found in Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"GELOBET SEIST DU","themes":["Hymn"],"lyrics":"Verse 1\nAll praise to Jesus' hallowed Name\nWho of virgin pure became True man for us!\nThe angels sing As the glad news to earth they bring. Hallelujah!\n\nVerse 2\nTh'Eternal Father's only Son For a manger leaves His throne\nDisguised in our poor flesh and blood See now the everlasting Good.\n\nVerse 3\nHe whom the world could not inwrap Yonder lies in Mary's lap;\nHe is become an infant small,\nWho by His might upholdeth all.\n\nVerse 4\nTh'Eternal Light, come down from heav'n,\nHath to us new sunshine giv'n;\nIt shineth in the midst of night,\nAnd maketh us the sons of light.\n\nVerse 5\nThe Father's Son, God ever-blest,\nIn the world became a guest;\nHe leads us from this vale of tears,\nAnd makes us in his kingdom heirs.\n\nVerse 6\nHe came to earth so mean and poor, Man to pity and restore,\nAnd make us rich in heaven above, Equal with angels through his love.\n\nVerse 7\nAll this He did to show His grace To our poor and sinful race;\nFor this let Christendom adore And praise His name for evermore.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-all-who-believe-and-are-baptized","title":"All Who Believe and Are Baptized","language":"en","writers":"Thomas Hansen Kingo, 1689. Translation by George Alfred Taylor Rygh, 1909, alt","music":"German circa 1400 from Etlich Christlich Lider, Wittenberg","year":1689,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"ES IST DAS HEIL UNS KOMMEN HER","themes":["Hymn"],"lyrics":"Verse 1\nAll who believe and are baptized shall see the Lord's salvation;\nbaptized into the death of Christ,\nthey are a new creation. through\nChrist's redemption they shall stand among the\nglorious heav'nly band of every tribe and nation.\n\nVerse 2\nWith one accord, O God, we pray: grant us thy Holy Spirit;\nlook thou on our infirmity through Jesus' blood and merit.\nGrant us to grow in grace each day that by this sacrament we may eternal life inherit.","arrangement":["Verse 1","Verse 2"],"source":"Open Hymnal Project"},{"id":"oh-alleluia-alleluia-hearts-to-heaven-and-voices-raise","title":"Alleluia, Alleluia! Hearts to Heaven and Voices Raise","language":"en","writers":"Christopher Wordsworth","music":"Ludwig van Beethoven; Adapted by Edward Hodges","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ODE TO JOY","themes":["Hymn"],"lyrics":"Verse 1\nAlleluia, alleluia! Hearts to Heav'n and voices raise:\nSing to God a hymn of gladness, sing to God a hymn of praise.\nHe, who on the cross a Victim, for the world's salvation bled,\nJesus Christ, the King of glory, now is risen from the dead.\n\nVerse 2\nNow the iron bars are broken,\nChrist from death to life is born,\nGlorious life, and life immortal, on the holy Easter morn.\nChrist has triumphed, and we conquer by His mighty enterprise:\nWe with Him to life eternal by His resurrection rise.\n\nVerse 3\nChrist is risen, Christ, the first fruits of the holy harvest field,\nWhich will all its full abundance at His second coming yield:\nThen the golden ears of harvest will their heads before Him wave,\nRipened by His glorious sunshine from the furrows of the grave.\n\nVerse 4\nChrist is risen, we are risen!\nShed upon us heav'nly grace,\nRain and dew and gleams of glory from the brightness of Thy face;\nThat we, with our hearts in Heaven, here on earth may fruitful be,\nAnd by angel hands be gathered, and be ever, Lord, with Thee.\n\nVerse 5\nAlleluia, alleluia! Glory be to God on high;\nAlleluia! to the Savior who has gained the victory;\nAlleluia! to the Spirit, fount of love and sanctity:\nAlleluia, alleluia! to the Triune Majesty.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-alleluia-sing-to-jesus","title":"Alleluia, Sing To Jesus!","language":"en","writers":"William Chatterton Dix","music":"Rowland H. Prichard","year":1867,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"HYFRYDOL","themes":["Hymn"],"lyrics":"Verse 1\nAlleluia! sing to Jesus!\nHis the scepter, His the throne.\nAlleluia! His the triumph,\nHis the victory alone.\nHark! the songs of peaceful Zion thunder like a mighty flood.\nJesus out of every nation has redeemed us by His blood.\n\nVerse 2\nAlleluia! not as orphans are we left in sorrow now;\nAlleluia! He is near us, faith believes, nor questions how;\nThough the cloud from sight received Him when the forty days were o'er\nShall our hearts forget His promise,\n\"I am with you evermore\"?\n\nVerse 3\nAlleluia! bread of angels,\nThou on earth our food, our stay;\nAlleluia! here the sinful flee to Thee from day to day:\nIntercessor, Friend of sinners,\nEarth's Redeemer, plead for me,\nWhere the songs of all the sinless sweep across the crystal sea.\n\nVerse 4\nAlleluia! King eternal, Thee the Lord of lords we own;\nAlleluia! born of Mary,\nEarth Thy footstool, Heaven Thy throne:\nThou within the veil hast entered,\nrobed in flesh our great High Priest;\nThou on earth both priest and victim in the Eucharistic feast.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-almighty-god-your-word-is-cast","title":"Almighty God Your Word Is Cast","language":"en","writers":"John Cawood","music":"William Croft","year":1816,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"ST. ANNE","themes":["Hymn"],"lyrics":"Verse 1\nAlmighty God, Your Word is cast Like seed into the ground;\nNow let the dew of Heav'n descend,\nAnd righteous fruits abound.\n\nVerse 2\nLet not the foe of Christ and man This holy seed remove,\nBut give it root in ev'ry heart To bring forth fruits of love.\n\nVerse 3\nLet not the world's deceitful cares The rising plant destroy.\nBut let it yield a hundredfold The fruits of peace and joy.\n\nVerse 4\nNor let Your Word so kindly sent\nTo raise us to Your throne Return to You,\nand sadly tell That we reject Your Son.\n\nVerse 5\nOft as the precious seed is sown,\nYour quick'ning grace bestow,\nThat all whose souls the truth receive,\nIts saving power may know.\n\nVerse 6\nGreat God, come down and on Your Word\nYour mighty power bestow,\nThat all who hear the joyful sound,\nYour saving grace may know.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-amazing-grace","title":"Amazing Grace","language":"en","writers":"John Newton, 1779. last verse author unknown, before","music":"James P. Carrell and David L. Clayton","year":1779,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"NEW BRITAIN","themes":["Hymn"],"lyrics":"Verse 1\nAmazing grace! How sweet the sound That saved a wretch like me!\nI once was lost, but now am found;\nWas blind, but now I see.\n\nVerse 2\n'Twas grace that taught my heart to fear,\nAnd grace my fears relieved;\nHow precious did that grace appear The hour I first believed.\n\nVerse 3\nThrough many dangers, toils and snares,\nI have already come;\n'Tis grace hath brought me safe thus far,\nAnd grace will lead me home.\n\nVerse 4\nThe Lord has promised good to me,\nHis Word my hope secures;\nHe will my Shield and Portion be,\nAs long as life endures.\n\nVerse 5\nYea, when this flesh and heart shall fail,\nAnd mortal life shall cease,\nI shall possess, within the veil,\nA life of joy and peace.\n\nVerse 6\nThe earth shall soon dissolve like snow,\nThe sun forbear to shine;\nBut God, Who called me here below,\nShall be forever mine.\n\nVerse 7\nWhen we've been there ten thousand years,\nBright shining as the sun,\nWe've no less days to sing God's praise\nThan when we'd first begun.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-and-can-it-be","title":"And Can It Be","language":"en","writers":"Charles Wesley","music":"Jeremiah Ingalls (1764-1828)","year":1738,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FILLMORE","themes":["Hymn"],"lyrics":"Verse 1\nAnd can it be that I should gain An interest in the Savior's blood?\nDied He for me, who caused His pain?\nFor me, who Him to death pursued?\nAmazing love! How can it be,\nThat Thou, my God, shouldst die for me?\n\nVerse 2\n'Tis mystery all: th'Immortal dies:\nWho can explore His strange design?\nIn vain the firstborn seraph tries To sound the depths of love divine.\n'Tis mercy all! Let earth adore,\nLet angel minds inquire no more.\n\nVerse 3\nHe left His Father's throne above So free, so infinite His grace?\nEmptied Himself of all but love,\nAnd bled for Adam's helpless race:\n'Tis mercy all, immense and free,\nFor O my God, it found out me!\n\nVerse 4\nLong my imprisoned spirit lay,\nFast bound in sin and nature's night;\nThine eye diffused a quick'ning ray?\nI woke, the dungeon flamed with light;\nMy chains fell off, my heart was free,\nI rose, went forth, and followed Thee.\n\nVerse 5\nStill the small inward voice I hear,\nThat whispers all my sins forgiv'n;\nStill the atoning blood is near,\nThat quenched the wrath of hostile Heav'n.\nI feel the life His wounds impart;\nI feel the Savior in my heart.\n\nVerse 6\nNo condemnation now I dread; Jesus, and all in Him, is mine;\nAlive in Him, my living Head, And clothed in righteousness divine,\nBold I approach th'eternal throne, And claim the crown, through Christ my own.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-angel-voices-ever-singing","title":"Angel Voices, Ever Singing","language":"en","writers":"Francis Pott","music":"Edwin G. Monk","year":1861,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"ANGEL VOICES (MONK)","themes":["Hymn"],"lyrics":"Verse 1\nAngel voices, ever singing, round Thy throne of light,\nAngel harps, forever ringing, rest not day or night;\nThousands only live to bless Thee, and confess Thee Lord of might.\n\nVerse 2\nThou Who art beyond the farthest mortal eye can scan,\nCan it be that Thou regardest songs of sinful man?\nCan we feel that Thou art near us and wilt hear us? Yea, we can.\n\nVerse 3\nLord, we know Thy love rejoices o'er each work of Thine;\nThou didst ears and hands and voices for Thy praise combine;\nCraftsman's art and music's measure for Thy pleasure didst design.\n\nVerse 4\nHere, great God, today we offer of Thine own to Thee;\nAnd for Thine acceptance proffer, all unworthily,\nHearts and minds, and hands and voices, in our choicest melody.\n\nVerse 5\nHonor, glory, might and merit,\nThine shall ever be,\nFather, Son, and Holy Spirit, blessed Trinity;\nOf the best that Thou hast given Earth and Heaven render Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-angels-from-the-realms-of-glory","title":"Angels From the Realms of Glory","language":"en","writers":"James Montgomery","music":"Henry Smart","year":1816,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"REGENT SQUARE","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nAngels from the realms of glory,\nWing your flight o'er all the earth;\nYe who sang creation's story Now proclaim Messiah's birth.\n\nChorus\nCome and worship, come and worship,\nWorship Christ, the newborn King.\n\nVerse 2\nShepherds, in the field abiding,\nWatching o'er your flocks by night,\nGod with us is now residing;\nYonder shines the infant light:\n\nVerse 3\nSages, leave your contemplations,\nBrighter visions beam afar;\nSeek the great Desire of nations;\nYe have seen His natal star.\n\nVerse 4\nSaints, before the altar bending,\nWatching long in hope and fear;\nSuddenly the Lord, descending,\nIn His temple shall appear.\n\nVerse 5\nSinners, wrung with true repentance,\nDoomed for guilt to endless pains,\nJustice now revokes the sentence,\nMercy calls you; break your chains.\n\nVerse 6\nThough an Infant now we view Him,\nHe shall fill His Father's throne,\nGather all the nations to Him;\nEvery knee shall then bow down:\n\nVerse 7\nAll creation, join in praising\nGod, the Father, Spirit, Son,\nEvermore your voices raising\nTo th'eternal Three in One.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus","Verse 7","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-angels-we-have-heard-on-high","title":"Angels We Have Heard On High","language":"en","writers":"French Carol; Translated by James Chadwick","music":"French carol melody","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"GLORIA","themes":["Hymn"],"lyrics":"Verse 1\nAngels we have heard on high Sweetly singing o'er the plains,\nAnd the mountains in reply Echoing their joyous strains.\n\nChorus\nGloria, in excelsis Deo!\nGloria, in excelsis Deo!\n\nVerse 2\nShepherds, why this jubilee?\nWhy your joyous strains prolong?\nWhat the gladsome tidings be Which inspire your heav'nly song?\n\nVerse 3\nCome to Bethlehem and see Christ Whose birth the angels sing;\nCome, adore on bended knee,\nChrist the Lord, the newborn King.\n\nVerse 4\nSee Him in a manger laid,\nWhom the choirs of angels praise;\nMary, Joseph, lend your aid,\nWhile our hearts in love we raise.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-as-with-gladness-men-of-old","title":"As With Gladness Men of Old","language":"en","writers":"William Chatterton Dix","music":"Conrad Kocher, 1838. Abridged by William Henry Monk","year":1860,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"DIX","themes":["Hymn"],"lyrics":"Verse 1\nAs with gladness,\nmen of old Did the guiding star behold\nAs with joy they hailed its light Leading onward,\nbeaming bright So, most glorious Lord, may we Evermore be led to Thee.\n\nVerse 2\nAs with joyful steps they sped To that lowly manger bed\nThere to bend the knee before Him whom Heav'n and earth adore;\nSo may we with willing feet Ever seek Thy mercy seat.\n\nVerse 3\nAs they offered gifts most rare At that manger rude and bare;\nSo may we with holy joy,\nPure and free from sin's alloy,\nAll our costliest treasures bring,\nChrist, to Thee, our heav'nly King.\n\nVerse 4\nHoly Jesus, ev'ry day Keep us in the narrow way;\nAnd, when earthly things are past,\nBring our ransomed souls at last Where they need no star to guide,\nWhere no clouds Thy glory hide.\n\nVerse 5\nIn the heav'nly country bright,\nNeed they no created light;\nThou its Light, its Joy, its Crown,\nThou its Sun which goes not down;\nThere forever may we sing Alleluias to our King!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-awake-my-heart-with-gladness","title":"Awake, My Heart, With Gladness","language":"en","writers":"Paul Gerhardt, 1648. Translated by John Kelly, 1867, alt","music":"Johann Crüger","year":1648,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"AUF, AUF, MEIN HERZ MIT FREUDEN","themes":["Hymn"],"lyrics":"Verse 1\nAwake, my heart, with gladness,\nSee what today is done;\nHow after gloom and sadness,\nComes forth the glorious Sun.\nMy Savior there was laid Where our bed must be made\nWhen to the realms of light Our spirit wings its flight.\n\nVerse 2\nThey in the grave did sink Him,\nThe foe held jubilee;\nBefore he can bethink him,\nLo! Christ again is free.\nAnd \"Victory\" He cries,\nAnd waving tow'rds the skies His banner,\nwhile the field Is by the Hero held!\n\nVerse 3\nUpon the grave is standing The Hero looking round;\nThe foe, no more withstanding,\nHis weapons on the ground Throws down,\nhis hellish pow'r To Christ must he give o'er,\nAnd to the Victor's bands Must yield his feet and hands.\n\nVerse 4\nA sight it is to gladden;\nAnd fill the heart with glee,\nNo more affright or sadden Shall aught,\nor take from me My trust or fortitude,\nOr any precious good The Savior bought for me\nIn sov'reign love and free.\n\nVerse 5\nHell and its prince, the devil,\nOf all their pow'rs are shorn;\nNow I am safe from evil,\nAnd sin I laugh to scorn.\nGrim Death with all his might Cannot my soul affright;\nHe is a pow'rless form,\nHowe'er he rage and storm.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-awake-my-soul-and-with-the-sun","title":"Awake, My Soul, And With The Sun","language":"en","writers":"Thomas Ken","music":"Genevan Psalter, attr. Louis Bourgeois","year":1674,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"OLD 100TH","themes":["Hymn"],"lyrics":"Verse 1\nAwake, my soul, and with the sun Thy daily stage of duty run;\nShake off dull sloth, and joyful rise,\nTo pay thy morning sacrifice.\n\nVerse 2\nThy precious time misspent, redeem,\nEach present day thy last esteem,\nImprove thy talent with due care;\nFor the great day thyself prepare.\n\nVerse 3\nBy influence of Light divine Let thy own light to others shine.\nReflect all Heaven's propitious ways In ardent love,\nand cheerful praise.\n\nVerse 4\nIn conversation be sincere;\nKeep conscience as the noontide clear;\nThink how all seeing God thy ways And all thy secret thoughts surveys.\n\nVerse 5\nWake, and lift up thyself, my heart,\nAnd with the angels bear thy part,\nWho all night long unwearied sing High praise to the eternal King.\n\nVerse 6\nAll praise to Thee, Who safe has kept\nAnd hast refreshed me while I slept\nGrant, Lord, when I from death shall wake\nI may of endless light partake.\n\nVerse 7\nHeav'n is, dear Lord, where'er Thou art,\nO never then from me depart;\nFor to my soul 'tis hell to be\nBut for one moment void of Thee.\n\nVerse 8\nLord, I my vows to Thee renew;\nDisperse my sins as morning dew.\nGuard my first springs of thought and will,\nAnd with Thyself my spirit fill.\n\nVerse 9\nDirect, control, suggest, this day,\nAll I design, or do, or say,\nThat all my powers, with all their might,\nIn Thy sole glory may unite.\n\nVerse 10\nI would not wake nor rise again\nAnd Heaven itself I would disdain,\nWert Thou not there to be enjoyed,\nAnd I in hymns to be employed.\n\nVerse 11\nPraise God, from Whom all blessings flow;\nPraise Him, all creatures here below;\nPraise Him above, ye heavenly host;\nPraise Father, Son, and Holy Ghost.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11"],"source":"Open Hymnal Project"},{"id":"oh-baptized-into-thy-name-most-holy","title":"Baptized Into Thy Name Most Holy","language":"en","writers":"Johann Jakob Rambach, 1734. Translated by Catherine Winkworth, 1863 and August Crull","music":"Kornelius Heinrich Dretzel","year":1734,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"O DASS ICH TAUSEND ZUNGEN HÄTTE (DRETZEL)","themes":["Hymn"],"lyrics":"Verse 1\nBaptized into Thy Name most holy,\nO Father, Son, and Holy Ghost,\nI claim a place, though weak and lowly,\nAmong Thy seed, Thy chosen host.\nBuried with Christ and dead to sin,\nThy Spirit now shall live within.\n\nVerse 2\nMy loving Father,\nhere doth take me To be henceforth His child and heir;\nMy faithful Savior,\nnow doth make me The fruit of all His sorrows share;\nMy Comforter will comfort me When darkest clouds around I see.\n\nVerse 3\nAnd I have vowed to fear and love Thee And to obey Thee,\nLord, alone; I felt Thy Holy Spirit move me,\nI dared to pledge myself Thine own,\nRenouncing sin to keep the faith And war with evil unto death.\n\nVerse 4\nMy faithful God, Thou failest never,\nThy cov'nant surely will abide;\nOh, cast me not away forever Should I transgress it on my side!\nBut if I fall hide not Thy face,\nRestore Thy child, Lord, by Thy Grace.\n\nVerse 5\nYes, all I am and love most dearly,\nTo Thee I offer now the whole;\nO let me make my vows sincerely,\nTake full possession of my soul!\nLet naught within me, naught I own,\nServe any will save Thine alone.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-be-still-my-soul","title":"Be Still My Soul","language":"en","writers":"Katharina A. von Schlegel, 1752. Translated by Jane L. Borthwick","music":"Jean Sibelius","year":1752,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FINLANDIA","themes":["Hymn"],"lyrics":"Verse 1\nBe still, my soul: the Lord is on thy side.\nBear patiently the cross of grief or pain.\nLeave to thy God to order and provide;\nIn every change, He faithful will remain.\nBe still, my soul: thy best,\nthy heav'nly Friend Through thorny ways leads to a joyful end.\n\nVerse 2\nBe still, my soul:\nthy God doth undertake To guide the future, as He has the past.\nThy hope, thy confidence let nothing shake;\nAll now mysterious shall be bright at last.\nBe still, my soul:\nthe waves and winds still know His voice\nWho ruled them while He dwelt below.\n\nVerse 3\nBe still, my soul: when dearest friends depart,\nAnd all is darkened in the vale of tears,\nThen shalt thou better know His love,\nHis heart, Who comes to soothe thy sorrow and thy fears.\nBe still, my soul:\nthy Jesus can repay From His own fullness all He takes away.\n\nVerse 4\nBe still, my soul:\nthe hour is hast'ning on When we shall be forever with the Lord.\nWhen disappointment, grief and fear are gone,\nSorrow forgot, love's purest joys restored.\nBe still, my soul:\nwhen change and tears are past\nAll safe and blessèd we shall meet at last.\n\nVerse 5\nBe still, my soul: begin the song of praise On earth,\nbelieving, to Thy Lord on high;\nAcknowledge Him in all thy words and ways,\nSo shall He view thee with a well pleased eye.\nBe still, my soul:\nthe Sun of life divine\nThrough passing clouds shall but more brightly shine.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-be-thou-my-vision","title":"Be Thou My Vision","language":"en","writers":"Attr. Dallan Forgaill, 8th Century. Translated by Mary Byrne, 1905 and Eleanor Hull","music":"Traditional Irish","year":1905,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"SLANE","themes":["Hymn"],"lyrics":"Verse 1\nBe Thou my Vision,\nO Lord of my heart;\nNaught be all else to me, save that Thou art.\nThou my best Thought, by day or by night,\nWaking or sleeping, Thy presence my light.\n\nVerse 2\nBe Thou my Wisdom, and Thou my true Word;\nI ever with Thee and Thou with me,\nLord; Thou my great Father, and I Thy true son;\nThou in me dwelling, and I with Thee one.\n\nVerse 3\nBe Thou my battle Shield,\nSword for the fight;\nBe Thou my Dignity,\nThou my Delight; Thou my soul's Shelter,\nThou my high Tower:\nRaise Thou me heav'nward,\nO Pow'r of my pow'r.\n\nVerse 4\nRiches I heed not, nor man's empty praise,\nThou mine Inheritance, now and always:\nThou and Thou only, be first in my heart,\nHigh King of Heaven, my Treasure Thou art.\n\nVerse 5\nHigh King of Heaven, my victory won,\nMay I reach Heav'ns joys,\nO bright Heaven's Sun!\nHeart of my own heart, whatever befall,\nStill be my Vision,\nO Ruler of all.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-beautiful-savior","title":"Beautiful Savior","language":"en","writers":"German Jesuits, published 1677. Translated by Joseph A. Seiss","music":"s Hymn' Silesian folk song","year":1677,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"CRUSADER","themes":["Hymn"],"lyrics":"Verse 1\nBeautiful Savior, King of Creation Son of God and Son of Man!\nTruly I'd love Thee, truly I'd serve Thee,\nLight of my soul, my joy, my crown.\n\nVerse 2\nFair are the meadows,\nFair are the woodlands,\nRobed in the flow'rs of blooming spring;\nJesus is fairer, Jesus is purer,\nHe makes our sorr'wing spirit sing.\n\nVerse 3\nFair is the sunshine,\nFair is the moonlight,\nBright the sparkling stars on high;\nJesus shines brighter,\nJesus shines purer Than all the angels in the sky.\n\nVerse 4\nBeautiful Savior, Lord of the nations,\nSon of God and Son of Man!\nGlory and honor, Praise, adoration Now and forevermore be Thine!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-behold-a-host-arrayed-in-white","title":"Behold, A Host, Arrayed in White","language":"en","writers":"Hans Adolf Brorson, circa 1760. Translation composite","music":"traditional Norwegian, 17th cent","year":1760,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"DEN STORE HVIDE FLOK","themes":["Hymn"],"lyrics":"Verse 1\nBehold a host, arrayed in white,\nLike thousand snow clad mountains bright,\nWith palms they stand.\nWho is this band Before the throne of light?\nLo, these are they of glorious fame Who from the great affliction came\nAnd in the flood of Jesus' blood Are cleansed from guilt and blame.\nNow gathered in the holy place Their voices they in worship raise,\nTheir anthems swell where God doth dwell,\nMid angels song of praise.\n\nVerse 2\nDespised and scorned, they sojourned here;\nBut now, how glorious they appear!\nThose martyrs stand a priestly band,\nGod's throne forever near.\nSo oft, in troubled days gone by,\nIn anguish they would weep and sigh.\nAt home above the God of Love For aye their tears shall dry.\nThey now enjoy their Sabbath rest,\nThe paschal banquet of the blest;\nThe Lamb, their Lord, at festal board Himself is Host and Guest.\n\nVerse 3\nThen hail, ye mighty legions, yea,\nAll hail! Now safe and blest for aye,\nAnd praise the Lord, who with His Word Sustained you on the way.\nYe did the joys of earth disdain,\nYe toiled and sowed in tears and pain.\nFarewell, now bring your sheaves and sing Salvation's glad refrain.\nSwing high your palms, lift up your song,\nYea, make it myriad voices strong.\nEternally shall praise to Thee,\nGod, and the Lamb belong.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-beneath-the-cross-of-jesus","title":"Beneath The Cross Of Jesus","language":"en","writers":"Elizabeth C. Clephane","music":"Frederick C. Maker","year":1868,"rights":"public-domain","copyright":"Public domain","defaultKey":"Db","bpm":null,"tune":"ST. CHRISTOPHER","themes":["Hymn","Lent"],"lyrics":"Verse 1\nBeneath the cross of Jesus I fain would take my stand,\nThe shadow of a mighty rock within a weary land;\nA home within the wilderness, a rest upon the way,\nFrom the burning of the noontide heat, and the burden of the day.\n\nVerse 2\nO safe and happy shelter,\nO refuge tried and sweet,\nO trysting place where Heaven's love and Heaven's justice meet!\nAs to the holy patriarch that wondrous dream was giv'n,\nSo seems my Savior's cross to me, a ladder up to heav'n.\n\nVerse 3\nThere lies beneath its shadow but on the further side\nThe darkness of an awful grave that gapes both deep and wide\nAnd there between us stands the cross two arms outstretched to\nsave A watchman set to guard the way from that eternal grave.\n\nVerse 4\nUpon that cross of Jesus mine eye at times can see\nThe very dying form of One Who suffered there for me;\nAnd from my stricken heart with tears two wonders I confess;\nThe wonders of redeeming love and my unworthiness.\n\nVerse 5\nI take, O cross, thy shadow for my abiding place;\nI ask no other sunshine than the sunshine of His face;\nContent to let the world go by to know no gain or loss,\nMy sinful self my only shame, my glory all the cross.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-blessed-assurance","title":"Blessed Assurance","language":"en","writers":"Fanny Crosby","music":"Phoebe P. Knapp","year":1873,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"BLESSED ASSURANCE","themes":["Hymn"],"lyrics":"Verse 1\nBlessèd assurance, Jesus is mine!\nO what a foretaste of glory divine!\nHeir of salvation, purchase of God,\nBorn of His Spirit, washed in His blood.\n\nChorus\nThis is my story, this is my song,\nPraising my Savior, all the day long;\nThis is my story, this is my song,\nPraising my Savior, all the day long.\n\nVerse 2\nPerfect submission, perfect delight,\nVisions of rapture now burst on my sight;\nAngels descending bring from above Echoes of mercy, whispers of love.\n\nVerse 3\nPerfect submission, all is at rest I in my Savior am happy and blest,\nWatching and waiting, looking above,\nFilled with His goodness, lost in His love.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-blessed-jesus-at-thy-word","title":"Blessed Jesus at Thy Word","language":"en","writers":"verses 1-3, Tobias Clausnitzer, 1663. verse 4, unknown author. Translated by Catherine Winkworth","music":"Johann Rudolph Ahle","year":1663,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"LIEBSTER JESU WIR SIND HIER","themes":["Hymn"],"lyrics":"Verse 1\nBlessed Jesus, at Thy Word We are gathered all to hear Thee;\nLet our hearts and souls be stirred\nNow to seek and love and fear Thee,\nBy Thy teachings sweet and holy,\nDrawn from earth to love Thee solely.\n\nVerse 2\nAll our knowledge, sense, and sight Lie in deepest darkness shrouded,\nTil Thy Spirit breaks our night With the beams of truth unclouded;\nThou alone to God canst win us;\nThou must work all good within us.\n\nVerse 3\nGlorious Lord, Thyself impart!\nLight of light, from God proceeding,\nOpen Thou our ears and heart;\nHelp us by Thy Spirit's pleading;\nHear the cry Thy people raises;\nHear and bless our prayers and praises.\n\nVerse 4\nFather, Son, and Holy Ghost,\nPraise to Thee and adoration!\nGrant that we Thy Word may trust And obtain true consolation,\nWhile we here below must wander,\nTill we sing Thy praises yonder.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-blest-be-the-tie-that-binds","title":"Blest Be The Tie That Binds","language":"en","writers":"John Fawcett","music":"Lowell Mason","year":1782,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"BOYLSTON","themes":["Hymn"],"lyrics":"Verse 1\nBlest be the tie that binds Our hearts in Christian love;\nThe fellowship of kindred minds Is like to that above.\n\nVerse 2\nBefore our Father's throne We pour our ardent prayers;\nOur fears, our hopes, our aims are one Our comforts and our cares.\n\nVerse 3\nWe share each other's woes,\nOur mutual burdens bear;\nAnd often for each other flows The sympathizing tear.\n\nVerse 4\nWhen we asunder part,\nIt gives us inward pain;\nBut we shall still be joined in heart,\nAnd hope to meet again.\n\nVerse 5\nThis glorious hope revives Our courage by the way;\nWhile each in expectation lives,\nAnd longs to see the day.\n\nVerse 6\nFrom sorrow, toil and pain,\nAnd sin, we shall be free,\nAnd perfect love and friendship reign\nThrough all eternity.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-blind-bartimaeus","title":"Blind Bartimaeus","language":"en","writers":"Henry Wadsworth Longfellow, alt","music":"Jeremiah Ingalls (1764-1828)","year":1842,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FILLMORE","themes":["Hymn"],"lyrics":"Verse 1\nBlind Bartimaeus at the gates Of Jericho in darkness waits:\nHe hears the crowd;\nhe hears a breath say \"It is Christ of\nNazareth!\" And calls in tones of agony,\n\"O Jesus, Jesus pity me!\"\n\nVerse 2\nThe thronging multitudes increase \"Blind Bartimaeus,\nhold thy peace!\" But still, above the noisy crowd,\nThe blind man's cry is shrill and loud:\nUntil they say, \"He calleth thee;\nCourage! arise! He calleth thee!\"\n\nVerse 3\nThen saith the Christ, as silent stands The crowd,\n\"What wilt thou at My hands?\" And he replies,\n\"O give me light!\nRabbi, restore the blind man's sight.\" And Jesus answers,\n\"Go thy way, Thy faith, thy faith hath savèd thee.\"\n\nVerse 4\nYe that hath eyes and cannot see,\nIn darkness and in misery,\nRecall those mighty voices three-\"O Jesus,\nJesus pity me!\" \"Courage! arise!\nHe calleth thee!\" \"Thy faith, thy faith hath savèd thee.\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-breathe-on-me-breath-of-god","title":"Breathe on Me, Breath of God","language":"en","writers":"Edwin Hatch","music":"found in John Chetham's Psalmody","year":1878,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"AYLESBURY","themes":["Hymn"],"lyrics":"Verse 1\nBreathe on me, breath of God,\nFill me with life anew,\nThat I may love what Thou dost love,\nAnd do what Thou wouldst do.\n\nVerse 2\nBreathe on me, breath of God,\nUntil my heart is pure,\nUntil with Thee I will one will,\nTo do and to endure.\n\nVerse 3\nBreathe on me, breath of God,\nSo shall I never die,\nBut live with Thee the perfect life Of Thine eternity.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-built-on-the-rock","title":"Built on the Rock","language":"en","writers":"Nikolai F. S. Grundtvig, 1857. Translated Carl Døving","music":"Ludvig M. Lindeman","year":1857,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"KIRKEN DEN ER ET GAMMELT HUS","themes":["Hymn"],"lyrics":"Verse 1\nBuilt on the Rock the church doth stand,\nEven when steeples are falling;\nCrumbled have spires in every land,\nBells still are chiming and calling;\nCalling the young and old to rest,\nBut above all the soul distressed,\nLonging for rest everlasting.\n\nVerse 2\nSurely in temples made with hands,\nGod, the Most High, is not dwelling;\nHigh above earth His temple stands,\nAll earthly temples excelling;\nYet He whom heav'ns cannot contain Chose to abide on earth with men,\nBuilt in our bodies His temple.\n\nVerse 3\nWe are God's house of living stones,\nBuilt for His own habitation;\nHe through baptismal grace us owns,\nHeirs of His wondrous salvation;\nWere we but two His Name to tell,\nYet He would deign with us to dwell,\nWith all His grace and His favor.\n\nVerse 4\nNow we may gather with our King;\nEv'n in the lowliest dwelling:\nPraises to Him we there may bring,\nHis wondrous mercy foretelling;\nJesus His grace to us accords,\nSpirit and life are all His words,\nHis truth doth hallow the temple.\n\nVerse 5\nStill we our earthly temples rear,\nThat we may herald His praises;\nThey are the homes where He draws near And little children embraces,\nBeautiful things in them are said,\nGod there with us His cov'nant made,\nMaking us heirs of His kingdom.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-by-grace-i-m-saved","title":"By Grace I'm Saved","language":"en","writers":"Christian L. Scheidt, 1742. Translated by Matthias Loy, (1828-1915)","music":"Johann Balthasar König","year":1742,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"O DASS ICH TANSEND ZUNGEN","themes":["Hymn"],"lyrics":"Verse 1\nBy grace I'm saved-grace free and boundless!\nMy heart, believ'st thou this or not?\nWhy tremblest thou with terror groundless?\nHas ever God a falsehood taught?\nHis Word is truethen this must be:\nBy grace there is a crown for thee.\n\nVerse 2\nBy grace! our works are all rejected,\nAll claims of merit pass for naught;\nThe mighty Savior, long expected,\nTo us this blissful truth has brought,\nThat He by death redeems our race,\nAnd we are saved alone by grace.\n\nVerse 3\nBy grace! mark well this phrase's meaning,\nWhen sin rolls sorrows o'er thy breast,\nWhen Satan threats with pride o'erweening,\nWhen troubled conscience sighs for rest:\nWhat reason ne'er can comprehend It pleases God by grace to send.\n\nVerse 4\nBy grace His Son, on earth appearing,\nVouchsafed beneath thy woe to bend;\nHadst thou, damnation justly fearing,\nDone aught to render Him thy friend?\nWas't not that He thy welfare sought,\nAnd but by grace deliv'rance wrought?\n\nVerse 5\nBy grace! this ground of our salvation As long as God is true endures:\nWhat saints have penned by inspiration,\nWhat God to our poor soul secures,\nWhat all our faith must rest upon,\nIs grace, free grace through His dear Son.\n\nVerse 6\nBy grace! but think not, thou who livest\nSecurely on in godless ways,\nThat thou, though all are called, receivest\nThe promised rest that wakes our praise:\nBy grace none find in heaven a place\nWho live in sin in hope of grace.\n\nVerse 7\nBy grace! They who have heard this sentence\nMust bid hypocrisy farewell;\nFor only after deep repentance\nThe soul what grace imports can tell;\nTo sin while grace a trifle seems,\nTo faith it bright with glory beams.\n\nVerse 8\nBy grace the timid hearts that languish,\nFind access to the Father's heart,\nWhen conflicts fierce and bitter anguish\nBid all their joy and hopes depart.\nWhere, oftimes, should I strength obtain,\nBid grace my anchor not remain!\n\nVerse 9\nBy grace! on this in death I'll rest me,\nRejoicing e'en though feeling naught;\nI know my sin it oft oppressed me\nBut Him, too, who my soul hath bought:\nMy heart exults grief flees apace\nBecause my soul is saved by grace.\n\nVerse 10\nBy grace! O sin and Satan hear it!\nI bear my flag of faith in hand,\nAnd pass, in spite of doubts, nor fear it,\nThe Red Sea to the promised land;\nI hold the word my Savior taught\nAs certain, whether felt or not.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10"],"source":"Open Hymnal Project"},{"id":"oh-christ-arose","title":"Christ Arose","language":"en","writers":"Robert Lowry","music":"Robert Lowry","year":1874,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CHRIST AROSE","themes":["Hymn","Easter"],"lyrics":"Verse 1\nLow in the grave He lay Jesus my Savior!\nWaiting the coming day — Jesus my Lord!\nUp from the grave He arose,\nWith a mighty triumph o'er His\n\nChorus\nfoes; He arose a Victor from the dark domain,\nAnd He lives forever with His saints to reign.\nHe arose! He arose! Hallelujah! Christ arose!\n\nVerse 2\nVainly they watch His bed — Jesus my Savior!\nVainly they seal the dead — Jesus my Lord!\n\nVerse 3\nDeath cannot keep his prey — Jesus my Savior!\nHe tore the bars away — Jesus my Lord!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-christ-jesus-lay-in-death-s-strong-bands","title":"Christ Jesus Lay In Death's Strong Bands","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CHRIST LAG IN TOBES BANDEN","themes":["Hymn"],"lyrics":"Verse 1\nChrist Jesus lay in death's strong bands,\nFor our offenses given;\nBut now at God's right hand He stands,\nAnd brings us life from Heaven.\nWherefore let us joyful be,\nAnd sing to God right thankfully Loud songs of Alleluia! Alleluia!\n\nVerse 2\nNo son of man could conquer Death,\nSuch mischief sin had wrought us,\nFor innocence dwelt not on earth,\nAnd therefore Death had brought us Into thralldom from of old\nAnd ever grew more strong and bold\nAnd kept us in his bondage. Alleluia!\n\nVerse 3\nBut Jesus Christ, God's only Son,\nTo our low state descended,\nThe cause of Death He has undone,\nHis power forever ended,\nRuined all his right and claim And left him nothing but the name,\nHis sting is lost forever. Alleluia!\n\nVerse 4\nIt was a strange and dreadful strife When life and death contended;\nThe victory remained with life;\nThe reign of death was ended.\nStripped of power, no more it reigns,\nAn empty form alone remains Death's sting is lost forever! Alleluia!\n\nVerse 5\nHere the true Paschal Lamb we see,\nWhom God so freely gave us;\nHe died on the accursed tree So strong His love! to save us.\nSee, His blood doth mark our door;\nFaith points to it,\nDeath passes o'er, And Satan cannot harm us. Alleluia!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-christ-returneth","title":"Christ Returneth","language":"en","writers":"H. L. Turner","music":"James McGranahan","year":1878,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"CHRIST RETURNETH","themes":["Hymn"],"lyrics":"Verse 1\nIt may be at morn, when the day is awaking,\nWhen sunlight through darkness and shadow is breaking That\nJesus will come in the fullness of glory\nTo receive from the world \"His own.\"\n\nChorus\nO Lord Jesus, how long, how long Ere we shout the glad song,\nChrist returneth! Hallelujah! Hallelujah! Amen. Hallelujah! Amen.\n\nVerse 2\nIt may be at midday, it may be at twilight,\nIt may be, perchance,\nthat the blackness of midnight\nWill burst into light in the blaze of His glory,\nWhen Jesus receives \"His own.\"\n\nVerse 3\nWhile hosts cry Hosanna, from heaven descending,\nWith glorified saints and the angels attending,\nWith grace on His brow, like a halo of glory,\nWill Jesus receive \"His own.\"\n\nVerse 4\nOh, joy! oh, delight! should we go without dying,\nNo sickness, no sadness, no dread and no crying.\nCaught up through the clouds with our Lord into glory,\nWhen Jesus receives \"His own.\"","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-christ-the-lord-is-risen-today-lyra","title":"Christ The Lord Is Risen Today (Lyra)","language":"en","writers":"Stanzas 1-7, Charles Wesley, 1739. Stanzas 8-10, 14th Century; translated in Lyra Davidica","music":"Robert Williams","year":1739,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"LLANFAIR","themes":["Hymn","Easter"],"lyrics":"Verse 1\nChrist, the Lord, is risen today,\nAlleluia! Sons of men and angels say,\nAlleluia! Raise your joys and triumphs high,\nAlleluia! Sing, ye heavens, and earth, reply, Alleluia!\n\nVerse 2\nLove's redeeming work is done,\nAlleluia! Fought the fight, the battle won,\nAlleluia! Lo! the Sun's eclipse is o'er,\nAlleluia! Lo! He sets in blood no more, Alleluia!\n\nVerse 3\nVain the stone, the watch, the seal,\nAlleluia! Christ hath burst the gates of hell,\nAlleluia! Death in vain forbids His rise,\nAlleluia! Christ hath opened paradise, Alleluia!\n\nVerse 4\nLives again our glorious King,\nAlleluia! Where, O death, is now thy sting?\nAlleluia! Once He died our souls to save,\nAlleluia! Where thy victory, O grave? Alleluia!\n\nVerse 5\nSoar we now where Christ hath led,\nAlleluia! Following our exalted Head,\nAlleluia! Made like Him, like Him we rise,\nAlleluia! Ours the cross, the grave, the skies, Alleluia!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-come-down-o-love-divine","title":"Come Down, O Love Divine","language":"en","writers":"Bianco of Siena d. 1434. Translated by Richard F. Littledale","music":"Ralph Vaughan Williams","year":1434,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"DOWN AMPNEY","themes":["Hymn"],"lyrics":"Verse 1\nCome down, O love divine, seek Thou this soul of mine,\nAnd visit it with Thine own ardor glowing.\nO Comforter, draw near, within my heart appear,\nAnd kindle it, Thy holy flame bestowing.\n\nVerse 2\nO let it freely burn,\ntil earthly passions turn To dust and ashes in its heat consuming;\nAnd let Thy glorious light shine ever on my sight,\nAnd clothe me round, the while my path illuming.\n\nVerse 3\nLet holy charity mine outward vesture be,\nAnd lowliness become mine inner clothing;\nTrue lowliness of heart, which takes the humbler part,\nAnd o'er its own shortcomings weeps with loathing.\n\nVerse 4\nAnd so the yearning strong, with which the soul will long,\nShall far outpass the pow'r of human telling;\nFor none can guess its grace,\ntill he become the place Wherein the Holy Spirit makes His dwelling.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-come-god-creator-holy-ghost","title":"Come, God Creator, Holy Ghost","language":"en","writers":"variously ascribed to Ambrose, Gregory the Great, Charlemagne, or Rhabanus Maurus. Translated by Martin Luther, 1524. Translated from German to English by Leonard Woolsey Bacon","music":"ancient Latin found in Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"KOMM, GOTT SCHOEPFER HEILIGER GEIST","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nCome, God Creator, Holy Ghost,\nAnd visit Thou these souls of men;\nFill them with graces, as Thou dost,\nThy creatures make pure again.\n\nVerse 2\nFor Comforter Thy name we call.\nSweet gift of God most high above,\nA holy unction to us all O Fount of life, Fire of love.\n\nVerse 3\nOur minds illumine and refresh,\nDeep in our hearts let love burn bright;\nThou know'st the weakness of our flesh;\nAnd strengthen us with Thy might.\n\nVerse 4\nThou with Thy wondrous sev'nfold gifts\nThe finger art of God's right hand;\nThe Father's Word Thou sendest swift On tongues of fire to each land.\n\nVerse 5\nDrive far from us our wily foe;\nGrant us Thy blesséd peace within,\nThat in Thy footsteps we may go,\nAnd shun the dark ways of sin.\n\nVerse 6\nTeach us the Father well to know,\nLikewise His only Son our Lord,\nThyself to us believing show,\nSpirit of both, aye adored\n\nVerse 7\nPraise to the Father, and the Son\nWho from the dead is risen again;\nPraise to the Comforter be done\nBoth now and ever. Amen.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-come-holy-spirit-lord-our-god","title":"Come Holy Spirit, Lord Our God","language":"en","writers":"v. 1 ancient Latin. v.2-3 Martin Luther, 1524. Translated by Arthur Tozel Russell (1806-1874)","music":"ancient Latin found in Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"KOMM HEILIGER GEIST, HERRE GOTT","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nCome, Holy Spirit, Lord our God,\nAnd pour Thy gifts of grace abroad;\nThy faithful people fill with blessing,\nLove's fire their hearts possessing.\nO Lord, Thou by Thy heav'nly Light Dost gather and in faith unite\nThrough all the world a holy nation To sing to Thee with exultation,\n\nChorus\nHallelujah! Hallelujah!\n\nVerse 2\nO, holiest Light! O Rock adored!\nGive us Thy light,\nThy living Word, To God Himself our spirits leading,\nWith Him as children pleading.\nFrom error, Lord, our souls defend,\nThat they on Christ alone attend;\nIn Him with faith unfeigned abiding,\nIn Him with all their might confiding.\n\nVerse 3\nO holiest Fire! O Source of rest!\nGrant that with joy and hope possest,\nAnd in Thy service kept forever,\nNaught us from Thee may sever.\nLord, may Thy pow'r prepare each heart;\nTo our weak nature strength impart,\nOnward to press, our foes defying,\nTo Thee, through living and through dying.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-come-thou-fount-of-every-blessing","title":"Come Thou Fount Of Every Blessing","language":"en","writers":"Robert Robinson","music":"Asahel Nettleton","year":1758,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"NETTLETON","themes":["Hymn"],"lyrics":"Verse 1\nCome, Thou Fount of every blessing,\nTune my heart to sing Thy grace;\nStreams of mercy, never ceasing,\nCall for songs of loudest praise.\nTeach me some melodious sonnet,\nSung by flaming tongues above.\nPraise the mount! I'm fixed upon it,\nMount of Thy redeeming love.\n\nVerse 2\nSorr'wing I shall be in spirit,\nTill released from flesh and sin,\nYet from what I do inherit,\nHere Thy praises I'll begin;\nHere I raise my Ebenezer;\nHere by Thy great help I've come;\nAnd I hope, by Thy good pleasure,\nSafely to arrive at home.\n\nVerse 3\nJesus sought me when a stranger,\nWand'ring from the fold of God;\nHe, to rescue me from danger,\nInterposed His precious blood;\nHow His kindness yet pursues me Mortal tongue can never tell,\nClothed in flesh, till death shall loose me I cannot proclaim it well.\n\nVerse 4\nO to grace how great a debtor Daily I'm constrained to be!\nLet Thy goodness, like a fetter,\nBind my wand'ring heart to Thee.\nProne to wander, Lord,\nI feel it, Prone to leave the God I love;\nHere's my heart, O take and seal it,\nSeal it for Thy courts above.\n\nVerse 5\nO that day when freed from sinning,\nI shall see Thy lovely face;\nClothèd then in blood washed linen How I'll sing Thy sovereign grace;\nCome, my Lord, no longer tarry,\nTake my ransomed soul away;\nSend thine angels now to carry Me to realms of endless day.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-come-thou-long-expected-jesus","title":"Come, Thou Long-Expected Jesus","language":"en","writers":"Charles Wesley","music":"from \"Southern Harmony\", 1835, alt","year":1745,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"JEFFERSON","themes":["Hymn","Advent"],"lyrics":"Verse 1\nCome, Thou long expected Jesus Born to set Thy people free;\nFrom our fears and sins release us,\nLet us find our rest in Thee.\nIsrael's Strength and Consolation,\nHope of all the earth Thou art;\nDear Desire of every nation,\nJoy of every longing heart.\n\nVerse 2\nBorn Thy people to de liver,\nBorn a child and yet a King,\nBorn to reign in us forever,\nNow Thy gracious kingdom bring.\nBy Thine own eternal Spirit Rule in all our hearts alone;\nBy Thine all sufficient merit,\nRaise us to Thy glorious throne.","arrangement":["Verse 1","Verse 2"],"source":"Open Hymnal Project"},{"id":"oh-come-ye-disconsolate","title":"Come, Ye Disconsolate","language":"en","writers":"verses 1-2 Thomas Moore, 1816. Verse 3 Thomas Hastings","music":"Samuel Webbe","year":1816,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CONSOLATOR (WEBBE)","themes":["Hymn"],"lyrics":"Verse 1\nCome, ye disconsolate, wher'er ye languish;\nCome to the mercy seat, fervently kneel.\nHere bring your wounded hearts, here tell your anguish;\nEarth has no sorrow that Heav'n cannot heal.\n\nVerse 2\nJoy of the desolate, light of the straying,\nHope of the penitent, fadeless and pure,\nHere speaks the Comforter, tenderly saying,\n\"Earth has no sorrow that Heav'n cannot cure.\"\n\nVerse 3\nHere see the Bread of Life;\nsee waters flowing Forth from the throne of God, pure from above;\nCome to the feast of love; come,\never knowing Earth has no sorrow but Heav'n can remove.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-come-your-heart-and-voices-raising","title":"Come, Your Heart and Voices Raising","language":"en","writers":"Paul Gerhardt, 1667. Translation composite","music":"German","year":1667,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"QUEM PASTORES","themes":["Hymn"],"lyrics":"Verse 1\nCome, your hearts and voices raising,\nChrist the Lord with gladness praising;\nLoudly sing His love amazing,\nWorthy folk of Christendom.\n\nVerse 2\nSin and death may well be groaning,\nSatan now may well be moaning;\nWe, our full salvation owning,\nCast our every care away.\n\nVerse 3\nSee how God, for us providing,\nGave His Son and life abiding;\nHe our weary steps is guiding From earth's woe to heav'nly joy.\n\nVerse 4\nChrist, from heav'n to us descending And in love our race befriending,\nIn our need His help extending,\nSaved us from the wily Foe.\n\nVerse 5\nJacob's Star in all its splendor Beams with comfort sweet and tender,\nForcing Satan to surrender,\nBreaking all the pow'rs of hell.\n\nVerse 6\nFrom the bondage that oppressed us,\nFrom sin's fetters that possessed us,\nFrom the grief that sore distressed us,\nWe, the captives, now are free.\n\nVerse 7\nOh, the joy beyond expressing\nWhen by faith we grasp this blessing\nAnd to Thee we come confessing,\nThat our freedom thou hast wrought!\n\nVerse 8\nGracious Child, we pray Thee, hear us,\nFrom Thy lowly manger cheer us,\nGently lead us and be near us\nTill we join the angelic choir.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-comfort-comfort-ye-my-people","title":"Comfort, Comfort Ye My People","language":"en","writers":"Johann Olearius (Oelschlaeger), 1671. Translated by Catherine Winkworth","music":"from Trente Quatre Pseaumes de David, Geneva","year":1671,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FREU DICH SEHR, O MEINE SEELE","themes":["Hymn","Advent"],"lyrics":"Verse 1\nComfort, comfort ye My people,\nSpeak ye peace, thus saith our God;\nComfort those who sit in darkness,\nMourning 'neath their sorrow's load;\nSpeak ye to Jerusalem Of the peace that waits for them;\nTell her that her sins I cover,\nAnd her warfare now is over.\n\nVerse 2\nFor the herald's voice is crying In the desert far and near,\nBidding all men to repentance,\nSince the kingdom now is here.\nO that warning cry obey!\nNow prepare for God a way!\nLet the valleys rise to meet Him,\nAnd the hills bow down to greet Him.\n\nVerse 3\nYea, her sins our God will pardon,\nBlotting out each dark misdeed;\nAll that well deserved His anger He will no more see nor heed.\nShe has suffered many a day,\nNow her griefs have passed away,\nGod will change her pining sadness Into ever springing gladness.\n\nVerse 4\nMake ye straight what long was crooked,\nMake the rougher places plain:\nLet your hearts be true and humble,\nAs befits His holy reign,\nFor the glory of the Lord O'er the earth is shed abroad,\nAnd all flesh shall see the token That His Word is never broken.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-crown-him-with-many-crowns","title":"Crown Him With Many Crowns","language":"en","writers":"Verses 1, 4, 5, 6 & 9: Matthew Bridges, The Passion of Jesus, 1852. verses 2 & 3: Godfrey Thring, Hymns and Sacred Lyrics","music":"George J. Elvey","year":1852,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"DIADEMATA","themes":["Hymn"],"lyrics":"Verse 1\nCrown Him with many crowns, the Lamb upon His throne.\nHark! How the heav'nly anthem drowns all music but its own.\nAwake, my soul, and sing of Him who died for thee,\nAnd hail Him as thy matchless King through all eternity.\n\nVerse 2\nCrown Him the virgin's Son, the God incarnate born,\nWhose arm those crimson trophies won which now His brow adorn;\nFruit of the mystic rose, as of that rose the stem;\nThe root whence mercy ever flows, the Babe of Bethlehem.\n\nVerse 3\nCrown Him the Son of God, before the worlds began,\nAnd ye who tread where He hath trod, crown Him the Son of Man;\nWho every grief hath known that wrings the human breast,\nAnd takes and bears them for His own, that all in Him may rest.\n\nVerse 4\nCrown Him the Lord of life, who triumphed o'er the grave,\nAnd rose victorious in the strife for those He came to save.\nHis glories now we sing,\nWho died, and rose on high,\nWho died eternal life to bring, and lives that death may die.\n\nVerse 5\nCrown Him the Lord of peace,\nWhose pow'r a scepter sways From pole to pole,\nthat wars may cease, and all be prayer and praise.\nHis reign shall know no end,\nand round His pierced feet\nFair flow'rs of paradise extend their fragrance ever sweet.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-day-of-wrath-o-day-of-mourning","title":"Day of Wrath, O Day of Mourning","language":"en","writers":"Thomas of Celano, 13th Century. Translated by William J. Irons","music":"John Bacchus Dykes","year":1848,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"DIES IRAE (DYKES)","themes":["Hymn"],"lyrics":"Verse 1\nDay of wrath, O day of mourning!\nSee fulfilled the prophet's warning,\nHeav'n and earth in ashes burning.\nOh, what fear man's bosom rendeth When from Heav'n the\nJudge descendeth On whose sentence all dependeth!\n\nVerse 2\nWondrous sound the trumpet flingeth,\nThrough earth's sepulchers it ringeth,\nAll before the throne it bringeth.\nDeath is struck and nature quaking;\nAll creation is awaking,\nTo its Judge an answer making.\n\nVerse 3\nLo, the book, exactly worded,\nWherein all hath been recorded;\nThence shall judgment be awarded.\nWhen the Judge His seat attaineth And each hidden deed arraigneth,\nNothing unavenged remaineth.\n\nVerse 4\nWhat shall I, frail man, be pleading?\nWho for me be interceding When the just are mercy needing?\nKing of majesty tremendous,\nWho dost free salvation send us,\nFount of pity, then befriend us.\n\nVerse 5\nThink, good Jesus, my salvation Caused Thy wondrous incarnation;\nLeave me not to reprobation!\nFaint and weary Thou hast sought me,\nOn the cross of suff'ring bought me;\nShall such grace be vainly brought me?","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-dear-christians-one-and-all-rejoice","title":"Dear Christians, One and All Rejoice","language":"en","writers":"Martin Luther, 1523. Translated by Richard Massie, 1854, alt","music":"from Klug's Geistliche Lieder, Wittenberg","year":1523,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ES IST GEWISSLICH AN DER ZEIT","themes":["Hymn"],"lyrics":"Verse 1\nDear Christians, one and all rejoice,\nWith exultation springing,\nAnd with united heart and voice And holy rapture singing,\nProclaim the wonders God hath done,\nHow his right arm the vict'ry won;\nRight dearly it hath cost him.\n\nVerse 2\nFast bound in Satan's chains I lay.\nDeath brooded darkly o'er me;\nSin was my torment night and day,\nTherein my mother bore me.\nDeeper and deeper still I fell,\nLife was become a living hell,\nSo firmly sin possessed me.\n\nVerse 3\nMy good works could avail me naught,\nFor they with sin were stainéd;\nFreewill against God's judgment fought,\nAnd dead to good remainéd.\nGrief drove me to despair, and I Had nothing left me but to die,\nTo hell I fast was sinking.\n\nVerse 4\nGod saw, in his eternal grace,\nMy sorrow out of measure;\nHe thought upon his tenderness To save was his good pleasure.\nHe turn'd to me a Father's heart —\nNot small the cost to heal my smart He gave his best and dearest.\n\nVerse 5\nHe spake to his beloved Son:\n'Tis time to take compassion;\nThen go, bright jewel of my crown,\nAnd bring to man salvation;\nFrom sin and sorrow set him free,\nSlay bitter death for him, that he May live with thee forever.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-despair-not-o-heart","title":"Despair Not, O Heart","language":"en","writers":"Aurelius Clemens Prudentius (348-413). Translated by O. T. Sanden","music":"unknown, sometimes attr. Martin Luther","year":1909,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"IAM MOESTA","themes":["Hymn"],"lyrics":"Verse 1\nDespair not, O heart, in thy sorrow,\nBut hope from God's promises borrow Beware in thy sorrow,\nof sinning For death is of life the beginning.\n\nVerse 2\nThe body is shrouded in mourning;\nThe garlands, the casket adorning,\nAre emblems of hope that betoken,\nO Death, that thy power is broken.\n\nVerse 3\nA dearly belov'd one hath left us;\nGod hath in His Wisdom bereft us;\nBut He will not leave us forsaken,We know that the dead shall awaken.\n\nVerse 4\nWhen dawneth the glorious morrow,\nThis body that we view with sorrow,\nA glorified form shall be given,\nRestored to its spirit in heaven.\n\nVerse 5\nThe seed that in springtime is planted,\nIs hid in the ground,\nbut if granted A measure of sunshine and showers,\nWill spring into fruitage and flowers;\n\nVerse 6\nA gift to the churchyard we tender,\nAs dust to the dust we surrender;\nReturning the clay to its Maker,\nWe lay it to rest in God's acre.\n\nVerse 7\nA soul in that body abided,\nA soul that in Jesus confided,\nA soul that hath longed for salvation,\nAnd now hath found hope's consummation.\n\nVerse 8\nO earth, we consign to thy keeping\nThis body with sorrow and weeping;\nIn peace to await resurrection,\nWhen it shall arise in perfection.\n\nVerse 9\nO Christ, our soul's Maker and Lover;\nWhen time and earth's travail are over,\nThou closest the grave's mournful story,\nAnd callest Thine own to Thy glory.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9"],"source":"Open Hymnal Project"},{"id":"oh-every-morning-mercies-new","title":"Every Morning Mercies New","language":"en","writers":"Greville Phillimore","music":"Edward J. Hopkins","year":1863,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"KELSO","themes":["Hymn"],"lyrics":"Verse 1\nEv'ry morning mercies new Fall as fresh as morning dew;\nEv'ry morning let us pay Tribute with the early day:\nFor Thy mercies, Lord, are sure;\nThy compassion doth endure.\n\nVerse 2\nStill the greatness of Thy love Daily doth our sins remove;\nDaily, far as east from west,\nLifts the burden from the breast;\nGives unbought to those who pray Strength to stand in evil day.\n\nVerse 3\nLet our prayers each morn prevail,\nThat these gifts may never fail;\nAnd, as we confess the sin And the tempter's pow'r within,\nFeed us with the Bread of Life,\nFit us for our daily strife.\n\nVerse 4\nAs the morning light returns,\nAs the sun with splendor burns,\nTeach us still to turn to Thee,\nEver blessed Trinity, With our hands our hearts to raise,\nIn unfailing prayer and praise.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-faith-of-our-fathers","title":"Faith of Our Fathers","language":"en","writers":"Frederick W. Faber, 1849. Refrain by James G. Walton","music":"Henri F. Hemy (1818-1888)","year":1849,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. CATHERINE","themes":["Hymn"],"lyrics":"Verse 1\nFaith of our fathers, living still,\nIn spite of dungeon, fire and sword;\nO how our hearts beat high with joy\nWhene'er we hear that glorious Word!\nFaith of our\n\nChorus\nfathers, holy faith! We will be true to thee till death.\n\nVerse 2\nFaith of our fathers, we will strive To win all nations unto Thee;\nAnd through the truth that comes from God,\nWe all shall then be truly free.\n\nVerse 3\nFaith of our fathers,\nwe will love Both friend and foe in all our strife;\nAnd preach Thee, too,\nas love knows how By kindly words and virtuous life.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-far-far-away-on-judea-s-plains","title":"Far, Far Away On Judea's Plains","language":"en","writers":"John M. MacFarlane","music":"s Plains' John M. MacFarlane","year":1869,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FAR, FAR AWAY ON JUDEA","themes":["Hymn"],"lyrics":"Verse 1\nFar, far away on Judea's plains,\nShepherds of old heard the joyous strains:\nGlory to God, glory to God,\nGlory to God in the\n\nChorus\nhighest; Peace on earth, good will to men;\nPeace on earth, good will to men.\n\nVerse 2\nSweet are these strains of redeeming love,\nMessage of mercy from heaven above:\n\nVerse 3\nLord, with the angels we too would rejoice;\nHelp us to sing with the heart and voice:\n\nVerse 4\nHasten the time when, from every clime,\nMen shall unite in the strains sublime:","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-fear-not-o-little-flock","title":"Fear Not, O Little Flock","language":"en","writers":"Attr. to King Gustavus Adolphus of Sweden (1594-1632), Jacob Fabricius (1593-1654) or Johann M. Altenburg (1584-1640). Translated by Catherine Winkworth","music":"traditional German","year":1594,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"KOMMT HER ZU MIR, SPRICHT GOTTES SOHN","themes":["Hymn"],"lyrics":"Verse 1\nFear not, O little flock, the foe Who madly seeks your overthrow;\nDread not his rage and pow'r;\nWhat though your courage sometimes faints,\nHis seeming triumph o'er God's saints Lasts but one little hour.\n\nVerse 2\nBe of good cheer;\nyour cause belongs To Him who can avenge your wrongs;\nLeave it to Him our Lord.\nThough hidden yet from all our eyes,\nHe sees the Gideon who shall rise;\nTo save us, and His word.\n\nVerse 3\nAs true as God's own word is true,\nNot earth nor hell with all their crew Against us shall prevail.\nA jest and by-word are they grown;\nGod is with us, we are His own,\nOur vict'ry cannot fail.\n\nVerse 4\nAmen, Lord Jesus, grant our prayer!\nGreat Captain, now Thine arm make bare;\nFight for us once again.\nSo shall thy saints and martyrs raise A mighty chorus to Thy praise,\nWorld without end. Amen.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-for-all-the-saints","title":"For All The Saints","language":"en","writers":"William W. How","music":"Ralph Vaughan Williams","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"SINE NOMINE","themes":["Hymn"],"lyrics":"Verse 1\nFor all the saints, who from their labors rest,\nWho Thee by faith before the world confessed,\nThy Name, O Jesus, be forever blessed.\nAlleluia, Alleluia! For the Evangelists, by whose blest word,\nLike fourfold streams, the garden of the Lord,\nIs fair and fruitful, be Thy Name adored.\n\nChorus\nAlleluia, Alleluia!\n\nVerse 2\nThou wast their Rock, their Fortress and their Might;\nThou, Lord, their Captain in the well fought fight;\nThou, in the darkness drear, their one true Light.\nAlleluia, Alleluia! For Martyrs, who with rapture kindled eye,\nSaw the bright crown descending from the sky,\nAnd seeing, grasped it, Thee we glorify.\n\nVerse 3\nFor the Apostles' glorious company,\nWho bearing forth the Cross o'er land and sea,\nShook all the mighty world, we sing to Thee:\nAlleluia, Alleluia! O blest communion, fellowship divine!\nWe feebly struggle, they in glory shine;\nAll are one in Thee, for all are Thine.\n\nVerse 4\nThe golden evening brightens in the west;\nSoon, soon to faithful warriors comes their rest;\nSweet is the calm of paradise the blessed.\nAlleluia, Alleluia! O may Thy soldiers, faithful, true and bold,\nFight as the saints who nobly fought of old,\nAnd win with them the victor's crown of gold.\n\nVerse 5\nBut lo! there breaks a yet more glorious day;\nThe saints triumphant rise in bright array;\nThe King of glory passes on His way.\nAlleluia, Alleluia! And when the strife is fierce, the warfare long,\nSteals on the ear the distant triumph song,\nAnd hearts are brave, again, and arms are strong.\n\nVerse 6\nFrom earth's wide bounds, from ocean's farthest coast,\nThrough gates of pearl streams in the countless host,\nAnd singing to Father, Son and Holy Ghost:","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-for-the-beauty-of-the-earth","title":"For The Beauty Of The Earth","language":"en","writers":"Folliot S. Pierpoint","music":"Conrad Kocher","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"DIX","themes":["Hymn"],"lyrics":"Verse 1\nFor the beauty of the earth For the glory of the skies,\nFor the love which from our birth Over and around us lies.\n\nChorus\nLord of all, to Thee we raise,\nThis our hymn of grateful praise.\n\nVerse 2\nFor the beauty of each hour,\nOf the day and of the night,\nHill and vale, and tree and flow'r,\nSun and moon, and stars of light.\n\nVerse 3\nFor the joy of ear and eye,\nFor the heart and mind's delight,\nFor the mystic harmony Linking sense to sound and sight.\n\nVerse 4\nFor the joy of human love,\nBrother, sister, parent, child,\nFriends on earth and friends above,\nFor all gentle thoughts and mild.\n\nVerse 5\nFor Thy Church, that evermore Lifteth holy hands above,\nOff'ring up on every shore Her pure sacrifice of love.\n\nVerse 6\nFor the martyrs' crown of light,\nFor Thy prophets' eagle eye,\nFor Thy bold confessors' might,\nFor the lips of infancy.\n\nVerse 7\nFor Thy virgins' robes of snow,\nFor Thy maiden mother mild,\nFor Thyself, with hearts aglow,\nJesu, Victim undefiled.\n\nVerse 8\nFor each perfect gift of Thine,\nTo our race so freely given,\nGraces human and divine,\nFlowers of earth and buds of Heaven.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus","Verse 7","Chorus","Verse 8","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-from-heaven-above-to-earth-i-come","title":"From Heaven Above To Earth I Come","language":"en","writers":"Martin Luther, 1535. translated by Catherine Winkworth","music":"traditional German from Schumann's Geistliche Lieder, Leipzig","year":1535,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"VOM HIMMEL HOCH","themes":["Hymn"],"lyrics":"Verse 1\nFrom Heaven above to earth I come,\nTo bear good news to every home;\nGlad tidings of great joy I bring,\nWhereof I now will say and sing.\n\nVerse 2\nTo you, this night, is born a Child Of Mary, chosen mother mild;\nThis tender Child of lowly birth,\nShall be the joy of all your earth.\n\nVerse 3\n'Tis Christ our God,\nWho far on high Had heard your sad and bitter cry;\nHimself will your Salvation be,\nHimself from sin will make you free.\n\nVerse 4\nHe brings those blessings long ago Prepared by God for all below;\nThat in His heavenly kingdom blest You may with us forever rest.\n\nVerse 5\nThese are the tokens ye shall mark,\nThe swaddling clothes and manger dark;\nThere shall ye find the young Child laid,\nBy Whom the heav'ns and earth were made.\n\nVerse 6\nNow let us all, with gladsome cheer,\nFollow the shepherds, and draw near\nTo see this wondrous Gift of God,\nWho hath His own dear Son bestowed.\n\nVerse 7\nGive heed, my heart, lift up thine eyes!\nWhat is it in yon manger lies?\nWho is this Child, so young and fair?\nThe blessèd Christ Child lieth there!\n\nVerse 8\nWelcome to earth, Thou noble Guest,\nThrough Whom e'en wicked men are blest!\nThou com'st to share our misery,\nWhat can we render, Lord, to Thee!\n\nVerse 9\nAh, Lord, Who hast created all,\nHow hast Thou made Thee weak and small,\nTo lie upon the coarse dry grass,\nThe food of humble ox and ass.\n\nVerse 10\nWere earth a thousand times as fair,\nBeset with gold and jewels rare,\nShe yet were far too poor to be\nA narrow cradle, Lord, for Thee.\n\nVerse 11\nFor velvets soft and silken stuff\nThou hast but hay and straw so rough,\nWhereon Thou King, so rich and great,\nAs 'twere Thy heaven, art throned in state.\n\nVerse 12\nThus hath it pleased Thee to make plain\nThe truth to us, poor fools and vain,\nThat this world's honor, wealth and might\nAre naught and worthless in Thy sight.\n\nVerse 13\nAh, dearest Jesus, holy Child,\nMake Thee a bed, soft, undefiled,\nHere in my poor heart's inmost shrine,\nThat I may evermore be Thine.\n\nVerse 14\nMy heart for very joy doth leap,\nMy lips no more can silence keep,\nI too must sing, with joyful tongue,\nThat sweetest ancient cradle song.\n\nVerse 15\nGlory to God in highest Heaven,\nWho unto man His Son hath given,\nWhile angels sing, with pious mirth,\nA glad New Year to all the earth.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11","Verse 12","Verse 13","Verse 14","Verse 15"],"source":"Open Hymnal Project"},{"id":"oh-from-nazareth","title":"From Nazareth","language":"en","writers":"Margaret E. Sangster","music":"Michael Praetorius","year":1911,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"PUER NOBIS NASCITUR","themes":["Hymn"],"lyrics":"Verse 1\nComes any good from Nazareth?\nThe scornful challenge as of old Is flung on many'a jeering breath\nFrom cloistered cells and marts of gold.\n\nVerse 2\nComes any good from Nazareth?\nBehold, the mighty Nazarene,\nThe Lord of life, the Lord of death,\nThrough warring ages walks serene.\n\nVerse 3\nOne touch upon His garment's fringe\nStill heals the hurt of bitter years.\nBefore Him yet the demons cringe,\nHe gives the wine of joy for tears.\n\nVerse 4\nO city of the Carpenter,\nUpon the hill slope old and gray,\nThe world among its pain and stir Turns yearning eyes on thee today.\n\nVerse 5\nFor He who dwelt in Nazareth,\nAnd wrought with toil of hand and brain,\nAlone gives victory to faith Until the day He come again.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-gabriel-s-message","title":"Gabriel's Message","language":"en","writers":"Traditional Basque Carol; Paraphrased by Sabine Baring Gould, (1834-1924)","music":"s Message' Traditional Basque Carol","year":1834,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"GABRIEL","themes":["Hymn"],"lyrics":"Verse 1\nThe angel Gabriel from heaven came,\nhis wings as drifted snow, his eyes as flame;\n\"All hail,\" said he,\n\"thou lowly maiden, Mary,\n\nChorus\nmost highly favored lady,\" Gloria!\n\nVerse 2\n\"For know a blessed Mother thou shalt be,\nall generations laud and honor thee,\nthy Son shall be Emmanuel, by seers foretold,\n\nVerse 3\nThen gentle Mary meekly bowed her head,\n\"To me be as it pleaseth God,\" she said,\n\"my soul shall laud and magnify His holy Name.\"\n\nVerse 4\nOf her, Emmanuel, the Christ was born in Bethlehem,\nall on a Christmas morn,\nand Christian folk throughout the world will ever say","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-gentle-mary-laid-her-child","title":"Gentle Mary Laid Her Child","language":"en","writers":"Joseph S. Cook","music":"13th Century spring carol; first published in the Swedish Piae Cantones","year":1919,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"TEMPUS ADEST FLORIDUM","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nGentle Mary laid her Child lowly in a manger;\nThere He lay, the undefiled, to the world a Stranger:\nSuch a Babe in such a place, can He be the Savior?\nAsk the saved of all the race who have found His favor.\n\nVerse 2\nAngels sang about His birth; wise men sought and found Him;\nHeaven's star shone brightly forth, glory all around Him:\nShepherds saw the wondrous sight, heard the angels singing;\nAll the plains were lit that night, all the hills were ringing.\n\nVerse 3\nGentle Mary laid her Child lowly in a manger;\nHe is still the undefiled, but no more a stranger:\nSon of God, of humble birth, beautiful the story;\nPraise His Name in all the earth, hail the King of glory!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-glorious-things-of-thee-are-spoken","title":"Glorious Things of Thee are Spoken","language":"en","writers":"John Newton, 1779, alt","music":"Franz Joseph Haydn","year":1779,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"AUSTRIA (HAYDN)","themes":["Hymn"],"lyrics":"Verse 1\nGlorious things of thee are spoken,\nZion city of our God;\nHe, Whose Word cannot be broken Formed thee for His Own abode:\nOn the Rock of Ages founded,\nWhat can shake thy sure repose?\nWith salvation's walls surrounded,\nThou mayst smile at all thy foes.\n\nVerse 2\nSee, the streams of living waters,\nSpringing from Eternal Love,\nWell supply thy sons and daughters,\nAnd all fear of want remove:\nWho can faint, while such a river Ever will their thirst assuage?\nGrace, which, like the Lord the Giver,\nNever fails from age to age.\n\nVerse 3\nRound each habitation hov'ring,\nSee the cloud and fire appear,\nFor a glory and a cov'ring:\nShowing that the Lord is near.\nThus deriving from their banner Light by night, and shade by day,\nSafe they feed upon the manna,\nWhich He gives them on their way.\n\nVerse 4\nSavior, if of Zion's city I, through grace, a member am,\nLet the world deride or pity,\nI will glory in Thy Name:\nFading is the worldling's pleasure,\nAll his boasted pomp and show:\nSolid joys and lasting treasure None but Zion's children know.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-go-to-dark-gethsemane","title":"Go To Dark Gethsemane","language":"en","writers":"James Montgomery","music":"Richard Redhead","year":1820,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"GETHSEMANE","themes":["Hymn"],"lyrics":"Verse 1\nGo to dark Gethsemane, ye that feel the tempter's pow'r;\nYour Redeemer's conflict see, watch with Him one bitter hour,\nTurn not from His griefs away; learn from Jesus Christ to pray.\n\nVerse 2\nFollow to the judgment hall, view the Lord of Life arraigned;\nO the wormwood and the gall!\nO the pangs His soul sustained!\nShun not suff'ring, shame, or loss;\nlearn from Christ to bear the cross.\n\nVerse 3\nCalv'ry's mournful mountain climb; there, adoring at His feet,\nMark that miracle of time,\nGod's own sacrifice complete.\n\"It is finished!\" hear Him cry; learn from Jesus Christ to die.\n\nVerse 4\nEarly hasten to the tomb where they laid His breathless clay;\nAll is solitude and gloom.\nWho has taken Him away?\nChrist is ris'n! He meets our eyes;\nSavior, teach us so to rise.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-god-himself-is-present","title":"God Himself is Present","language":"en","writers":"Gerhard Tersteegen, 1729. Translated by Frederick W. Foster and John Miller, 1789, alt","music":"Joachim Neander","year":1729,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"WUNDERBARER KÖNIG","themes":["Hymn"],"lyrics":"Verse 1\nGod Himself is present:\nLet us now adore Him,\nAnd with awe appear before Him.\nGod is in His temple, all within keep silence,\nProstrate lie with deepest reverence.\nHim alone God we own,\nHim our God and Savior;\nPraise His name forever.\n\nVerse 2\nGod Himself is present:\nHear the harps resounding!\nSee the crowds the throne surrounding!\n\"Holy, holy, holy\", hear the hymn ascending,\nAngels, saints, their voices blending!\nBow Thine ear to us here:\nHear, O Christ, the praises That Thy Church now raises.\n\nVerse 3\nO Thou fount of blessing,\nPurify my spirit; Trusting only in Thy merit,\nLike the holy angels Who behold Thy glory,\nMay I ceaselessly adore Thee,\nLet Thy will Ever still Rule Thy Church terrestrial,\nAs the hosts celestial.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-god-rest-ye-merry-gentlemen","title":"God Rest Ye Merry Gentlemen","language":"en","writers":"Traditional English","music":"Traditional English","year":1918,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"GOD REST YE MERRY GENTLEMEN","themes":["Hymn"],"lyrics":"Verse 1\nGod rest ye merry, gentlemen, let nothing you dismay,\nRemember Christ our Savior was born on Christmas Day;\nTo save us all from Satan's pow'r when we were gone astray.\n\nChorus\nO tidings of comfort and joy, comfort and joy;\nO tidings of comfort and joy.\n\nVerse 2\nIn Bethlehem, in Israel, this blessèd Babe was born,\nAnd laid within a manger upon this blessèd morn;\nThe which His mother Mary did nothing take in scorn.\n\nVerse 3\nFrom God our heav'nly Father a blessèd angel came;\nAnd unto certain shepherds brought tidings of the same;\nHow that in Bethlehem was born the Son of God by name.\n\nVerse 4\n\"Fear not, then,\" said the angel,\n\"Let nothing you afright This day is born a\nSavior of a pure Virgin bright,\nTo free all those who trust in Him from Satan's pow'r and might.\"\n\nVerse 5\nThe shepherds at those tidings rejoiced much in mind,\nAnd left their flocks afeeding in tempest, storm and wind,\nAnd went to Bethl'em straightaway this blessèd Babe to find.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-god-that-madest-earth-and-heaven","title":"God, That Madest Earth and Heaven","language":"en","writers":"verse 1, Reginald Heber, 1827. verse 2, William Mercer, 1864. verse 3, Richard Whately","music":"traditional Welsh","year":1827,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"AR HYD Y NOS","themes":["Hymn"],"lyrics":"Verse 1\nGod, that madest earth and Heaven, darkness and light;\nWho the day for toil hast given, for rest the night;\nMay Thine angel guards defend us,\nSlumber sweet Thy mercy send us;\nHoly dreams and hopes attend us, all through the night.\n\nVerse 2\nAnd when morn again shall call us, to run life's way,\nMay we still, whate'er befall us,\nThy will obey. From the pow'r of evil hide us,\nIn the narrow pathway guide us,\nNor Thy smile be e'er denied us all through the day.\n\nVerse 3\nGuard us waking, guard us sleeping, and when we die,\nMay we in Thy mighty keeping all peaceful lie;\nWhen the last dread call shall wake us,\nDo not Thou, our God, forsake us,\nBut to reign in glory take us with Thee on high.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-god-the-father-be-our-stay","title":"God the Father Be Our Stay","language":"en","writers":"15th Century Litany, adapted by Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"GOTT DER VATER, WOHN UNS BEI","themes":["Hymn"],"lyrics":"Verse 1\nGod the Father, be our Stay,\nWhen hell's dread pow'rs assail us;\n\nChorus\nCleanse us from our sins, we pray,\nNor in our last hour fail us.\nKeep us from the Evil One;\nFirm in the faith abiding,\nIn Christ our Savior hiding,\nAnd heartily confiding. Let us put God's armor on:\nWith all true Christians running\nOur heav'nly race and shunning The devil's wiles and cunning.\nAmen, Amen, this be done,\nSo sing we, Hallelujah!\n\nVerse 2\nJesus Christ be Thou our Stay,\n\nVerse 3\nHoly Ghost, be Thou our Stay,\n\nVerse 4\n1(alt). Triune God, be Thou our Stay,","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-god-whose-almighty-word","title":"God, Whose Almighty Word","language":"en","writers":"John Marriott","music":"Felice de Giardini","year":1813,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ITALIAN HYMN","themes":["Hymn"],"lyrics":"Verse 1\nGod, whose almighty word\nChaos and darkness heard And took their flight:\nHear us, we humble pray,\nAnd where the Gospel day Sheds not its glorious ray,\nLet there be light!\n\nVerse 2\nLord, who once came to bring,\nOn your redeeming wing,\nHealing and sight, Health to the sick in mind,\nSight to the inly blind:\nOh, now to humankind Let there be light!\n\nVerse 3\nSpirit of truth and love,\nLife giving, holy dove,\nSpeed forth your flight;\nMove on the water's face,\nBearing the lamp of grace,\nAnd in earth's darkest place Let there be light!\n\nVerse 4\nHoly and blessed three,\nGlorious Trinity, Wisdom, love, might!\nBoundless as ocean's tide,\nRolling in fullest pride,\nThrough the earth, far and wide,\nLet there be light!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-god-will-take-care-of-you","title":"God Will Take Care of You","language":"en","writers":"Civilla Durfee Martin","music":"Walter Stillman Martin","year":1905,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"MARTIN","themes":["Hymn"],"lyrics":"Verse 1\nBe not dismayed whate'er betide,\nGod will take care of you;\nBeneath His wings of love abide,\nGod will take care of you.\n\nChorus\nGod will take care of you, through ev'ry day, o'er all the way;\nHe will take care of you,\nGod will take care of you.\n\nVerse 2\nThrough days of toil when heart doth fail,\nGod will take care of you;\nWhen dangers fierce your path assail,\nGod will take care of you.\n\nVerse 3\nAll you may need He will provide,\nGod will take care of you;\nNothing you ask will be denied,\nGod will take care of you.\n\nVerse 4\nNo matter what may be the test,\nGod will take care of you;\nLean, weary one, upon His breast,\nGod will take care of you.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-guide-me-o-thou-great-jehovah","title":"Guide Me, O Thou Great Jehovah","language":"en","writers":"William Williams, 1745. Translated by Peter Williams","music":"John Hughes","year":1745,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"CWM RHONDDA","themes":["Hymn"],"lyrics":"Verse 1\nGuide me, O Thou great Jehovah,\nPilgrim through this barren land.\nI am weak, but Thou art mighty;\nHold me with Thy pow'rful hand.\nBread of Heaven, Bread of Heaven,\nFeed me till I want no more;\nFeed me till I want no more.\n\nVerse 2\nOpen now the crystal fountain,\nWhence the healing stream doth flow;\nLet the fire and cloudy pillar Lead me all my journey through.\nStrong Deliv'rer, strong Deliv'rer,\nBe Thou still my Strength and Shield;\nBe Thou still my Strength and Shield.\n\nVerse 3\nLord, I trust Thy mighty power,\nWondrous are Thy works of old;\nThou deliver'st Thine from thralldom,\nWho for naught themselves had sold:\nThou didst conquer, Thou didst conquer,\nSin, and Satan and the grave,\nSin, and Satan and the grave.\n\nVerse 4\nWhen I tread the verge of Jordan,\nBid my anxious fears subside;\nDeath of deaths, and hell's destruction,\nLand me safe on Canaan's side.\nSongs of praises, songs of praises,\nI will ever give to Thee;\nI will ever give to Thee.\n\nVerse 5\nMusing on my habitation,\nMusing on my heav'nly home,\nFills my soul with holy longings:\nCome, my Jesus, quickly come;\nVanity is all I see;\nLord, I long to be with Thee!\nLord, I long to be with Thee!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-hallelujah-what-a-savior","title":"Hallelujah, What a Savior!","language":"en","writers":"Philip Paul Bliss","music":"Philip Paul Bliss","year":1875,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"HALLELUJAH WHAT A SAVIOR","themes":["Hymn"],"lyrics":"Verse 1\nMan of Sorrows! what a name For the Son of God,\nwho came Ruined sinners to reclaim.\nHallelujah! What a Savior!\n\nVerse 2\nBearing shame and scoffing rude,\nIn my place condemned He stood;\nSealed my pardon with His blood.\n\nVerse 3\nGuilty, vile, and helpless we;\nSpotless Lamb of God was He;\n\"Full atonement!\" can it be?\n\nVerse 4\nLifted up was He to die;\n\"It is finished!\" was His cry;\nNow in Heav'n exalted high.\n\nVerse 5\nWhen He comes, our glorious King,\nAll His ransomed home to bring,\nThen anew His song we'll sing:","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-happy-the-man-who-feareth-god","title":"Happy the Man Who Feareth God","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"WO GOTT ZUM HAUS (WALTER)","themes":["Hymn"],"lyrics":"Verse 1\nHappy the man who feareth God,\nWhose feet His holy ways have trod;\nThine own good hand shall nourish thee,\nAnd well and happy shalt thou be.\n\nVerse 2\nThy wife shall, like a fruitful vine,\nFill all thy house with clusters fine;\nThy children all be fresh and sound,\nLike olive-plants thy table round.\n\nVerse 3\nLo! to the man these blessings cleave\nWho in God's holy fear doth live;\nFrom him the ancient curse hath fled By Adam's race inherited.\n\nVerse 4\nOut of Mount Zion God shall send,\nAnd crown with joy thy latter end;\nThat thou Jerusalem mayst see,\nIn favor and prosperity.\n\nVerse 5\nHe shall be with thee in thy ways,\nAnd give thee health and length of days Yea,\nthou shalt children's children see,\nAnd peace on Israel shall be.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-hark-hark-my-soul","title":"Hark, Hark, My Soul!","language":"en","writers":"Frederick W. Faber, 1854. Arranged and alt. by Mike Hosken, 2014","music":"Jean Sibelius","year":1854,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FINLANDIA","themes":["Hymn"],"lyrics":"Verse 1\nHark! hark, my soul!\nangelic songs are swelling O'er earth's green fields and ocean's wave-beat shore:\nHow sweet the truth those blessèd strains are telling\nOf that new life when sin shall be no more!\nOnward we go, for still we hear them sing,\n\"Come, weary souls, for Jesus bids you come\";\n\nVerse 2\nAnd through the dark, its echoes sweetly ringing,\nThe music of the Gospel leads us home.\nFar, far away, like bells at ev'ning pealing,\nThe voice of Jesus sounds o'er land and sea,\nAnd laden souls, by thousands meekly stealing,\nKind Shepherd, turn their weary steps to Thee.\n\nVerse 3\nFaith's journeys end in welcome to the weary,\nAnd Heav'n, the heart's true home will come at last.\nAngels, sing on, your faithful watches keeping,\nSing us sweet fragments of the songs above;\nTill morning's joy shall end the night of weeping,\nAnd life's long shadows break in cloudless love.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-hark-the-glad-sound","title":"Hark the Glad Sound","language":"en","writers":"Philip Doddridge","music":"Thomas Haweis","year":1735,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"CHESTERFIELD","themes":["Hymn"],"lyrics":"Verse 1\nHark, the glad sound! the Savior comes!\nThe Savior promised long;\nLet every heart prepare a throne,\nAnd every voice a song.\n\nVerse 2\nOn Him the Spirit, largely poured,\nExerts its sacred Fire;\nWisdom and might, and zeal and love,\nHis holy Breast inspire.\n\nVerse 3\nHe comes the pris'ners to release,\nIn Satan's bondage held;\nThe gates of brass before Him burst,\nThe iron fetters yield.\n\nVerse 4\nHe comes from thickest films of vice To clear the mental ray,\nAnd on the eyeballs of the blind To pour celestial day.\n\nVerse 5\nHe comes the broken heart to bind,\nThe bleeding soul to cure;\nAnd with the treasures of His grace T'enrich the humble poor.\n\nVerse 6\nHis silver trumpets publish loud\nThe jub'lee of the Lord\nOur debts are all remitted now\nOur heritage restored.\n\nVerse 7\nOur glad hosannas, Prince of Peace,\nThy welcome shall proclaim;\nAnd Heav'n's eternal arches ring\nWith Thy belovèd name.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-hark-the-herald-angels-sing","title":"Hark! The Herald Angels Sing","language":"en","writers":"Charles Wesley, 1739, alt","music":"from Felix Mendelssohn","year":1739,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"MENDELSSOHN","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nHark! The herald angels sing,\n\"Glory to the newborn King;\nPeace on earth, and mercy mild,\nGod and sinners reconciled!\" Joyful, all ye nations rise,\nJoin the triumph of the skies;\nWith th'angelic host proclaim,\n\"Christ is born in Bethlehem!\"\n\nChorus\nHark! the herald angels sing,\n\"Glory to the newborn King!\"\n\nVerse 2\nChrist, by highest Heav'n adored;\nChrist the everlasting Lord;\nLate in time, behold Him come,\nOffspring of a virgin's womb.\nVeiled in flesh the Godhead see;\nHail th'incarnate Deity,\nPleased with us in flesh to dwell, Jesus our Emmanuel.\n\nVerse 3\nHail the heav'nly Prince of Peace!\nHail the Sun of Righteousness!\nLight and life to all He brings,\nRis'n with healing in His wings.\nMild He lays His glory by,\nBorn that man no more may die.\nBorn to raise the sons of earth,\nBorn to give them second birth.\n\nVerse 4\nCome, Desire of nations, come,\nFix in us Thy humble home;\nRise, the woman's conqu'ring Seed,\nBruise in us the serpent's head.\nNow display Thy saving power,\nRuined nature now restore;\nNow in mystic union join Thine to ours, and ours to Thine.\n\nVerse 5\nAdam's likeness, Lord, efface,\nStamp Thine image in its place:\nSecond Adam from above,\nReinstate us in Thy love.\nLet us Thee, though lost, regain,\nThee, the Life, the inner man:\nO, to all Thyself impart,\nFormed in each believing heart.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-hark-the-voice-of-jesus-calling","title":"Hark, the Voice of Jesus Calling","language":"en","writers":"Daniel March","music":"Joseph Barnby","year":1868,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"GALILEAN","themes":["Hymn"],"lyrics":"Verse 1\nHark, the voice of Jesus calling,\n\"Who will go and work today?\nFields are ripe and harvests waiting,\nWho will bear the sheaves away?\" Long and loud the Master calls us,\nRich reward He offers free;\nWho will answer, gladly saying,\n\"Here am I, send me, send me?\"\n\nVerse 2\nIf you cannot cross the ocean,\nAnd the distant lands explore,\nYou can find the lost around you,\nYou can help them at your door;\nIf you cannot give your thousands,\nYou can give the widow's mite;\nWhat you truly give for Jesus,\nWill be precious in His sight.\n\nVerse 3\nIf you cannot speak like angels,\nIf you cannot preach like Paul,\nYou can tell the love of Jesus,\nYou can say He died for all.\nIf you cannot rouse the wicked,\nWith the judgment's dread alarms,\nYou can lead the little children To the Savior's waiting arms.\n\nVerse 4\nIf you cannot be the watchman,\nStanding high on Zion's wall,\nPointing out the path to heaven,\nOff'ring life and peace to all,\nWith your prayers and with your bounties\nYou can do what heav'n demands;\nYou can be like faithful Aaron,\nHolding up the prophet's hands.\n\nVerse 5\nIf among the older people,\nYou may not be apt to teach,\n\"Feed My lambs,\" said Christ, our Shepherd,\n\"Place the food within their reach.\"\nAnd it may be that the children You have led with trembling hand,\nWill be found among your jewels,\nWhen you reach the better land.\n\nVerse 6\nLet none hear you idly saying, \"There is nothing I can do.\"\nWhile the lost of earth are dying, And the Master calls for you;\nTake the task He gives you gladly; Let His work your pleasure be;\nAnswer quickly when He calls you, \"Here am I, send me, send me.\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-he-keeps-me-singing","title":"He Keeps Me Singing","language":"en","writers":"Luther B. Bridgers","music":"Hans Engelmann","year":1910,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"HE KEEPS ME SINGING","themes":["Hymn"],"lyrics":"Verse 1\nThere's within my heart a melody Jesus whispers sweet and low,\n\"Fear not, I am with thee, peace,\nbe still,\" In all of life's ebb and flow.\n\nChorus\nJesus, Jesus, Jesus, — Sweetest name I know,\nFills my ev'ry longing,\nKeeps me singing as I go.\n\nVerse 2\nAll my life was wrecked by sin and strife,\nDiscord filled my heart with pain,\nJesus swept across the broken strings,\nStirred the slumb'ring chords again.\n\nVerse 3\nFeasting on the riches of His grace,\nResting 'neath His shelt'ring wing,\nAlways looking on His smiling face,\nThat is why I shout and sing.\n\nVerse 4\nThough sometimes He leads through waters deep,\nTrials fall across the way,\nThough sometimes the path seems rough and steep,\nSee His footprints all the way.\n\nVerse 5\nSoon He's coming back to welcome me,\nFar beyond the starry sky;\nI shall wing my flight to worlds unknown,\nI shall reign with Him on high.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-he-leadeth-me","title":"He Leadeth Me","language":"en","writers":"Joseph H. Gilmore","music":"William B. Bradbury","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"HE LEADETH ME","themes":["Hymn"],"lyrics":"Verse 1\nHe leadeth me, O blessèd thought!\nO words with heav'nly comfort fraught!\nWhate'er I do, where'er I be Still 'tis God's hand that leadeth me.\n\nChorus\nHe leadeth me, He leadeth me,\nBy His own hand He leadeth me;\nHis faithful follow'r I would be,\nFor by His hand He leadeth me.\n\nVerse 2\nSometimes mid scenes of deepest gloom,\nSometimes where Eden's bowers bloom,\nBy waters still, ov'r troubled sea,\nStill 'tis His hand that leadeth me.\n\nVerse 3\nLord, I would place my hand in Thine,\nNor ever murmur nor repine;\nContent, whatever lot I see,\nSince 'tis my God that leadeth me.\n\nVerse 4\nAnd when my task on earth is done,\nWhen by Thy grace the vict'ry's won,\nE'en death's cold wave I will not flee,\nSince God through Jordan leadeth me.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-he-was-not-willing","title":"He Was Not Willing","language":"en","writers":"Lucy R. Meyer","music":"Lucy R. Meyer","year":1885,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"HE WAS NOT WILLING","themes":["Hymn"],"lyrics":"Verse 1\n\"He was not willing that any should perish\";\nJesus enthroned in the glory above,\nSaw our poor fallen world, pitied our sorrows,\nPoured out His life for us, wonderful love!\nPerishing, perishing! Thronging our pathway,\nHearts break with burdens too heavy to bear:\nJesus would save, but there's no one to tell them,\nNo one to lift them from sin and despair.\n\nVerse 2\n\"He was not willing that any should perish\";\nClothed in our flesh with its sorrow and pain,\nCame He to seek the lost, comfort the mourner,\nHeal the heart broken by sorrow and shame.\nPerishing, perishing! Harvest is passing,\nReapers are few and the night draweth near:\nJesus is calling thee, haste to the reaping,\nThou shalt have souls, precious souls for thy hire.\n\nVerse 3\nPlenty for pleasure, but little for Jesus;\nTime for the world with its troubles and toys,\nNo time for Jesus' work, feeding the hungry,\nLifting lost souls to eternity's joys.\nPerishing, perishing! Hark, how they call us;\nBring us your Savior, oh, tell us of Him!\nWe are so weary, so heavily laden,\nAnd with long weeping our eyes have grown dim.\n\nVerse 4\n\"He was not willing that any should perish\";\nAm I His follower,\nand can I live Longer at ease with a soul going downward,\nLost for the lack of the help I might give!\nPerishing, perishing! Thou wast not willing;\nMaster, forgive, and inspire us anew;\nBanish our worldliness,\nhelp us to ever Live with eternity's values in view.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-he-who-would-valiant-be","title":"He Who Would Valiant Be","language":"en","writers":"John Bunyan, 1684. Modified by Percy Dearmer","music":"traditional English","year":1684,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"MONKS GATE","themes":["Hymn"],"lyrics":"Verse 1\nHe who would valiant be 'gainst all disaster,\nLet him in constancy follow the Master.\nThere's no discouragement shall make him once relent\nHis first avowed intent to be a pilgrim.\n\nVerse 2\nWho so beset him round with dismal stories\nDo but themselves confound his strength the more is.\nNo foes shall stay his might; though he with giants fight,\nHe will make good his right to be a pilgrim.\n\nVerse 3\nSince, Lord, Thou dost defend us with Thy Spirit,\nWe know we at the end, shall life inherit.\nThen fancies flee away!\nI'll fear not what men say,\nI'll labor night and day to be a pilgrim.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-holy-ghost-with-light-divine","title":"Holy Ghost, with Light Divine","language":"en","writers":"verses 1-6 Andrew Reed, 1817. verses 7-13 Samuel Longfellow","music":"Orlando Gibbons","year":1817,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"CANTERBURY","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nHoly Ghost, with light divine Shine upon this heart of mine;\nChase the shades of night away,\nTurn the darkness into day.\n\nVerse 2\nLet me see my Savior's face,\nLet me all His beauties trace;\nShow those glorious truths to me Which are only known to Thee.\n\nVerse 3\nHoly Ghost, with pow'r divine Cleanse this guilty heart of mine;\nIn Thy mercy pity me,\nFrom sin's bondage set me free.\n\nVerse 4\nHoly Ghost, with joy divine Cheer this saddened heart of mine;\nYield a sacred, settled peace,\nLet it grow and still increase.\n\nVerse 5\nHoly Spirit, all divine,\nDwell within this heart of mine;\nCast down every idol-throne,\nReign supreme, and reign alone.\n\nVerse 6\nSee, to Thee I yield my heart,\nShed Thy life through every part;\nA pure temple I would be,\nWholly dedicate to Thee.\n\nVerse 7\nHoly Spirit, Truth divine,\nDawn upon this soul of mine;\nWord of God and inward light\nWake my spirit, clear my sight.\n\nVerse 8\nHoly Spirit, Love divine,\nGlow within this heart of mine;\nKindle every high desire;\nPerish self in Thy pure fire.\n\nVerse 9\nHoly Spirit, Power divine\nFill and nerve this will of mine;\nGrant that I may strongly live,\nBravely bear, and nobly strive.\n\nVerse 10\nHoly Spirit, Right divine,\nKing within my conscience reign;\nBe my Lord, and I shall be\nFirmly bound, forever free.\n\nVerse 11\nHoly Spirit, Peace divine,\nStill this restless heart of mine;\nSpeak to calm this tossing sea,\nStayed in Thy tranquility.\n\nVerse 12\nHoly Spirit, Joy divine,\nGladden Thou this heart of mine;\nIn the desert ways I sing,\n\"Spring, O Well, forever spring.\"\n\nVerse 13\nNow incline me to repent,\nLet me now my sins lament,\nNow my foul revolt deplore,\nWeep, believe, and sin no more.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11","Verse 12","Verse 13"],"source":"Open Hymnal Project"},{"id":"oh-holy-god-we-praise-thy-name","title":"Holy God, We Praise Thy Name","language":"en","writers":"attr. Ignaz Franz, 1774. Translated by Clarence A. Walworth","music":"from Katholisches Gesangbuch, Maria Theresa","year":1774,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"TE DEUM","themes":["Hymn"],"lyrics":"Verse 1\nHoly God, we praise Thy Name;\nLord of all, we bow before Thee!\nAll on earth Thy scepter claim,\nAll in Heaven above adore Thee;\nInfinite Thy vast domain,\nEverlasting is Thy reign.\n\nVerse 2\nHark! the loud celestial hymn Angel choirs above are raising,\nCherubim and seraphim, In unceasing chorus praising;\nFill the heavens with sweet accord:\nHoly, holy, holy, Lord.\n\nVerse 3\nLo! the apostolic train Join the sacred Name to hallow;\nProphets swell the loud refrain,\nAnd the white robed martyrs follow;\nAnd from morn to set of sun,\nThrough the Church the song goes on.\n\nVerse 4\nHoly Father, Holy Son,\nHoly Spirit, Three we name Thee;\nWhile in essence only One,\nUndivided God we claim Thee;\nAnd adoring bend the knee,\nWhile we own the mystery.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-holy-holy-holy","title":"Holy, Holy, Holy","language":"en","writers":"Reginald Heber","music":"John Bacchus Dykes","year":1826,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"NICAEA","themes":["Hymn","Trinity"],"lyrics":"Verse 1\nHoly, holy, holy! Lord God Almighty!\nEarly in the morning our song shall rise to Thee;\nHoly, holy, holy, merciful and mighty!\nGod in three Persons, blessed Trinity!\n\nVerse 2\nHoly, holy, holy! All the saints adore Thee,\nCasting down their golden crowns around the glassy sea;\nCherubim and seraphim falling down before Thee,\nWho was, and is, and evermore shall be.\n\nVerse 3\nHoly, holy, holy! though the darkness hide Thee,\nThough the eye of sinful man Thy glory may not see;\nOnly Thou art holy; there is none beside Thee,\nPerfect in pow'r, in love, and purity.\n\nVerse 4\nHoly, holy, holy! Lord God Almighty!\nAll Thy works shall praise Thy Name, in earth, and sky, and sea;\nHoly, holy, holy; merciful and mighty!\nGod in three Persons, blessed Trinity!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-holy-spirit-ever-dwelling","title":"Holy Spirit, Ever Dwelling","language":"en","writers":"Timothy Rees","music":"Thomas J. Williams","year":1922,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"EBENEZER","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nHoly Spirit, ever dwelling in the holiest realms of light Holy Spirit,\never brooding o'er a world of gloom and blight Holy Spirit,\never raising earthbound souls to glory high Living,\nlife-imparting Spirit you we praise and magnify.\n\nVerse 2\nHoly Spirit, ever breathing on the church the breath of life Holy Spirit,\never striving through your people's ceaseless strife Holy Spirit,\never forming in the church the mind of Christ\nIn our worship we will praise you for your fruit and gifts unpriced.\n\nVerse 3\nHoly Spirit, ever working through the church's ministry Quick'ning,\nstrength'ning, and absolving setting captive sinners free Holy Spirit,\never binding age to age and soul to soul\nIn community unending you we worship and extol.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-hosanna-loud-hosanna","title":"Hosanna, Loud Hosanna","language":"en","writers":"Jeanette Threlfall, 1873, alt","music":"from Gesangbuch der Herzogl. Hofkapelle, Wurttemberg","year":1873,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"ELLACOMBE","themes":["Hymn"],"lyrics":"Verse 1\nHosanna, loud hosanna, the little children sang;\nThrough pillared court and temple the lovely anthem rang.\nTo Jesus, Who had blessed them close folded to His breast,\nThe children sang their praises, the simplest and the best.\n\nVerse 2\nFrom Olivet they followed mid an exultant crowd,\nThe victor palm branch waving, and chanting clear and loud.\nThe Lord of men and angels rode on in lowly state,\nNor scorned that little children should on His bidding wait.\n\nVerse 3\n\"Hosanna in the highest!\" that ancient song we sing,\nFor Christ is our Redeemer, the Lord of heav'n our King.\nO may we ever praise Him with heart and life and voice,\nAnd in His blissful presence eternally rejoice!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-how-firm-a-foundation","title":"How Firm A Foundation","language":"en","writers":"John Rippon","music":"Joseph Funk","year":1787,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"FOUNDATION (FUNK)","themes":["Hymn"],"lyrics":"Verse 1\nHow firm a foundation, ye saints of the Lord,\nIs laid for your faith in His excellent Word!\nWhat more can He say than to you He hath said,\nYou, who unto Jesus for refuge have fled?\n\nVerse 2\nIn every condition, in sickness, in health;\nIn poverty's vale, or abounding in wealth;\nAt home and abroad, on the land, on the sea,\nAs thy days demand, shall thy strength ever be.\n\nVerse 3\nFear not, I am with thee,\nO be not dismayed,\nFor I am thy God and will still give thee aid;\nI'll strengthen and help thee,\nand cause thee to stand Upheld by My righteous, omnipotent hand.\n\nVerse 4\nWhen through the deep waters I call thee to go,\nThe rivers of woe shall not thee overflow;\nFor I will be with thee, thy troubles to bless,\nAnd sanctify to thee thy deepest distress.\n\nVerse 5\nWhen through fiery trials thy pathways shall lie,\nMy grace, all sufficient, shall be thy supply;\nThe flame shall not hurt thee;\nI only design Thy dross to consume, and thy gold to refine.\n\nVerse 6\nEven down to old age all My people shall prove\nMy sovereign, eternal, unchangeable love;\nAnd when hoary hairs shall their temples adorn,\nLike lambs they shall still in My bosom be borne.\n\nVerse 7\nThe soul that on Jesus has leaned for repose,\nI will not, I will not desert to its foes;\nThat soul, though all hell should endeavor to shake,\nI'll never, no never, no never forsake.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-i-am-jesus-little-lamb","title":"I Am Jesus' Little Lamb","language":"en","writers":"Henrietta L. von Hayn, 1778. Translation composite","music":"from Bruder Choral-Buch","year":1778,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"WEIL ICH JESU SCHÄFLEIN BIN","themes":["Hymn"],"lyrics":"Verse 1\nI am Jesus' little lamb,\nEver glad at heart I am;\nFor my Shepherd gently guides me,\nKnows my need, and well provides me,\nLoves me ev'ry day the same,\nEven calls me by my name.\n\nVerse 2\nDay by day, at home, away,\nJesus is my Staff and Stay.\nWhen I hunger, Jesus feeds me,\nInto pleasant pastures leads me;\nWhen I thirst, He bids me go Where the quiet waters flow.\n\nVerse 3\nWho so happy as I am,\nEven now the Shepherd's lamb?\nAnd when my short life is ended,\nBy His angel host attended,\nHe shall fold me to His breast,\nThere within His arms to rest.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-i-bind-unto-myself-today","title":"I Bind Unto Myself Today","language":"en","writers":"attributed to St. Patrick of Ireland (circa 387-466). Paraphrased by Cecil F. Alexander","music":"Charles V. Stanford","year":1889,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"ST. PATRICKS BREASTPLATE","themes":["Hymn"],"lyrics":"Verse 1\nAgainst the demon snares of sin,\nThe vice that gives temptation force,\nThe natural lusts that war within,\nThe hostile men that mar my course;\nOr few or many, far or nigh,\nIn every place and in all hours,\nAgainst their fierce hostility\nI bind to me these holy powers.\n\nVerse 2\nAgainst all Satan's spells and wiles,\nAgainst false words of heresy,\nAgainst the knowledge that defiles,\nAgainst the heart's idolatry,\nAgainst the wizard's evil craft,\nAgainst the death wound and the burning,\nThe choking wave, the poisoned shaft,\nProtect me, Christ, till Thy returning.\n\nVerse 3\nChrist be with me, Christ within me,\nChrist behind me, Christ before me,\nChrist beside me, Christ to win me,\nChrist to comfort and restore me.\nChrist beneath me, Christ above me,\nChrist in quiet, Christ in danger,\nChrist in hearts of all that love me,\nChrist in mouth of friend and stranger.\n\nVerse 4\nI bind unto myself the Name,\nThe strong Name of the Trinity,\nBy invocation of the same,\nThe Three in One and One in Three.\nBy Whom all nature hath creation,\nEternal Father, Spirit, Word:\nPraise to the Lord of my salvation,\nSalvation is of Christ the Lord.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-i-come-o-savior-to-thy-table","title":"I Come, O Savior, To Thy Table","language":"en","writers":"Friedrich C. Heyder, 1710. Translation composite","music":"from Emskirchner Choralbuch","year":1710,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"ICH STERBE TÄGLICH","themes":["Hymn","Communion"],"lyrics":"Verse 1\nI come, O Savior, to Thy table,\nFor weak and weary is my soul;\nThou, Bread of Life, alone art able To satisfy and make me whole:\n\nChorus\nLord, may Thy body and Thy blood Be for my soul the highest good!\n\nVerse 2\nOh, grant that I in manner worthy\nMay now approach Thy heav'nly board And,\nas I lowly bow before Thee,\nLook only unto Thee, O Lord!\n\nVerse 3\nUnworthy though I am,\nO Savior, Because I have a sinful heart,\nYet Thou Thy lamb wilt banish never,\nFor Thou my faithful Shepherd art:\n\nVerse 4\nOh, let me loathe all sin forever As death and poison to my soul\nThat I through willful sinning never\nMay see Thy judgment take its toll!\n\nVerse 5\nThy heart is filled with fervent yearning\nThat sinners may salvation see Who,\nLord, to Thee in faith are turning;\nSo I, a sinner, come to Thee.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-i-heard-the-bells-on-christmas-day","title":"I Heard The Bells On Christmas Day","language":"en","writers":"Henry Wadsworth Longfellow","music":"John B. Calkin","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"WALTHAM (CALKIN)","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nI heard the bells on Christmas day Their old familiar carols play,\nAnd wild and sweet the words repeat Of peace on earth,\ngood will to men.\n\nVerse 2\nAnd thought how, as the day had come,\nThe belfries of all Christendom\nHad rolled along th'unbroken song Of peace on earth,\ngood will to men.\n\nVerse 3\nTill ringing, singing on its way The world revolved from night to day,\nA voice, a chime, a chant sublime Of peace on earth, good will to men.\n\nVerse 4\nAnd in despair I bowed my head \"There is no peace on earth,\" I said,\n\"For hate is strong and mocks the song Of peace on earth,\ngood will to men.\"\n\nVerse 5\nThen pealed the bells more loud and deep:\n\"God is not dead, nor doth He sleep;\nThe wrong shall fail,\nthe right prevail With peace on earth, good will to men.\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-i-know-that-my-redeemer-lives","title":"I Know That My Redeemer Lives","language":"en","writers":"Samuel Medley","music":"John Hatton","year":1775,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"DUKE STREET","themes":["Hymn"],"lyrics":"Verse 1\nI know that my Redeemer lives;\nWhat comfort this sweet sentence gives!\nHe lives, He lives, who once was dead;\nHe lives, my ever living Head.\n\nVerse 2\nHe lives to bless me with His love,\nHe lives to plead for me above.\nHe lives my hungry soul to feed,\nHe lives to help in time of need.\n\nVerse 3\nHe lives triumphant from the grave,\nHe lives eternally to save,\nHe lives all glorious in the sky,\nHe lives exalted there on high.\n\nVerse 4\nHe lives to grant me rich supply,\nHe lives to guide me with His eye,\nHe lives to comfort me when faint,\nHe lives to hear my soul's complaint.\n\nVerse 5\nHe lives to silence all my fears,\nHe lives to wipe away my tears He lives to calm my troubled heart,\nHe lives all blessings to impart.\n\nVerse 6\nHe lives, my kind, wise, heavenly Friend,\nHe lives and loves me to the end;\nHe lives, and while He lives, Ill sing;\nHe lives, my Prophet, Priest, and King.\n\nVerse 7\nHe lives and grants me daily breath;\nHe lives, and I shall conquer death:\nHe lives my mansion to prepare;\nHe lives to bring me safely there.\n\nVerse 8\nHe lives, all glory to His Name!\nHe lives, my Jesus, still the same.\nOh, the sweet joy this sentence gives,\nI know that my Redeemer lives!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-i-know-whom-i-have-believed","title":"I Know Whom I Have Believed","language":"en","writers":"Daniel Webster Whittle (a.k.a. Elias Nathan)","music":"James McGranahan","year":1883,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"I KNOW WHOM I HAVE BELIEVED","themes":["Hymn"],"lyrics":"Verse 1\nI know not why God's wondrous grace To me He hath made known,\nNor why, unworthy, Christ in love Redeemed me for His own.\n\nChorus\nBut I know Whom I have believèd,\nAnd am persuaded that He is able\nTo keep that which I've committed Unto Him against that day.\n\nVerse 2\nI know not how this saving faith To me He did impart,\nNor how believing in His Word Wrought peace within my heart.\n\nVerse 3\nI know not how the Spirit moves,\nConvincing us of sin,\nRevealing Jesus through the Word,\nCreating faith in Him.\n\nVerse 4\nI know not what of good or ill May be reserved for me,\nOf weary ways or golden days,\nBefore His face I see.\n\nVerse 5\nI know not when my Lord may come,\nAt night or noonday fair,\nNor if I walk the vale with Him,\nOr meet Him in the air.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-i-need-thee-every-hour","title":"I Need Thee Every Hour","language":"en","writers":"Annie Sherwood Hawks","music":"Robert Lowry","year":1872,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"I NEED THEE EVERY HOUR","themes":["Hymn"],"lyrics":"Verse 1\nI need Thee ev'ry hour,\nMost gracious Lord; No tender voice like Thine Can peace afford.\n\nChorus\nI need Thee, O I need Thee;\nEv'ry hour I need Thee;\nO bless me now, my Savior,\nI come to Thee!\n\nVerse 2\nI need Thee ev'ry hour,\nStay Thou near by;\nTemptations lose their pow'r When Thou art nigh.\n\nVerse 3\nI need Thee ev'ry hour,\nIn joy or pain;\nCome quickly and abide,\nOr life is vain.\n\nVerse 4\nI need Thee ev'ry hour,\nTeach me Thy will;\nAnd Thy rich promises In me fulfill.\n\nVerse 5\nI need Thee ev'ry hour,\nMost Holy One; O make me Thine indeed, Thou blessed Son!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-i-place-my-trust-in-god","title":"I Place My Trust In God","language":"en","writers":"verses by Dorothy Amstutz, 2007. Refrain by Loren J. Kropf, 2010","music":"Loren J. Kropf, 2010. Music, Setting, and refrain verified as public domain by Loren Kropf August 19, 2011. This score is a part of the Open Hymnal Project, 2011 Revision","rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"HALY - TRUST","themes":["Hymn"],"lyrics":"Verse 1\nI placed my trust in God today,\nFor it is He who knows the way,\nAnd when uncertainties arise,\nI trust His judgment, true and wise.\n\nChorus\nI'll place my trust in God today,\nEven when I cannot see the way,\nHe'll lead me on with His strong hand,\nUntil I reach the promised land.\n\nVerse 2\nI placed my trust in God today,\nAlone I could not find my way.\nLed by His guidance, safe and sure,\nI then can rest in peace, secure.\n\nVerse 3\nI place my trust in God each day,\nCommitted, yielded to His way.\nNaught can o'erthrow me when I'm there Beneath His everlasting care.\n\nVerse 4\nI'll place my trust in God each day,\nAnd while I walk the narrow way,\nEach burden God will help me bear;\nHe hears my cry, my ev'ry prayer.\n\nVerse 5\nI'll place my trust in God each day,\nYes, even though the skies are gray.\nLed by His hand,\nI will not fear;\nI know that God is always near.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-i-sing-the-mighty-power-of-god","title":"I Sing the Mighty Power of God","language":"en","writers":"Isaac Watts","music":"from Gesangbuch der Herzogl. Hofkapelle, Wurttemberg","year":1709,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"ELLACOMBE","themes":["Hymn"],"lyrics":"Verse 1\nI sing the mighty pow'r of God,\nThat made the mountains rise;\nThat spread the flowing seas abroad,\nAnd built the lofty skies.\nI sing the wisdom that ordained The sun to rule the day:\nThe moon shines full at His command,\nAnd all the stars obey.\n\nVerse 2\nI sing the goodness of the Lord,\nThat filled the earth with food:\nHe formed the creatures with His word,\nAnd then pronounced them good.\nLord, how Thy wonders are displayed,\nWhere'er I turn my eye;\nIf I survey the ground I tread,\nOr gaze upon the sky.\n\nVerse 3\nThere's not a plant or flow'r below,\nBut makes Thy glories known;\nAnd clouds arise and tempests blow,\nBy order from Thy throne.\nCreatures that borrow life from Thee Are subject to Thy care:\nThere's not a place where we can flee,\nBut God is present there.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-if-god-had-not-been-on-our-side","title":"If God Had Not Been on Our Side","language":"en","writers":"Martin Luther, 1524. Translation composite","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"WÄR GOTT NICHT MIT UNS DIESE ZEIT (1524)","themes":["Hymn"],"lyrics":"Verse 1\nIf God had not been on our side And had not come to aid us,\nThe foes with all their pow'r and pride Would surely have dismayed us;\nFor we, His flock,\nwould have to fear The threat of men both far and near\nWho rise in might against us.\n\nVerse 2\nTheir furious wrath, did God permit,\nWould surely have consumed us And as a deep and yawning pit\nWith life and limb entombed us.\nLike men o'er whom dark waters roll\nTheir wrath would have engulfed our soul And,\nlike a flood, o'erwhelmed us.\n\nVerse 3\nBlest be the Lord,\nwho foiled their threat That they could not devour us;\nOur souls, like birds, escaped their net,\nThey could not overpow'r us.\nThe snare is broken we are free!\nOur help is ever,\nLord, in Thee, Who madest earth and heaven.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-if-god-himself-be-for-me","title":"If God Himself Be For Me","language":"en","writers":"Paul Gerhardt, 1656. Verses 1-3, 7-9, 11-15 Translated by Richard Massie, 1856, alt. Verses 4-6,10 Translated for Evangelical Lutheran Hymn-Book (Pittsburgh), 1907, alt","music":"traditional German found in \"Memminger Tabulaturbuche\", 17th Century","year":1656,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"WOODBIRD","themes":["Hymn"],"lyrics":"Verse 1\nIf God Himself be for me,\nI may a host defy;\nFor when I pray, before me My foes, confounded, fly.\nIf Christ, my Head and Master,\nBefriend me from above,\nWhat foe or what disaster Can drive me from His love?\n\nVerse 2\nThis I believe, yea, rather,\nOf this I make my boast,\nThat God is my dear Father,\nThe Friend who loves me most,\nAnd that, whate'er betide me,\nMy Savior is at hand Through stormy seas to guide me\nAnd bring me safe to land.\n\nVerse 3\nI build on this foundation,\nThat Jesus and His blood Alone are my salvation,\nThe true, eternal good.\nWithout Him all that pleases Is valueless on earth;\nThe gifts I owe to Jesus Alone my love are worth.\n\nVerse 4\nMy Jesus is my Splendor,\nMy Sun, my Light, alone;\nWere He not my Defender Before God's awe-full throne,\nI never should find favor And mercy in His sight,\nBut be destroyed forever As darkness by the light.\n\nVerse 5\nHe canceled my offenses,\nDelivered me from death;\nHe is the Lord who cleanses My soul from sin through faith.\nIn Him I can be cheerful,\nBold, and undaunted aye;\nIn Him I am not fearful Of God's great Judgment Day.\n\nVerse 6\nNaught, naught, can now condemn me Nor set my hope aside;\nNow hell no more can claim me, Its fury I deride.\nNo sentence e'er reproves me, No ill destroys my peace;\nFor Christ, my Savior, loves me And shields me with His grace.\n\nVerse 7\nHis Spirit in me dwelleth, And o'er my mind He reigns.\nAll sorrow He dispelleth And soothes away all pains.\nHe crowns His work with blessing And helpeth me to cry,\n\"My Father!\" without ceasing, To Him who dwells on high.\n\nVerse 8\nAnd when my soul is lying Weak, trembling, and opprest,\nHe pleads with groans and sighing That cannot be exprest;\nBut God's quick eye discerns them, Although they give no sound,\nAnd into language turns them E'en in the heart's deep ground.\n\nVerse 9\nTo mine His Spirit speaketh Sweet word of holy cheer,\nHow God to him that seeketh For rest is always near\nAnd how He hath erected A city fair and new,\nWhere what our faith expected We evermore shall view.\n\nVerse 10\nIn yonder home doth flourish My heritage, my lot;\nThough here I die and perish, My heaven shall fail me not.\nThough care my life oft saddens And causeth tears to flow,\nThe light of Jesus gladdens And sweetens every woe.\n\nVerse 11\nWho clings with resolution To Him whom Satan hates\nMust look for persecution; For him the burden waits\nOf mockery, shame, and losses, Heaped on his blameless head;\nA thousand plagues and crosses Will be his daily bread.\n\nVerse 12\nFrom me this is not hidden, Yet I am not afraid;\nI leave my cares, as bidden, To whom my vows were paid.\nThough life and limb it cost me And everything I won,\nUnshaken shall I trust Thee And cleave to Thee alone.\n\nVerse 13\nThough earth be rent asunder, Thou'rt mine eternally;\nNot fire nor sword nor thunder Shall sever me from Thee;\nNot hunger, thirst, nor danger, Not pain nor poverty\nNor mighty princes' anger Shall ever hinder me.\n\nVerse 14\nNo angel and no gladness, No throne, no pomp, no show,\nNo love, no hate, no sadness, No pain, no depth of woe,\nNo scheme of man's contrivance, However small or great,\nShall draw me from Thy guidance Nor from Thee separate.\n\nVerse 15\nMy heart for joy is springing And can no more be sad,\n'Tis full of mirth and singing, Sees naught but sunshine glad.\nThe Sun that cheers my spirit Is Jesus Christ, my King;\nThat which I shall inherit Makes me rejoice and sing.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11","Verse 12","Verse 13","Verse 14","Verse 15"],"source":"Open Hymnal Project"},{"id":"oh-i-m-but-a-stranger-here","title":"I'm But A Stranger Here","language":"en","writers":"Thomas Rawson Taylor","music":"Arthur Seymour Sullivan","year":1836,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. EDMUND (SULLIVAN)","themes":["Hymn"],"lyrics":"Verse 1\nI'm but a stranger here,\nHeav'n is my home;\nEarth is a desert drear,\nHeav'n is my home.\nDanger and sorrow stand round me on every hand;\nHeav'n is my fatherland,\nHeav'n is my home.\n\nVerse 2\nWhat though the tempest rage,\nHeav'n is my home;\nShort is my pilgrimage,\nHeav'n is my home;\nTime's wild and wintry blast soon shall be over past;\nI shall reach home at last,\nHeav'n is my home.\n\nVerse 3\nThere at my Savior's side Heav'n is my home;\nI shall be glorified,\nHeav'n is my home.\nThere are the good and blest, those I loved most and best;\nThere, too, I soon shall rest,\nHeav'n is my home.\n\nVerse 4\nTherefore I murmur not,\nHeav'n is my home;\nWhate'er my earthly lot,\nHeav'n is my home;\nAnd I shall surely stand there at my Lord's right hand.\nHeav'n is my fatherland,\nHeav'n is my home.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-immortal-invisible-god-only-wise","title":"Immortal, Invisible, God Only Wise","language":"en","writers":"Walter Chalmers Smith","music":"traditional Welsh found in \"Caniadau y Cyssegr\" by John Roberts","year":1876,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. DENIO","themes":["Hymn"],"lyrics":"Verse 1\nImmortal, invisible, God only wise,\nIn light inaccessible hid from our eyes,\nMost blessèd, most glorious, the Ancient of Days,\nAlmighty, victorious, Thy great Name we praise.\n\nVerse 2\nUnresting, unhasting, and silent as light,\nNor wanting, nor wasting,\nThou rulest in might;\nThy justice, like mountains, high soaring above Thy clouds,\nwhich are fountains of goodness and love.\n\nVerse 3\nTo all, life Thou givest, to both great and small;\nIn all life Thou livest, the true life of all;\nWe blossom and flourish as leaves on the tree,\nAnd wither and perish but naught changeth Thee.\n\nVerse 4\nGreat Father of glory, pure Father of light,\nThine angels adore Thee, all veiling their sight;\nBut of Thy rich graces this grace,\nLord, impart Take the veil from our face, the vile from our heart.\n\nVerse 5\nAll laud we would render;\nO help us to see 'Tis only the splendor of light hideth Thee,\nAnd so let Thy glory, almighty, impart,\nThrough Christ in His story,\nThy Christ to the heart.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-in-his-temple-now-behold-him","title":"In His Temple Now Behold Him","language":"en","writers":"verses 1-3, Henry J. Pye, 1851. verse 4, William Cooke","music":"Henry Purcell","year":1851,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"WESTMINSTER ABBEY","themes":["Hymn"],"lyrics":"Verse 1\nIn His temple now behold Him,\nSee the long expected Lord;\nAncient prophets had foretold Him;\nGod has now fulfilled His word.\nNow to praise Him,\nHis redeemèd Shall break forth with one accord.\n\nVerse 2\nIn the arms of her who bore Him,\nVirgin pure, behold Him lie,\nWhile his agèd saints adore Him Ere in faith and hope they die.\nHallelujah! Hallelujah! Lo, th'incarnate God most high.\n\nVerse 3\nJesus, by Thy presentation,\nThou, who didst for us endure,\nMake us see our great salvation,\nSeal us with Thy promise sure.\nAnd present us in Thy glory To Thy Father, cleansed and pure.\n\nVerse 4\nPrince and Author of salvation,\nBe Thy boundless love our theme!\nJesus, praise to Thee be given By the world Thou didst redeem.\nWith the Father and the Spirit,\nLord of majesty supreme!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-in-peace-and-joy-i-now-depart","title":"In Peace and Joy I Now Depart","language":"en","writers":"Martin Luther, 1524. Translated by Leonard Woolsey Bacon, 1884, alt","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"MIT FRIED UND FREUD ICH FAR DAHIN","themes":["Hymn"],"lyrics":"Verse 1\nIn peace and joy I now depart At God's disposing;\nFor full of comfort is my heart,\nSoft reposing. So the Lord hath promised me,\nAnd death is but a slumber.\n\nVerse 2\n'Tis Christ that wrought this work for me,\nMy faithful Savior, Whom Thou hast made mine eyes to see By Thy favor.\nNow I know He is my Life,\nMy Help in need and dying.\n\nVerse 3\nHim Thou hast unto all set forth Their great\nSalvation And to His kingdom called the earth,\nEvery nation, By Thy dear and wholesome Word,\nIn every place resounding.\n\nVerse 4\nHe is the Hope and saving Light Of lands benighted;\nBy Him are they who dwelt in night Fed and lighted.\nHe is Israel's Praise and Bliss,\nTheir Joy, Reward, and Glory.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-in-the-bleak-midwinter","title":"In The Bleak MidWinter","language":"en","writers":"Christina Georgina Rossetti, 1872, alt","music":"Gustav Theodore Holst, 1906, alt","year":1872,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"CRANHAM","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nIn the bleak midwinter, frosty wind made moan,\nEarth stood hard as iron, water like a stone;\nSnow had fallen, snow on snow, snow on snow on snow,\nIn the bleak midwinter, long ago.\n\nVerse 2\nOur God, Heav'n cannot hold Him, nor earth sustain;\nHeav'n and earth shall flee away when He comes to reign.\nIn the bleak midwinter a stable place sufficed\nThe Lord God Almighty, Jesus Christ.\n\nVerse 3\nEnough for Him, whom cherubim, worship night and day,\nBreastful of milk, and a mangerful of hay;\nEnough for Him, whom angels fall down before,\nOx and ass and camel which adore.\n\nVerse 4\nAngels and archangels may have gathered there,\nCherubim and seraphim thronged the air;\nBut His mother only, in her maiden bliss,\nWorshiped the beloved with a kiss.\n\nVerse 5\nWhat can I give Him, poor as I am?\nIf I were a shepherd,\nI would bring a lamb;\nIf I were a Wise Man,\nI would do my part;\nYet what can I give Him: give my heart.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-in-these-our-days-so-perilous","title":"In These Our Days So Perilous","language":"en","writers":"Latin c. 6th century, adapted by Martin Luther, 1529. Translated to English by Richard Massie, 1854, alt","music":"Martin Luther. Found in Klug's Geistliche Lieder","year":1529,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"VERLEIH UNS FRIEDEN GNÄDIGLICH","themes":["Hymn"],"lyrics":"Verse 1\nIn these our days so perilous,\nLord, peace in mercy send us;\nNo God but Thee can fight for us,\nNo God but Thee defend us;\nThou our only God and Savior.","arrangement":["Verse 1"],"source":"Open Hymnal Project"},{"id":"oh-isaiah-mighty-seer-in-days-of-old","title":"Isaiah, Mighty Seer, In Days of Old","language":"en","writers":"Martin Luther, 1526 as the Sanctus of the German Mass, after Is 6:1-4. Translation composite","music":"Martin Luther, 1526 in the German Mass","year":1526,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"JESAIA DEM PROPHETEN DAS GESCHAH","themes":["Hymn"],"lyrics":"Verse 1\nIsaiah, mighty seer,\nin days of old The Lord of all in\nSpirit did behold High on a lofty throne,\nin splendor bright,\nWith flowing train that filled the Temple quite.\nAbove the throne were stately seraphim,\nSix wings had they, these messengers of Him.\nWith twain they veiled their faces, as was meet,\nWith twain in reverent awe they hid their feet,\nAnd with the other twain aloft they soared,\nOne to the other called and praised the Lord:\n\"Holy is God, the Lord of Sabaoth!\nHoly is God, the Lord of Sabaoth!\nHoly is God, the Lord of Sabaoth!\nBehold, His glory filleth all the earth!\"\nThe beams and lintels trembled at the cry,\nAnd clouds of smoke enwrapped the throne on high.","arrangement":["Verse 1"],"source":"Open Hymnal Project"},{"id":"oh-it-came-upon-a-midnight-clear","title":"It Came Upon A Midnight Clear","language":"en","writers":"Edmund H. Sears","music":"Richard S. Willis","year":1849,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"CAROL","themes":["Hymn","Christmas","Evening"],"lyrics":"Verse 1\nIt came upon the midnight clear,\nThat glorious song of old,\nFrom angels bending near the earth,\nTo touch their harps of gold;\n\"Peace on the earth, good will to men,\nFrom Heaven's all gracious King.\" The world in solemn stillness lay,\nTo hear the angels sing.\n\nVerse 2\nStill through the cloven skies they come With peaceful wings unfurled,\nAnd still their heavenly music floats O'er all the weary world;\nAbove its sad and lowly plains,\nThey bend on hov'ring wing,\nAnd ever over its Babel sounds The blessèd angels sing.\n\nVerse 3\nYet with the woes of sin and strife The world has suffered long;\nBeneath the angel strain have rolled Two thousand years of wrong;\nAnd man, at war with man, hears not The love-song which they bring;\nO hush the noise, ye men of strife And hear the angels sing.\n\nVerse 4\nAnd ye, beneath life's crushing load,\nWhose forms are bending low,\nWho toil along the climbing way With painful steps and slow,\nLook now! for glad and golden hours Come swiftly on the wing.\nO rest beside the weary road,\nAnd hear the angels sing!\n\nVerse 5\nFor lo! the days are hast'ning on,\nBy prophet-bards foretold,\nWhen with the ever circling years Comes round the age of gold;\nWhen peace shall over all the earth Its ancient splendors fling,\nAnd the whole world send back the song Which now the angels sing.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-it-is-well-with-my-soul","title":"It Is Well With My Soul","language":"en","writers":"Horatio G. Spafford","music":"Philip P. Bliss","year":1873,"rights":"public-domain","copyright":"Public domain","defaultKey":"Db","bpm":null,"tune":"IT IS WELL","themes":["Hymn"],"lyrics":"Verse 1\nWhen peace, like a river, attendeth my way,\nWhen sorrows like sea billows roll;\nWhatever my lot, Thou has taught me to say,\nIt is well, it is well, with my soul. It is\n\nChorus\nwell, with my soul,\nIt is well, it is well with my soul.\n\nVerse 2\nThough Satan should buffet, though trials should come,\nLet this blest assurance control,\nThat Christ has regarded my helpless estate,\nAnd hath shed His own blood for my soul.\n\nVerse 3\nMy sin, oh, the bliss of this glorious thought!\nMy sin, not in part but the whole,\nIs nailed to the cross, and I bear it no more,\nPraise the Lord, praise the Lord, O my soul!\n\nVerse 4\nFor me, be it Christ, be it Christ hence to live:\nIf Jordan above me shall roll,\nNo pang shall be mine,\nfor in death as in life Thou wilt whisper Thy peace to my soul.\n\nVerse 5\nBut, Lord, 'tis for Thee, for Thy coming we wait,\nThe sky, not the grave, is our goal;\nOh trump of the angel!\nOh voice of the Lord!\nBlessèd hope, blessèd rest of my soul!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-jerusalem-the-golden","title":"Jerusalem the Golden","language":"en","writers":"Bernard of Cluny, 1146. Translated by John Mason Neale","music":"Alexander C. Ewing","year":1146,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"EWING","themes":["Hymn"],"lyrics":"Verse 1\nJerusalem the golden, with milk and honey blest,\nBeneath thy contemplation sink heart and voice oppressed.\nI know not, O I know not, what joys await us there,\nWhat radiancy of glory, what bliss beyond compare.\n\nVerse 2\nThey stand, those halls of Zion, all jubilant with song,\nAnd bright with many'an angel, and all the martyr throng;\nThe Prince is ever in them, the daylight is serene.\nThe pastures of the blessèd are decked in glorious sheen.\n\nVerse 3\nThere is the throne of David, and there, from care released,\nThe shout of them that triumph, the song of them that feast;\nAnd they are with their Leader, who conquered in the fight,\nAnd won for them forever their gleaming robes of white.\n\nVerse 4\nO sweet and blessèd country, the home of God's elect!\nO sweet and blessèd country, that eager hearts expect!\nJesus, in mercy bring us to that dear land of rest,\nWho art, with God the Father, and Spirit, ever blessed.\n\nVerse 5\nBrief life is here our portion, brief sorrow, short lived care;\nThe life that knows no ending, the tearless life, is there.\nO happy retribution! Short toil, eternal rest;\nFor mortals and for sinners, a mansion with the blest.\n\nVerse 6\nThat we should look, poor wanderers, to have our home on high!\nThat worms should seek for dwellings beyond the starry sky!\nAnd now we fight the battle, but then shall wear the crown\nOf full and everlasting, and passionless renown.\n\nVerse 7\nAnd how we watch and struggle, and now we live in hope,\nAnd Zion in her anguish with Babylon must cope;\nBut he whom now we trust in shall then be seen and known,\nAnd they that know and see Him shall have Him for their own.\n\nVerse 8\nFor thee, O dear, dear country, mine eyes their vigils keep;\nFor very love, beholding, thy happy name, they weep:\nThe mention of thy glory is unction to the breast,\nAnd medicine in sickness, and love, and life, and rest.\n\nVerse 9\nO one, O only mansion! O paradise of joy!\nWhere tears are ever banished, and smiles have no alloy;\nThe cross is all thy splendor, the Crucified thy praise,\nHis laud and benediction thy ransomed people raise.\n\nVerse 10\nJerusalem the glorious! Glory of the elect!\nO dear and future vision that eager hearts expect!\nE'en now by faith I see thee, e'en here thy walls discern;\nTo thee my thoughts are kindled, and strive, and pant, and yearn.\n\nVerse 11\nJerusalem, the only, that look'st from heaven below,\nIn thee is all my glory, in me is all my woe!\nAnd though my body may not, my spirit seeks thee fain,\nTill flesh and earth return me to earth and flesh again.\n\nVerse 12\nJerusalem, exulting on that securest shore,\nI hope thee, wish thee, sing thee, and love thee evermore!\nI ask not for my merit: I seek not to deny\nMy merit is destruction, a child of wrath am I.\n\nVerse 13\nBut yet with faith I venture and hope upon the way,\nFor those perennial guerdons I labor night and day.\nThe best and dearest Father Who made me, and Who saved,\nBore with me in defilement, and from defilement laved.\n\nVerse 14\nWhen in His strength I struggle, for very joy I leap;\nWhen in my sin I totter, I weep, or try to weep:\nAnd grace, sweet grace celestial, shall all its love display,\nAnd David's royal fountain purge every stain away.\n\nVerse 15\nO sweet and blessèd country, shall I e'er see thy face?\nO sweet and blessèd country, shall I e'er win thy grace?\nI have the hope within me to comfort and to bless!\nO shall I e'er win the prize? O tell me, tell me, Yes!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11","Verse 12","Verse 13","Verse 14","Verse 15"],"source":"Open Hymnal Project"},{"id":"oh-jesus-came-the-heavens-adoring","title":"Jesus Came, the Heavens Adoring","language":"en","writers":"Godfrey Thring","music":"from Geistreiches Gesangbuch Darmstadt, Germany","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"SIEH, HIER BIN ICH, EHRENKOENIG","themes":["Hymn"],"lyrics":"Verse 1\nJesus came, the heav'ns adoring,\nCame with peace from realms on high;\nJesus came for man's redemption,\nLowly came on earth to die.\nAlleluia! Alleluia! Came in deep humility.\n\nVerse 2\nJesus comes again in mercy,\nWhen our hearts are bowed with care;\nJesus comes again in answer To an earnest, heartfelt prayer;\nAlleluia! Alleluia! Comes to save us from despair.\n\nVerse 3\nJesus comes to hearts rejoicing,\nBringing news of sins forgiv'n;\nJesus comes in sounds of gladness,\nLeading souls redeemed to Heav'n;\nAlleluia! Alleluia! Now the gate of death is riv'n.\n\nVerse 4\nJesus comes in joy and sorrow,\nShares alike our hopes and fears;\nJesus comes, whate'er befalls us,\nGlads our hearts, and dries our tears;\nAlleluia! Alleluia! Cheering e'en our failing years.\n\nVerse 5\nJesus comes on clouds triumphant,\nWhen the heav'ns shall pass away;\nJesus comes again in glory;\nLet us then our homage pay,\nAlleluia! Alleluia! Till the dawn of endless day.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-jesus-christ-is-risen-today","title":"Jesus Christ Is Risen Today","language":"en","writers":"14th Century Bohemian Latin carol. Stanzas 1-3 translated in John Arnold's Compleat Psalmist, 1749. Stanza 4 Charles Wesley, 1740, alt","music":"from Lyra Davidica","year":1749,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"EASTER HYMN","themes":["Hymn","Easter"],"lyrics":"Verse 1\nJesus Christ is ris'n today,\nAlleluia! Our triumphant holy day,\nAlleluia! Who did once, upon the cross,\nAlleluia! Suffer to redeem our loss, Alleluia!\n\nVerse 2\nHymns of praise then let us sing,\nAlleluia! Unto Christ, our heav'nly King,\nAlleluia! Who endured the cross and grave,\nAlleluia! Sinners to redeem and save, Alleluia!\n\nVerse 3\nBut the pain which He endured,\nAlleluia! Our salvation hath procured,\nAlleluia! Now above the sky He's king,\nAlleluia! Where the angels ever sing, Alleluia!\n\nVerse 4\nSing we to our God above,\nAlleluia! Praise eternal as His love,\nAlleluia! Praise Him, all you heav'nly host,\nAlleluia! Father, Son, and Holy Ghost, Alleluia!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-jesus-christ-our-blessed-savior","title":"Jesus Christ, Our Blessed Savior","language":"en","writers":"John Hus (1369-1415). Expanded by Martin Luther, 1524. Translator v.4,6 by Richard Massie Other verses unknown","music":"from Walter's Geistliche Gesangbüchlein","year":1369,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"JESUS CHRISTUS UNSER HEILAND, DER VON UNS (WALTER)","themes":["Hymn"],"lyrics":"Verse 1\nJesus Christ, our Blessed Savior,\nTurned away God's wrath forever;\nSuff'ring pains no tongue can tell,\nHe saved us from the pains of hell.\n\nVerse 2\nTo remind us that, to save us He hath died,\nHis flesh He gave us With this bread, a quick'ning food,\nAnd with this wine, His precious blood.\n\nVerse 3\nWhoso to this board repaireth,\nTake good heed how He prepareth;\nDeath instead of life shall He Receive who comes unworthily.\n\nVerse 4\nPraise the Father, God in heaven,\nWho such dainty food hath given,\nAnd for misdeeds thou hast done Gave to die His beloved Son.\n\nVerse 5\nThou shalt hold with faith unshaken,\nThat this food is to be taken By the sick who are distressed,\nBy those whose heart is sin-oppressed.\n\nVerse 6\nTo such grace and mercy turneth\nEvery soul that truly mourneth;\nArt thou well? Avoid this board,\nElse thou reapest an ill reward.\n\nVerse 7\nChrist says: \"Come ye heavy-laden,\nI your weary hearts will gladden;\nThey that are yet strong  and well,\nDespise the best physician's skill.\n\nVerse 8\nCouldst thou earn thine own salvation,\nUseless were my death and passion;\nThis feast is not spread for thee,\nIf thine own helper thou wilt be.\n\nVerse 9\nIf thou this believest truly,\nAnd confession makest duly,\nThou a welcome guest art here,\nThis heavenly food thy soul shall cheer.\n\nVerse 10\nBut the fruits must not be missing,\nLove thy neighbor without ceasing,\nThat true love let him receive,\nWhich here to thee thy God doth give.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10"],"source":"Open Hymnal Project"},{"id":"oh-jesus-christ-who-came-to-save","title":"Jesus Christ Who Came to Save","language":"en","writers":"Martin Luther, 1524. Translated by Leonard Woolsey Bacon","music":"from Klug's Geistliche Lieder, Wittenberg","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"JESUS CHRISTUS UNSER HEILAND, DER DEN TOD (KLUG)","themes":["Hymn"],"lyrics":"Verse 1\nJesus Christ, who came to save,\nAnd overcame the grave,\nIs now arisen, And sin hath bound in prison. Kyri' eleison.\n\nVerse 2\nWho withouten sin was found,\nBore our transgression's wound.\nHe is our Savior,\nAnd brings us to God's favor.\n\nVerse 3\nLife and mercy, sin and death,\nAll in His hands He hath;\nThem He'll deliver, Who trust in Him forever.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-jesus-grant-that-balm-and-healing","title":"Jesus Grant That Balm and Healing","language":"en","writers":"Johann Heermann, 1644. Translation composite","music":"Johann Balthasar König","year":1644,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"DER AM KREUZ","themes":["Hymn"],"lyrics":"Verse 1\nJesus, grant that balm and healing In Thy holy wounds I find,\nEvery hour that I am feeling,\nPains of body and of mind.\nShould some evil thought within Tempt my treacherous heart to sin,\nShow the peril, and from sinning Keep me ere its first beginning.\n\nVerse 2\nShould some lust or sharp temptation\nProve too strong for flesh and blood,\nLet me think upon Thy Passion,\nAnd the breach is soon made good.\nOr should Satan press me hard,\nLet me then be on my guard,\nSaying, \"Christ for me was wounded,\" That the tempter flee confounded.\n\nVerse 3\nIf the world my heart entices On the broad and easy road\nWith its mirth and luring vices,\nLet me think upon the load Thou didst carry and endure\nThat I flee all thoughts impure,\nBanishing each wild emotion,\nCalm and blest in my devotion.\n\nVerse 4\nEvery wound that pains or grieves me,\nBy Thy stripes, Lord, is made whole;\nWhen I'm faint, Thy cross revives me,\nGranting new life to my soul.\nYea, Thy comfort renders sweet Every bitter cup I meet;\nFor Thy all atoning Passion Has procured my soul's salvation.\n\nVerse 5\nO my God, my Rock and Tower,\nGrant that in Thy death I trust,\nKnowing death has lost his power Since Thou trodd'st him in the dust.\nSavior, let Thine agony Ever help and comfort me;\nWhen I die, be my Protection,\nLight and Life and Resurrection.\n\nVerse 6\nJesus, grant that balm and healing In Thy holy wounds I find,\nEvery hour that I am feeling, Pains of body and of mind.\nAnd when I this world must leave, Grant that, Lord, to Thee I cleave,\nIn Thy wounds find consolation And obtain my soul's salvation","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-jesus-in-thy-dying-woes","title":"Jesus, In Thy Dying Woes","language":"en","writers":"Thomas B. Pollock","music":"William H. Monk","year":1870,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"WORDS ON THE CROSS - THE LITANY","themes":["Hymn"],"lyrics":"Verse 1\nJesus, in Thy dying woes,\nEven while Thy lifeblood flows,\nCraving pardon for Thy foes;\nHear us, holy Jesus.\n\nVerse 2\nSavior, for our pardon sue,\nWhen our sins Thy pangs renew,\nFor we know not what we do:\nHear us, holy Jesus.\n\nVerse 3\nO may we, who mercy need,\nBe like Thee in heart and deed,\nWhen with wrong our spirits bleed:\nHear us, holy Jesus.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-jesus-is-all-the-world-to-me","title":"Jesus Is All the World To Me","language":"en","writers":"Will L. Thompson, 1904. Music 'Jesus Is All the World To Me' Will L. Thompson","year":1904,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"themes":["Hymn"],"lyrics":"Verse 1\nJesus is all the world to me,\nMy life, my joy, my all;\nHe is my strength from day to day,\nWithout Him I would fall.\nWhen I am sad, to Him I go,\nNo other one can cheer me so;\nWhen I am sad,\nHe makes me glad, He's my friend.\n\nVerse 2\nJesus is all the world to me, my friend in trials sore;\nI go to Him for blessings and He gives them ov'r and o'er.\nHe sends the sunshine and the rain,\nHe sends the harvest's golden grain;\nSunshine and rain, harvest of grain, He's my friend.\n\nVerse 3\nJesus is all the world to me, and true to Him I'll be;\nO how could I this friend deny, when He's so true to me?\nFollowing Him I know I'm right,\nHe watches o'er me day and night;\nFollowing Him, by day and night, He's my friend.\n\nVerse 4\nJesus is all the world to me,\nI want no better friend;\nI trust Him now,\nI'll trust Him when Life's fleeting days shall end.\nBeautiful life with such a friend; beautiful life that has no end;\nEternal life, eternal joy, He's my friend.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-jesus-king-of-glory","title":"Jesus, King of Glory","language":"en","writers":"W. Hope Davison","music":"Franz Joseph Haydn","year":1880,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. ALBAN","themes":["Hymn"],"lyrics":"Verse 1\nJesus, King of glory, throned above the sky,\nJesus, tender Savior, hear Thy children cry.\nPardon our transgressions, cleanse us from our sin,\nBy Thy Spirit help us heav'nly life to win. Jesus, King of\n\nChorus\nglory, throned above the sky,\nJesus, tender Savior, hear Thy children cry.\n\nVerse 2\nOn this day of gladness,\nBending low the knee In thine earthly temple,\nLord, we worship thee;\nCelebrate thy goodness, Mercy, grace, and truth,\nAll thy loving guidance Of our heedless youth.\n\nVerse 3\nFor the little children Who have come to thee;\nFor the glad, bright spirits Who thy glory see;\nFor the loved ones resting In thy dear embrace;\nFor the pure and holy Who behold thy face,\n\nVerse 4\nHelp us ever steadfast in the faith to be:\nIn Thy Church's conflicts fighting valiantly.\nLoving Savior, strengthen these weak hearts of ours,\nThrough Thy cross to conquer crafty evil powers.\n\nVerse 5\nWhen the shadows lengthen, show us,\nLord, Thy way; Through the darkness lead us to the heav'nly day;\nWhen our course is finished, ended all the strife,\nGrant us, with the faithful, palms and crowns of life.\n\nVerse 6\nFor thy faithful servants Who have entered in;\nFor thy fearless soldiers Who have conquered sin;\nFor the countless legions Who have followed thee,\nHeedless of the danger, On to victory,","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-jesus-shall-reign","title":"Jesus Shall Reign","language":"en","writers":"Isaac Watts","music":"John Hatton","year":1719,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"DUKE STREET","themes":["Hymn"],"lyrics":"Verse 1\nJesus shall reign where'er the sun Does his successive journeys run;\nHis kingdom stretch from shore to shore\nTill moons shall wax and wane no more.\n\nVerse 2\nFor Him shall endless prayer be made,\nAnd praises throng to crown His head;\nHis Name, like sweet perfume shall rise With every morning sacrifice.\n\nVerse 3\nPeople and realms of every tongue\nDwell on His love with sweetest song;\nAnd infant voices shall proclaim Their early blessings on His Name.\n\nVerse 4\nBlessings abound where'er He reigns;\nThe prisoner leaps to lose his chains,\nThe weary find eternal rest,\nAnd all the sons of want are blest.\n\nVerse 5\nWhere He displays His healing power\nDeath and the curse are known no more;\nIn Him the tribes of Adam boast More blessings than their father lost.\n\nVerse 6\nLet every creature rise and bring\nPeculiar honors to our King,\nAngels descend with songs again,\nAnd earth repeat the loud Amen.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-jesus-sinners-doth-receive","title":"Jesus Sinners Doth Receive","language":"en","writers":"Erdmann Neumeister, 1718. Translated by Henry Mills, 1845 (et al)","music":"Ich Nicht (Darmstadt)' from Neu-verfertigtes Darmstädtiches Gesang-Buch","year":1718,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"MEINEN JESUM LASS","themes":["Hymn"],"lyrics":"Verse 1\nJesus sinners doth receive;\nWell may we this saying ponder Who in sin's delusions live,\nAnd from God and Heaven wander:\nHere is hope for all who grieve — Jesus sinners doth receive.\n\nVerse 2\nWe deserve but grief and shame, — Yet His words, rich grace revealing,\nPardon, peace, and life proclaim;\nHere their ills have perfect healing\nWho with humble hearts believe — Jesus sinners doth receive.\n\nVerse 3\nAs the shepherd seeks to find His lost sheep that from Him strayeth,\nSo hath Christ each soul in mind,\nAnd for its salvation prayeth;\nFain He'd have each wand'rer live:\nJesus sinners doth receive.\n\nVerse 4\nCome, then, all by guilt oppressed,\nJesus calls, and He would make you God's own children, pure and blest,\nAnd to glory He would take you;\nThink on this, and well believe Jesus sinners doth receive.\n\nVerse 5\nSavior, now I come to Thee:\nGreat my sins, a weary burden!\nWilt Thou mercy show to me?\nCan I hope to find a pardon?\nI will trust: my soul relieve!\nMe, a sinner, Lord, receive!\n\nVerse 6\nRich Thy mercy- strangely good!  O how oft have I offended!\nBut through Thy redeeming blood All my fear of wrath is ended:\nYes I now can witness give: Jesus sinners doth receive!\n\nVerse 7\nNow my conscience is at peace; From the Law I stand acquitted;\nChrist hath purchased my release, And my every sin remitted.\nNaught remains my soul to grieve: Jesus sinners doth receive.\n\nVerse 8\nJesus sinners doth receive! Happy in His ceaseless favor,\nHere for Heaven I will live, There shall live with Him forever,\n\"Joy in death these tidings give; Jesus sinners doth receive!\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-jesus-tender-shepherd-hear-me","title":"Jesus, Tender Shepherd, Hear Me","language":"en","writers":"Mary L. Duncan","music":"John Stainer","year":1839,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"EVENING PRAYER","themes":["Hymn"],"lyrics":"Verse 1\nJesus, tender Shepherd, hear me;\nBless Thy little lamb tonight;\nThrough the darkness be Thou near me;\nWatch my sleep till morning light.\n\nVerse 2\nAll this day thy hand has led me,\nAnd I thank Thee for Thy care;\nThou hast clothed me, warmed and fed me,\nListen to my evening prayer.\n\nVerse 3\nLet my sins be all forgiven;\nBless the friends I love so well;\nTake me, when I die, to heaven,\nHappy there with Thee to dwell.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-jesus-thy-boundless-love-to-me","title":"Jesus, Thy Boundless Love To Me","language":"en","writers":"Paul Gerhardt, 1653. Translated by John Wesley","music":"William Yoakley","year":1653,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"YOAKLEY","themes":["Hymn"],"lyrics":"Verse 1\nJesus, Thy boundless love to me No thought can reach,\nno tongue declare;\nUnite my thankful heart with Thee And reign without a rival there.\nTo Thee alone, dear Lord,\nI live; Myself to Thee, dear Lord, I give.\n\nVerse 2\nO, grant that nothing in my soul May dwell but Thy pure love alone!\nOh, may Thy love possess me whole,\nMy joy, my treasure, and my crown!\nAll coldness from my heart remove;\nMy every act, word, thought, be love.\n\nVerse 3\nO love, how cheering is thy ray!\nAll pain before thy presence flies;\nCare, anguish, sorrow, melt away Where'er thy healing beams arise.\nO Jesus, nothing may I see,\nNothing desire or seek, but Thee!\n\nVerse 4\nThis love unwearied I pursue And dauntlessly to Thee aspire.\nOh, may Thy love my hope renew Burn in my soul like heav'nly fire!\nAnd day and night be all my care To guard this sacred treasure there.\n\nVerse 5\nMy Savior, Thou Thy love to me In shame,\nin want, in pain, hast showed;\nFor me, on the accursed tree,\nThou pourest forth Thy guiltless blood;\nThy wounds upon my heart impress,\nNor aught shall the lov'd stamp efface.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-jesus-wants-all-of-his-children","title":"Jesus Wants All Of His Children","language":"en","writers":"verses 1-5 Mrs. James W. Wood, 1909. verses 6-7 Brian J. Dumont, 2008","music":"Mrs. James W. Wood, from \"Service in Song\", Standard Pub. Co., 1909. verses 6-7 released into the public domain by the author on 17 Dec 2008","year":1909,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"BLESSED ARE THEY","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nWhen I know that I have done wrong, to Jesus I flee.\nHe has paid for all transgressions, He has paid for me!\n\nVerse 2\nJesus knew that we would fail Him so He came to be\nLife to all the poor and lost ones, life eternally!","arrangement":["Verse 1","Verse 2"],"source":"Open Hymnal Project"},{"id":"oh-joy-to-the-world","title":"Joy to the World","language":"en","writers":"Isaac Watts","music":"pieced together from \"Messiah\" George F. Handel","year":1719,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"ANTIOCH","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nJoy to the world, the Lord is come!\nLet earth receive her King;\nLet ev'ry heart prepare Him room,\nAnd Heav'n and nature sing,\nAnd Heav'n and nature sing,\nAnd Heav'n, and Heav'n, and nature sing.\n\nVerse 2\nJoy to the earth, the Savior reigns!\nLet men their songs employ;\nWhile fields and floods, rocks,\nhills and plains Repeat the sounding joy,\nRepeat the sounding joy,\nRepeat, repeat, the sounding joy.\n\nVerse 3\nNo more let sins and sorrows grow,\nNor thorns infest the ground;\nHe comes to make His blessings flow Far as the curse is found,\nFar as the curse is found,\nFar as, far as, the curse is found.\n\nVerse 4\nHe rules the world with truth and grace,\nAnd makes the nations prove The glories of His righteousness,\nAnd wonders of His love,\nAnd wonders of His love,\nAnd wonders, wonders, of His love.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-joyful-joyful-we-adore-thee","title":"Joyful, Joyful, We Adore Thee","language":"en","writers":"Henry J. van Dyke","music":"Ludwig van Beethoven; Adapted by Edward Hodges","year":1907,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ODE TO JOY","themes":["Hymn"],"lyrics":"Verse 1\nJoyful, joyful, we adore Thee,\nGod of glory, Lord of love;\nHearts unfold like flowers before Thee, opening to the sun above.\nMelt the clouds of sin and sadness; drive the dark of doubt away;\nGiver of immortal gladness, fill us with the light of day!\n\nVerse 2\nAll Thy works with joy surround Thee,\nearth and heaven reflect Thy rays,\nStars and angels sing around Thee, center of unbroken praise.\nField and forest, vale and mountain, flowery meadow, flashing sea,\nSinging bird and flowing fountain call us to rejoice in Thee.\n\nVerse 3\nThou art giving and forgiving, ever blessing, ever blessed,\nWellspring of the joy of living, ocean depth of happy rest!\nThou our Father, Christ our Brother, all who live in love are Thine;\nTeach us how to love each other, lift us to the joy divine.\n\nVerse 4\nMortals, join the happy chorus, which the morning stars began;\nFather love is reigning o'er us, brother love binds man to man.\nEver singing, march we onward, victors in the midst of strife,\nJoyful music leads us Sunward in the triumph song of life.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-lamp-of-our-feet","title":"Lamp of Our Feet","language":"en","writers":"Bernard Barton","music":"John B. Dykes","year":1826,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. AGNES","themes":["Hymn"],"lyrics":"Verse 1\nLamp of our feet! whereby we trace Our path, when wont to stray;\nStream from the fount of heav'nly grace!\nBrook by the trav'ler's way!\n\nVerse 2\nBread of our souls! whereon we feed;\nTrue manna from on high!\nOur guide, and chart wherein we read Of realms beyond the sky.\n\nVerse 3\nPillar of fire-through watches dark!\nOr radiant cloud by day!\nWhen waves would whelm our tossing bark — Our anchor and our stay!\n\nVerse 4\nPole-star on life's tempestuous deep!\nBeacon! when doubts surround;\nCompass! by which our course we keep;\nOur deep sea-lead, to sound!\n\nVerse 5\nRiches in poverty! our aid In every needful hour!\nUnshaken rock! the pilgrim's shade;\nThe soldier's fortress tow'r.\n\nVerse 6\nOur shield and buckler in the fight!\nVict'ry's triumphant palm!\nComfort in grief! in weakness, might!\nIn sickness, Gilead's balm.\n\nVerse 7\nChildhood's preceptor! manhood's trust!\nOld age's firm ally!\nOur hope-when we go down to dust,\nOf immortality.\n\nVerse 8\nPure oracles of truth divine!\nUnlike each fabled dream\nGiven forth from Delphos' mystic shrine\nOr groves of Academe!\n\nVerse 9\nWord of the ever-living God!\nWill of His glorious Son!\nWithout Thee, how could earth be trod?\nOr Heaven itself be won?\n\nVerse 10\nYet to unfold thy hidden worth,\nThy mysteries to reveal,\nThat Spirit which first gave thee forth,\nThy volume must unseal!\n\nVerse 11\nAnd we, if we aright would learn\nThe wisdom it imparts,\nMust to its heavenly teaching turn\nWith simple, child-like hearts!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11"],"source":"Open Hymnal Project"},{"id":"oh-let-all-mortal-flesh-keep-silence","title":"Let All Mortal Flesh Keep Silence","language":"en","writers":"from Liturgy of St. James, 4th Century. Translated by Gerard Moultrie","music":"traditional French","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"PICARDY","themes":["Hymn"],"lyrics":"Verse 1\nLet all mortal flesh keep silence,\nAnd with fear and trembling stand;\nPonder nothing earthly minded,\nFor with blessing in His hand,\nChrist our God to earth descendeth,\nOur full homage to demand.\n\nVerse 2\nKing of kings, yet born of Mary,\nAs of old on earth He stood,\nLord of lords, in human vesture,\nIn the body and the blood;\nHe will give to all the faithful His own self for heav'nly food.\n\nVerse 3\nRank on rank the host of heaven Spreads its vanguard on the way,\nAs the Light of light descendeth From the realms of endless day,\nThat the pow'rs of hell may vanish As the darkness clears away.\n\nVerse 4\nAt His feet the six wingèd seraph,\nCherubim with sleepless eye,\nVeil their faces to the presence,\nAs with ceaseless voice they cry:\nAlleluia, Alleluia Alleluia, Lord Most High!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-let-children-hear-the-mighty-deeds","title":"Let Children Hear The Mighty Deeds","language":"en","writers":"Isaac Watts","music":"James Lea Summers, (1837-1881)","year":1719,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"LEA","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nLet children hear the mighty deeds Which God performed of old;\nWhich in our younger years we saw,\nAnd which our fathers told.\n\nVerse 2\nHe bids us make His glories known,\nHis works of pow'r and grace;\nAnd we'll convey His wonders down Through every rising race.\n\nVerse 3\nOur lips shall tell them to our sons,\nAnd they again to theirs;\nThat generations yet unborn May teach them to their heirs.\n\nVerse 4\nThus shall they learn in God alone Their hope securely stands,\nThat they may ne'er forget His work But practice His commands.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-let-our-gladness-have-no-end","title":"Let Our Gladness Have No End","language":"en","writers":"From the Kancional, by Tobias Zavorka, 1602. Translator unknown","music":"15th Century Bohemian","year":1602,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"NARODIL SE KRISTUS PÁN","themes":["Hymn"],"lyrics":"Verse 1\nLet our gladness have no end,\nHallelujah! For to earth did Christ descend.\nHallelujah! On this day God\n\nChorus\ngave us Christ, His Son, to save us;\nChrist, His Son, to save us.\n\nVerse 2\nSee, the loveliest blooming rose,\nHallelujah! From the branch of Jesse grows. Hallelujah!\n\nVerse 3\nInto flesh is made the Word.\nHallelujah! He, our refuge and our Lord. Hallelujah!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-lift-high-the-cross","title":"Lift High The Cross","language":"en","writers":"George W. Kitchin (1827-1912). Modified by Michael R. Newbolt","music":"Sydney H. Nicholson","year":1827,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CRUCIFIER","themes":["Hymn","Lent"],"lyrics":"Verse 1\nLift high the cross, the love of Christ proclaim,\nTill all the world adore His sacred Name.\nCome, brethren, follow where our Captain trod, our King victorious,\nChrist the Son of God.\n\nVerse 2\nLift high the cross, the love of Christ proclaim,\nTill all the world adore His sacred Name.\nLed on their way by this triumphant sign,\nThe hosts of God in conquering ranks combine.\n\nVerse 3\nLift high the cross, the love of Christ proclaim,\nTill all the world adore His sacred Name.\nEach newborn servant of the Crucified\nBears on the brow the seal of Him Who died.\n\nVerse 4\nLift high the cross, the love of Christ proclaim,\nTill all the world adore His sacred Name.\nThis is the sign which\nSatan's legions fear and angels veil their faces to revere.\n\nVerse 5\nLift high the cross, the love of Christ proclaim,\nTill all the world adore His sacred Name.\nSaved by this Cross whereon their Lord was slain,\nthe sons of Adam their lost home regain.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lift-up-your-heads-ye-mighty-gates","title":"Lift Up Your Heads, Ye Mighty Gates","language":"en","writers":"Georg Weissel, 1642. Translated by Catherine Winkworth","music":"August Lemke","year":1642,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"MILWAUKEE","themes":["Hymn"],"lyrics":"Verse 1\nLift up your heads, ye mighty gates!\nBehold, the King of glory waits;\nThe King of kings is drawing near,\nThe Savior of the world is here;\nLife and salvation doth He bring,\nWherefore rejoice and gladly sing:\nWe praise Thee, Father, now!\nCreator, wise art Thou!\n\nVerse 2\nThe Lord is just, a Helper tried,\nMercy is ever at His side,\nHis kingly crown is holiness,\nHis scepter, pity in distress,\nThe end of all our woe He brings;\nWherefore the earth is glad and sings:\nWe praise Thee, Savior, now!\nMighty in deed art Thou!\n\nVerse 3\nO blest the land, the city blest,\nWhere Christ the Ruler is confessed!\nO happy hearts and happy homes To whom this King in triumph comes!\nThe cloudless Sun of joy He is,\nWho bringeth pure delight and bliss.\nO Comforter divine, What boundless grace is Thine!\n\nVerse 4\nFling wide the portals of your heart;\nMake it a temple, set apart From earthly use for heav'ns employ,\nAdorned with prayer and love and joy;\nSo shall your Sovereign enter in, and new and nobler life begin;\nTo Thee, O God, be praise,\nFor Word, and deed, and grace!\n\nVerse 5\nRedeemer, come! I open wide My heart to Thee; here,\nLord, abide! Let me Thy inner presence feel,\nThy grace and love in me reveal.\nThy Holy Spirit guide us on,\nUntil our glorious goal be won!\nEternal praise and fame We offer to Thy Name.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lo-god-to-heav-n-ascendeth","title":"Lo, God To Heav'n Ascendeth","language":"en","writers":"Gottfried Wilhelm Sacer, 1661. verses 1-5,7 Translated by Frances Elizabeth Cox, 1841. verse 6 translator unknown","music":"Johann Crüger","year":1661,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"VON GOTT WILL ICH NICHT LAZEN","themes":["Hymn"],"lyrics":"Verse 1\nLo, God to Heav'n ascendeth!\nThroughout its regions vast\nWith shouts triumphant blendeth the trumpet's thrilling blast:\nSing praise to Christ the Lord; sing praise with exultation,\nKing of each heathen nation, the God of Hosts adored!\n\nVerse 2\nWith joy is Heav'n resounding Christ's glad return to see;\nBehold the saints surrounding the Lord who set them free.\nBright myriads, thronging, come; the cherub band rejoices,\nAnd loud seraphic voices Welcome Messiah home.\n\nVerse 3\nNo more the way is hidden,\nSince Christ our Head arose:\nNo more to man forbidden The road to Heav'n that goes.\nOur Lord is gone before; yet here He will not leave us,\nAnd soon in Heav'n receive us and open wide the door.\n\nVerse 4\nChrist is our place preparing; to Heav'n we, too, shall rise,\nAnd, joys angelic sharing,\nBe where our treasure lies:\nThere may each heart be found!\nWhere Jesus Christ has entered,\nThere let our Hope be centered;\nOur course still heav'nward bound.\n\nVerse 5\nMay we, His servants, thither In heart and mind ascend,\nAnd let us sing together:\n\"We seek Thee, Christ, our friend,\nThee, God's exalted Son, our Life, and Way to Heaven,\nTo whom all pow'r is given, our Joy and Hope and Crown.\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lo-he-comes-with-clouds-descending","title":"Lo! He Comes With Clouds Descending","language":"en","writers":"John Cennick, 1752. Altered by Charles Wesley, 1758, alt","music":"attr. Thomas Olivers","year":1752,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"HELMSLEY","themes":["Hymn"],"lyrics":"Verse 1\nLo! He comes with clouds descending,\nOnce for ev'ry sinner slain;\nThousand thousand saints attending,\nSwell the triumph of His train:\nHallelujah! Hallelujah! Hallelujah! God appears on earth to reign.\n\nVerse 2\nEv'ry eye shall now behold Him Robed in dreadful majesty;\nThose who set at naught and sold Him,\nPierced and nailed Him to the tree,\nDeeply wailing, deeply wailing, deeply wailing,\nShall the true Messiah see.\n\nVerse 3\nEv'ry island, sea, and mountain,\nHeav'n and earth, shall flee away;\nAll who hate Him must, confounded,\nHear the trump proclaim the day:\nCome to judgment! Come to judgment!\nCome to judgment! Come to judgment! Come away!\n\nVerse 4\nNow redemption, long expected,\nSee in solemn pomp appear;\nAll His saints, by man rejected,\nNow shall meet Him in the air:\nHallelujah! Hallelujah! Hallelujah! See the day of God appear!\n\nVerse 5\nAnswer Thine own bride and Spirit,\nHasten, Lord, the gen'ral doom!\nThe new Heav'n and earth inherit,\nTake Thy pining exiles home:\nAll creation, all creation, all creation,\nTravails! groans! and bids Thee come!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lo-how-a-rose-e-er-blooming","title":"Lo, How A Rose E'er Blooming","language":"en","writers":"verses 1-2, 15th Century German. Translated by Theodore Baker, 1894. verses 3,4 Fridrich Layriz (1808-1859). Translated by Harriet Reynolds Krauth, 1875. verse 5, 15th Century German. Translated by John C. Mattes","music":"German from Köln","year":1894,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ES IST EIN ROS ENTSPRUNGEN (RHYTHMIC)","themes":["Hymn"],"lyrics":"Verse 1\nLo, how a Rose e'er blooming from tender stem hath sprung!\nOf Jesse's lineage coming, as men of old have sung.\nIt came, a flow'ret bright, amid the cold of winter,\nWhen half spent was the night.\n\nVerse 2\nIsaiah 'twas foretold it, the Rose I have in mind;\nWith Mary we behold it, the virgin mother kind.\nTo show God's love aright, she bore to men a Savior,\nWhen half spent was the night.\n\nVerse 3\nThe shepherds heard the story proclaimed by angels bright,\nHow Christ, the Lord of glory was born on earth this night.\nTo Bethlehem they sped and in the manger found Him,\nAs angel heralds said.\n\nVerse 4\nThis Flow'r, whose fragrance tender with sweetness fills the air,\nDispels with glorious splendor the darkness everywhere;\nTrue Man, yet very God, from sin and death He saves us,\nAnd lightens ev'ry load.\n\nVerse 5\nO Savior, Child of Mary, who felt our human woe,\nO Savior, King of glory, who dost our weakness know;\nBring us at length we pray, to the bright courts of Heaven,\nAnd to the endless day!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-look-down-o-lord-from-heaven-behold","title":"Look Down, O Lord, From Heaven Behold","language":"en","writers":"Martin Luther, 1524. Translated by Frances Elizabeth Cox","music":"from Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ACH GOTT VOM HIMMEL","themes":["Hymn"],"lyrics":"Verse 1\nLook down, O Lord, from heav'n behold,\nAnd let thy pity waken!\nHow few the flock within thy fold,\nNeglected and forsaken! Almost thou'lt seek for faith in vain,\nAnd those who should thy truth maintain Thy Word from us have taken.\n\nVerse 2\nWith frauds which they themselves invent\nThy truth they have confounded;\nTheir hearts are not with one consent On thy pure doctrine grounded;\nAnd, whilst they gleam with outward show,\nThey lead thy people to and fro,\nIn error's maze astounded.\n\nVerse 3\nGod surely will uproot all those With vain deceits who store us,\nWith haughty tongue who God oppose,\nAnd say, \"Who'll stand before us?\nBy right or might we will prevail;\nWhat we determine cannot fail,\nFor who can lord it o'er us?\"\n\nVerse 4\nFor this, saith God,\nI will arise, These wolves my flock are rending;\nI've heard my people's bitter sighs To heav'n my throne ascending:\nNow will I up, and set at rest Each weary soul by fraud opprest,\nThe poor with might defending.\n\nVerse 5\nThe silver sev'n times tried is pure From all adulteration;\nSo, through God's word, shall men endure Each trial and temptation:\nIts worth gleams brighter through the cross,\nAnd, purified from human dross,\nIt shines through every nation.\n\nVerse 6\nThy truth thou wilt preserve, O Lord, From this vile generation;\nMake us to lean upon thy word, With calm anticipation.\nThe wicked walk on every side When, 'mid thy flock, the vile abide In pow'r and exaltation.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-lord-dismiss-us-with-thy-blessing","title":"Lord, Dismiss Us With Thy Blessing","language":"en","writers":"John Fawcett, 1773; verse 3 alt. by Godfrey Thring","music":"Henry Smart","year":1773,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"REGENT SQUARE","themes":["Hymn"],"lyrics":"Verse 1\nLord, dismiss us with Thy blessing;\nFill our hearts with joy and peace;\nLet us each Thy love possessing,\nTriumph in redeeming grace.\nO refresh us, O refresh us,\nTrav'ling through this wilderness.\n\nVerse 2\nThanks we give and adoration For Thy Gospel's joyful sound;\nMay the fruits of Thy salvation In our hearts and lives abound.\nEver faithful, ever faithful,\nTo the truth may we be found.\n\nVerse 3\nSo that when Thy love shall call us,\nSavior, from the world away,\nFear of death shall not appall us,\nGlad Thy summons to obey.\nMay we ever, may we ever,\nReign with Thee in endless day.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-lord-enthroned-in-heavenly-splendor","title":"Lord, Enthroned in Heavenly Splendor","language":"en","writers":"George H. Bourne, 1874, alt","music":"William Owen","year":1874,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"BRYN CALFARIA","themes":["Hymn"],"lyrics":"Verse 1\nLord, enthroned in heav'nly splendor,\nFirst begotten from the dead,\nYou alone, our strong Defender,\nNow lift up Your people's head.\nAlleluia! Alleluia! Alleluia! Jesus, true and living Bread!\nJesus, true and living Bread!\n\nVerse 2\nHere our humblest homage pay we,\nHere in loving reference bow;\nHere for faith's discernment pray we,\nLest we fail to know You now.\nAlleluia! Alleluia! Alleluia! Thou art here, we ask not how.\nThou art here, we ask not how.\n\nVerse 3\nThough the lowliest form doth veil Thee As of old in Bethlehem,\nHere as there Thine angels hail Thee,\nBranch and Flow'r of Jesse's stem.\nAlleluia! Alleluia! Alleluia! We in worship join with them.\nWe in worship join with them.\n\nVerse 4\nPaschal Lamb, Your offering finished Once for all when You were slain,\nIn its fullness undiminished Shall forevermore remain.\nAlleluia! Alleluia! Alleluia! Cleansing souls from every stain.\nCleansing souls from every stain.\n\nVerse 5\nGreat High Priest of our profession,\nThrough the veil Thou wentest in,\nBy Thy mighty intercession,\nGrace and peace for us to win.\nAlleluia! Alleluia! Alleluia! Jesus, true and living Bread!\nJesus, true and living Bread!\n\nVerse 6\nLife imparting heavenly Manna,\nSmitten Rock with streaming side,\nHeaven and earth with loud hosanna\nWorship You, the Lamb Who died.\nAlleluia! Alleluia! Alleluia!\nRisen, Ascended, Glorified!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-lord-jesus-think-on-me","title":"Lord Jesus Think On Me","language":"en","writers":"Synesius of Cyrene, circa 430. Translated by Allen W. Chatfield","music":"William Daman's Psalter","year":1876,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"SOUTHWELL","themes":["Hymn"],"lyrics":"Verse 1\nLord Jesus, think on me And purge away my sin;\nFrom earthborn passions set me free And make me pure within.\n\nVerse 2\nLord Jesus, think on me,\nWith many'a care oppressed;\nLet me Thy loving servant be And taste Thy promised rest.\n\nVerse 3\nLord Jesus, think on me Amid the battle's strife;\nIn all my pain and misery Be Thou my Health and Life.\n\nVerse 4\nLord Jesus, think on me Nor let me go astray;\nThrough darkness and perplexity Point Thou the heav'nly way.\n\nVerse 5\nLord Jesus, think on me When floods the tempest high;\nWhen on doth rush the enemy,\nO Savior, be Thou nigh!\n\nVerse 6\nLord Jesus, think on me\nThat, when the flood is past,\nI may th'eternal brightness see\nAnd share Thy joy at last.\n\nVerse 7\nLord Jesus, think on me\nThat I may sing above\nTo Father, Spirit, and to Thee\nThe strains of praise and love.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-lord-keep-us-steadfast-in-thy-word","title":"Lord, Keep Us Steadfast in Thy Word","language":"en","writers":"Martin Luther, 1541. Translated by Catherine Winkworth","music":"from Klug's \"Geistliche Lieder auffs new gebessert\"","year":1541,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ERHALT UNS, HERR, BEI DEINEM WORT","themes":["Hymn"],"lyrics":"Verse 1\nLord, keep us steadfast in Thy Word;\nCurb those who fain by craft and sword Would wrest the kingdom from\nThy Son And set at naught all He hath done.\n\nVerse 2\nLord Jesus Christ, Thy pow'r make known,\nFor Thou art Lord of lords alone;\nDefend Thy Christendom that we May evermore sing praise to Thee.\n\nVerse 3\nO Comforter of priceless worth,\nSend peace and unity on earth.\nSupport us in our final strife And lead us out of death to life.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-lord-of-our-life","title":"Lord Of Our Life","language":"en","writers":"Matthäus Apelles von Löwenstern, 1644. Translated by Philip Pusey","music":"from Poitiers Antiphoner","year":1644,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ISTE CONFESSOR","themes":["Hymn"],"lyrics":"Verse 1\nLord of our life, and God of our salvation,\nStar of our night, and Hope of every nation,\nHear and receive Thy church's supplication, Lord God Almighty.\n\nVerse 2\nSee round Thine Ark the hungry billows curling!\nSee how Thy foes their banners are unfurling!\nLord, while their darts envenomed they are hurling,\nThou canst preserve us.\n\nVerse 3\nLord, Thou canst help when earthly armor faileth;\nLord, Thou canst save when sin itself assaileth;\nLord, o'er Thy Rock nor death nor hell prevaileth;\nGrant us Thy peace, Lord.\n\nVerse 4\nPeace, in our hearts, our evil thoughts assuaging,\nPeace, in Thy Church, where brothers are engaging,\nPeace, when the world its busy war is waging;\nCalm Thy foes raging!\n\nVerse 5\nGrant us Thy help till backward they are driven;\nGrant them Thy Truth, that they may be forgiven;\nGrant peace on earth, and after we have striven,\nPeace in Thy Heaven.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lord-thee-i-love-with-all-my-heart","title":"Lord, Thee I Love with All My Heart","language":"en","writers":"Martin Schalling, circa 1571. Translated by Catherine Winkworth","music":"Strassburg","year":1571,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"HERZLICH LIEB HAB ICH DICH O HERR","themes":["Hymn"],"lyrics":"Verse 1\nLord, Thee I love with all my heart;\nI pray Thee, ne'er from me depart;\nWith tender mercy cheer me.\nEarth has no pleasure I would share,\nYea, Heav'n itself were void and bare If Thou,\nLord, wert not near me.\nAnd should my heart for sorrow break,\nMy trust in Thee can nothing shake.\nThou art the portion I have sought;\nThy precious blood my soul has bought.\nLord Jesus Christ, My God and Lord, my God and Lord,\nForsake me not! I trust Thy Word.\n\nVerse 2\nYea, Lord, 'twas Thy rich bounty gave My body,\nsoul, and all I have In this poor life of labor.\nLord, grant that I in every place May glorify\nThy lavish grace And serve and help my neighbor.\nLet no false doctrine me beguile,\nLet Satan not my soul defile.\nGive strength and patience unto me To bear my cross and follow Thee.\nLord Jesus Christ, My God and Lord, my God and Lord,\nIn death Thy comfort still afford.\n\nVerse 3\nLord, let at last Thine angels come,\nTo Abr'am's bosom bear me home,\nThat I may die unfearing;\nAnd in its narrow chamber keep\nMy body safe in peaceful sleep Until Thy reappearing.\nAnd then from death awaken me,\nThat these mine eyes with joy may see,\nO Son of God,\nThy glorious face, My Savior and my fount of grace.\nLord Jesus Christ, My prayer attend, my prayer attend,\nAnd I will praise Thee without end!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-lord-who-at-cana-s-wedding-feast","title":"Lord, Who at Cana's Wedding Feast","language":"en","writers":"Adelaide Thrupp","music":"Frederick Westlake","year":1853,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. URSULA","themes":["Hymn","Communion"],"lyrics":"Verse 1\nLord, who at Cana's wedding feast Didst as a Guest appear,\nThou dearer far than earthly guest,\nVouchsafe Thy presence here.\nFor holy Thou indeed dost prove The marriage vow to be,\nProclaiming it a type of love Between the Church and Thee.\n\nVerse 2\nThe holiest vow that man can make,\nThe golden thread in life,\nThe bond that none may dare to break,\nThat bindeth man and wife,\nWhich, blest by Thee, whate'er betide,\nNo evil shall destroy,\nThrough careworn days each care divides And doubles every joy.\n\nVerse 3\nOn those who at Thine altar kneel,\nO Lord, Thy blessing pour,\nThat each may wake the other's zeal To love Thee more and more.\nOh, grant them here in peace to live,\nIn purity and love,\nAnd, this world leaving, to receive A crown of life above.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-lord-who-throughout-these-forty-days","title":"Lord Who Throughout These Forty Days","language":"en","writers":"Claudia F. Hernaman","music":"Day's Psalter","year":1873,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ST. FLAVIAN","themes":["Hymn"],"lyrics":"Verse 1\nLord, who throughout these forty days For us didst fast and pray,\nTeach us with Thee to mourn our sins And close by Thee to stay.\n\nVerse 2\nAs Thou with Satan didst contend,\nAnd didst the vict'ry win,\nO give us strength in Thee to fight,\nIn Thee to conquer sin.\n\nVerse 3\nAs Thou didst hunger bear, and thirst,\nSo teach us, gracious Lord,\nTo die to self, and chiefly live By Thy most holy Word.\n\nVerse 4\nAnd through these days of penitence,\nAnd through Thy passiontide,\nYea, evermore in life and death,\nJesus, with us abide.\n\nVerse 5\nAbide with us, that so, this life Of suff'ring over past,\nAn Easter of unending joy We may attain at last.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-lord-of-glory-who-hast-bought-us","title":"Lord of Glory, Who Hast Bought Us","language":"en","writers":"Eliza S. Alderson","music":"Rowland H. Prichard","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"HYFRYDOL","themes":["Hymn"],"lyrics":"Verse 1\nLord of Glory, who hast bought us with Thy lifeblood as the price,\nNever grudging for the lost ones that tremendous sacrifice;\nAnd with that hast freely given blessings countless as the sand,\nTo th'unthankful and the evil with Thine own unsparing hand.\n\nVerse 2\nGrant us hearts, dear Lord,\nto yield Thee gladly, freely, of Thine own.\nWith the sunshine of Thy goodness melt our thankless hearts of stone.\nTill our cold and selfish natures, warmed by Thee,\nat length believe\nThat more happy and more blessed 'tis to give than to receive.\n\nVerse 3\nWondrous honor hast Thou given to our humblest charity.\nIn Thine own mysterious sentence,\n\"Ye have done it unto Me.\" Can it be,\nO gracious Master, Thou dost deign for alms to sue,\nSaying by Thy poor and needy,\n\"Give as I have given you\"\n\nVerse 4\nLord of Glory, who hast bought us with Thy lifeblood as the price,\nNever grudging for the lost ones that tremendous sacrifice;\nGive us faith, to trust Thee boldly; hope, to stay our souls on Thee;\nBut O, best of all Thy graces, give us Thine own charity.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-lord-of-life-all-praise-excelling","title":"Lord of Life, All Praise Excelling","language":"en","writers":"Clement C. Moore","music":"Rowland H. Prichard","year":1808,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"HYFRYDOL","themes":["Hymn"],"lyrics":"Verse 1\nLord of life, all praise excelling,\nThou, in glory unconfined,\nDeignst to make Thy humble dwelling With the poor of humble mind.\nAs Thy love, through all creation,\nBeams like Thy diffusive light;\nSo the high and humble station Both are equal in Thy sight.\n\nVerse 2\nThus Thy care, for all providing,\nWarmed Thy faithful prophet's tongue;\nWho, the lot of all deciding,\nTo Thy chosen Israel sung.\nWhen Thy harvest yields Thee pleasure,\nThou the golden sheaf shalt bind;\nTo the poor belongs the treasure Of the scattered ears behind.\n\nVerse 3\nStill we read Thy Word declaring Mercy,\nLord, Thine own decree;\nMercy ev'ry sorrow sharing,\nWarms the heart resembling Thee.\nStill the orphan and the stranger,\nStill the widow owns Thy care;\nScreened by Thee in ev'ry danger,\nHeard by Thee in ev'ry prayer.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-may-god-bestow-on-us-his-grace","title":"May God Bestow on Us His Grace","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"adapted from older German hymn by Martin Luther. Found in Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"ES WOLLT UNS GOTT GENÆDIG","themes":["Hymn"],"lyrics":"Verse 1\nMay God bestow on us His grace,\nWith blessings rich provide us,\nAnd may the brightness of His face To life eternal guide us\nThat we His saving health may know,\nHis gracious will and pleasure,\nAnd also to the heathen show\nChrist's riches without measure And unto God convert them.\n\nVerse 2\nThine over all shall be the praise And thanks of every nation,\nAnd all the world with joy shall raise The voice of exultation;\nFor Thou shalt judge the earth,\nO Lord, Nor suffer sin to flourish;\nThy people's pasture is Thy Word Their souls to feed and nourish,\nIn righteous paths to keep them.\n\nVerse 3\nOh, let the people praise Thy worth,\nIn all good works increasing;\nThe land shall plenteous fruit bring forth,\nThy Word is rich in blessing.\nMay God the Father,\nGod the Son, And God the Spirit bless us!\nLet all the world praise Him alone,\nLet solemn awe possess us.\nNow let our hearts say, Amen.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-moment-by-moment","title":"Moment By Moment","language":"en","writers":"Daniel W. Whittle","music":"May Whittle Moody","year":1893,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"WHITTLE","themes":["Hymn"],"lyrics":"Verse 1\nDying with Jesus, by death reckoned mine;\nLiving with Jesus, a new life divine;\nLooking to Jesus till glory doth shine,\nMoment by moment, O Lord,\nI am Thine. Moment by moment I'm kept in His love;\n\nChorus\nMoment by moment I've life from above;\nLooking to Jesus till glory doth shine;\nMoment by moment, O Lord, I am Thine.\n\nVerse 2\nNever a trial that He is not there,\nNever a burden that He doth not bear,\nNever a sorrow that He doth not share,\nMoment by moment, I'm under His care.\n\nVerse 3\nNever a heartache, and never a groan,\nNever a teardrop and never a moan;\nNever a danger but there on the throne,\nMoment by moment He thinks of His own.\n\nVerse 4\nNever a weakness that He doth not feel,\nNever a sickness that He cannot heal;\nMoment by moment, in woe or in weal,\nJesus my Savior, abides with me still.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-more-love-to-thee","title":"More Love to Thee","language":"en","writers":"Elizabeth Payson Prentis","music":"William Howard Doane","year":1856,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"MORE LOVE TO THEE","themes":["Hymn"],"lyrics":"Verse 1\nMore love to Thee,\nO Christ; More love to Thee;\nHear Thou the pray'r I make On bended knee;\nThis is my earnest plea,\nMore love, O Christ, to Thee,\nMore love to Thee;\nMore love to Thee.\n\nVerse 2\nOnce earthly joy I craved,\nSought peace and rest;\nNow thee alone I seek,\nGive what is best;\nThis all my pray'r shall be,\nMore love, O Christ, to Thee,\nMore love to Thee;\nMore love to Thee.\n\nVerse 3\nThen shall my latest breath,\nWhisper Thy praise, This be the parting cry My heart shall raise;\nThis still its pray'r shall be,\nMore love, O Christ, to Thee,\nMore love to Thee;\nMore love to Thee.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-my-faith-looks-up-to-thee","title":"My Faith Looks Up To Thee","language":"en","writers":"Ray Palmer","music":"Lowell Mason","year":1830,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"OLIVET","themes":["Hymn"],"lyrics":"Verse 1\nMy faith looks up to Thee,\nThou Lamb of Calvary,\nSavior divine! Now hear me while I pray, take all my guilt away,\nO let me from this day be wholly Thine!\n\nVerse 2\nMay Thy rich grace impart Strength to my fainting heart,\nmy zeal inspire!\nAs Thou hast died for me,\nO may my love to Thee,\nPure warm, and changeless be, a living fire!\n\nVerse 3\nWhile life's dark maze I tread,\nAnd griefs around me spread, be Thou my Guide;\nBid darkness turn to day, wipe sorrow's tears away,\nNor let me ever stray from Thee aside.\n\nVerse 4\nWhen ends life's transient dream,\nWhen death's cold sullen stream over me roll;\nBlest Savior, then in love, fear and distrust remove;\nO bear me safe above, a ransomed soul!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-my-hope-is-built","title":"My Hope Is Built","language":"en","writers":"Edward Mote","music":"John Bacchus Dykes","year":1834,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"MELITA","themes":["Hymn"],"lyrics":"Verse 1\nMy hope is built on nothing less Than Jesus' blood and righteousness.\nI dare not trust the sweetest frame,\nBut wholly trust in Jesus' Name.\nOn Christ the solid\n\nChorus\nRock I stand, All other ground is sinking sand.\n\nVerse 2\nWhen darkness veils His lovely face,\nI rest on His unchanging grace.\nIn every high and stormy gale,\nMy anchor holds within the veil.\n\nVerse 3\nHis oath, His covenant,\nHis blood, Support me in the whelming flood.\nWhen all around my soul gives way,\nHe then is all my hope and stay.\n\nVerse 4\nWhen He shall come with trumpet sound,\nOh may I then in Him be found.\nDressed in His righteousness alone,\nFaultless to stand before the throne.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-my-jesus-as-thou-wilt","title":"My Jesus, As Thou Wilt","language":"en","writers":"Benjamin Schmolck, circa 1704. Translated by Jane L. Borthwick","music":"Carl M. von Weber","year":1704,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"JEWETT","themes":["Hymn"],"lyrics":"Verse 1\nMy Jesus, as Thou wilt!\nOh, may Thy will be mine!\nInto Thy hand of love I would my all resign;\nThrough sorrow, or through joy, conduct me as Thine own,\nAnd help me still to say, my Lord,\nThy will be done!\n\nVerse 2\nMy Jesus, as Thou wilt!\nIf needy here and poor,\nGive me Thy people's bread, their portion rich and sure.\nThe manna of Thy Word Let my soul feed upon;\nAnd if all else should fail, my Lord, thy will be done!\n\nVerse 3\nMy Jesus, as Thou wilt!\nThough seen through many'a tear,\nLet not my star of hope grow dim or disappear;\nSince Thou on earth hast wept, and sorrowed oft alone,\nIf I must weep with Thee, my Lord,\nThy will be done!\n\nVerse 4\nMy Jesus, as Thou wilt!\nAll shall be well for me;\nEach changing future scene I gladly trust with Thee:\nStraight to my home above I travel calmly on,\nAnd sing, in life or death, my Lord,\nThy will be done!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-my-savior-s-love","title":"My Savior's Love","language":"en","writers":"Charles H. Gabriel","music":"s LoveI Stand Amazed in the Presence' Charles H. Gabriel","year":1905,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"MY SAVIOR","themes":["Hymn"],"lyrics":"Verse 1\nI stand amazed in the presence Of Jesus the Nazarene,\nAnd wonder how He could love me,\nA sinner, condemn'd, unclean.\n\nChorus\nHow marvelous! how wonderful!\nAnd my song shall ever be:\nHow marvelous! how wonderful!\nIs my Savior's love for me!\n\nVerse 2\nFor me it was in the garden He pray'd \"Not my will,\nbut Thine;\" He had no tears for His own griefs,\nBut sweat drops of blood for mine.\n\nVerse 3\nIn pity angels beheld Him,\nAnd came from the world of light To comfort Him in the sorrows,\nHe bore for my soul that night.\n\nVerse 4\nWhen with the ransomed in glory His face I at last shall see,\n'Twill be my joy thro' the ages,\nTo sing of His love for me.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-my-soul-now-praise-thy-maker","title":"My Soul, Now Praise Thy Maker","language":"en","writers":"Johann Graumann, 1525. Translated by Catherine Winkworth","music":"from Johannes Kugelmann's Concentus Novi","year":1525,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"NUN LOB, MEIN SEEL","themes":["Hymn"],"lyrics":"Verse 1\nMy soul, now praise thy maker!\nLet all within me bless His name Who maketh thee partaker\nOf mercies more than thou dar'st claim.\nForget Him not whose meekness Still bears with all thy sin,\nWho healeth all thy weakness,\nRenews thy life within.\nWhose grace and care are endless And saved thee through the past;\nWho leaves no suff'rer friendless,\nBut rights the wronged at last.\n\nVerse 2\nHe shows to man His treasure Of judgment, truth, and righteousness,\nHis love beyond all measure,\nHis yearning pity o'er distress,\nNor treats us as we merit,\nBut lays His anger by.\nThe humble, contrite spirit Finds His compassion nigh;\nAnd high as Heav'n above us,\nAs break from close of day,\nSo far, since He doth love us,\nHe puts our sins away.\n\nVerse 3\nFor as a tender father Hath pity on his children here,\nHe in His arms will gather All who are His in childlike fear.\nHe knows how frail our powers Who but from dust are made;\nWe flourish like the flowers,\nAnd even so we fade;\nThe wind but o'er them passes,\nAnd all their bloom is o'er — We wither like the grasses,\nOur place knows us no more.\n\nVerse 4\nGod's grace alone endureth,\nAnd children's children yet shall prove How\nHe with strength assureth The hearts of all that seek His love.\nIn Heav'n is fixed His dwelling,\nHis rule is over all;\nAngels, in might excelling,\nBright hosts, before Him fall.\nPraise Him who ever reigneth,\nAll ye who hear His Word,\nNor our poor hymns disdaineth — My soul,\nO praise the Lord!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-nearer-my-god-to-thee","title":"Nearer, My God, To Thee","language":"en","writers":"st. 1-2 by Sarah F. Adams, 1841. st. 3-5 by Hervey D. Ganse (1822-1891). st. 6 by Edward H. Bickersteth, Jr. (1825-1906)","music":"Lowell Mason","year":1841,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"BETHANY (MASON)","themes":["Hymn"],"lyrics":"Verse 1\nNearer, my God, to Thee, nearer to Thee!\nE'en though it be a cross that raiseth me,\nStill all my song shall be, nearer, my God, to Thee.\nNearer, my God, to Thee, Nearer to Thee!\n\nVerse 2\nThough like the wanderer, the sun gone down,\nDarkness be over me, my rest a stone.\nYet in my dreams I'd be nearer, my God to Thee.\nThen evermore to be Nearer to Thee!\n\nVerse 3\nNearer, my Lord, to thee,\nNearer to thee! Who to the cross didst come,\nDying for me! Strengthen my willing feet,\nHold me in service sweet\n\nVerse 4\nNearer, O Comforter, Nearer to thee!\nWho with my loving Lord Dwellest with me!\nGrant me thy fellowship!\nHelp me each day to keep\n\nVerse 5\nBut to be nearer still,\nBring me, O God,\nNot by the visioned steeps Angels have trod.\nHere where thy cross I see,\nJesus, I wait for thee,\n\nVerse 6\nThere in my Father's home, safe and at rest,\nThere in my Savior's love, perfectly blest; Age\nafter age to be, nearer my God to Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-no-not-one","title":"No, Not One!","language":"en","writers":"Johnson Oatman, Jr","music":"George Crawford Hugg","year":1894,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"NO, NOT ONE","themes":["Hymn"],"lyrics":"Verse 1\nThere's not a friend like the lowly Jesus,\nNo, not one! no, not one!\nNone else could heal all our soul's diseases,\nNo, not one! no, not one!\n\nChorus\nJesus knows all about our struggles,\nHe will guide till the day is done;\nThere's not a friend like the lowly Jesus,\nNo, not one! no, not one!\n\nVerse 2\nNo friend like Him is so high and holy,\nNo, not one! no, not one!\nAnd yet no friend is so meek and lowly,\nNo, not one! no, not one!\n\nVerse 3\nThere's not an hour that He is not near us,\nNo, not one! no, not one!\nNo night so dark but His love can cheer us,\nNo, not one! no, not one!\n\nVerse 4\nDid ever saint find this friend forsake him?\nNo, not one! no, not one!\nOr sinner find that He would not take him?\nNo, not one! no, not one!\n\nVerse 5\nWas e'er a gift like the Savior given?\nNo, not one! no, not one!\nWill He refuse us a home in heaven?\nNo, not one! no, not one!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-none-other-lamb","title":"None Other Lamb","language":"en","writers":"Christina Rossetti","music":"William Jeater","year":1892,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"ROSSETTI","themes":["Hymn"],"lyrics":"Verse 1\nNone other Lamb, none other name,\nNone other hope in Heav'n or earth or sea,\nNone other hiding place from guilt and shame, None beside Thee!\n\nVerse 2\nMy faith burns low, my hope burns low;\nOnly my heart's desire cries out in me\nBy the deep thunder of its want and woe,\nCries out to Thee.\n\nVerse 3\nLord, Thou art life, though I be dead;\nLove's fire Thou art, however cold I be:\nNor Heav'n have I, nor place to lay my head,\nNor home, but Thee.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-not-worthy-lord-to-gather-up-the-crumbs","title":"Not Worthy, Lord, to Gather Up the Crumbs","language":"en","writers":"Edward Henry Bickersteth","music":"William H. Monk","year":1872,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"EVENTIDE","themes":["Hymn"],"lyrics":"Verse 1\nNot worthy, Lord,\nto gather up the crumbs With trembling hand that from Thy table fall,\nA weary, heavy laden sinner comes\nTo plead Thy promise and obey Thy call.\n\nVerse 2\nI am not worthy to be thought Thy child,\nNor sit the last and lowest at Thy board;\nToo long a wanderer and too oft beguiled;\nI only ask one reconciling word.\n\nVerse 3\nOne word from Thee, my Lord, one smile, one look,\nAnd I could face the cold, rough world again;\nAnd with that treasure in my heart could brook\nThe wrath of devils and the scorn of men.\n\nVerse 4\nAnd is not mercy Thy prerogative — Free mercy,\nboundless, fathomless, divine?\nMe, Lord, the chief of sinners, me forgive,\nAnd Thine the greater glory, only Thine.\n\nVerse 5\nI hear Thy voice;\nThou bid'st me come and rest;\nI come, I kneel,\nI clasp Thy piercèd feet;\nThou bid'st me take my place,\na welcome guest Among Thy saints, and of Thy banquet eat.\n\nVerse 6\nMy praise can only breathe itself in prayer,\nMy prayer can only lose itself in Thee;\nDwell Thou forever in my heart, and there,\nLord, let me sup with Thee; sup Thou with me.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-now-praise-we-christ-the-holy-one","title":"Now Praise We Christ, the Holy One","language":"en","writers":"Coelius Sedulius, circa 450. Translated to German by Martin Luther, 1524. Translated from German to English by Richard Massie, 1854, alt","music":"ancient Latin found in Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CHRISTUM WIR SOLLEN LOBEN SCHON","themes":["Hymn"],"lyrics":"Verse 1\nNow praise we Christ, the Holy One,\nThe spotless virgin Mary's Son,\nFar as the blesséd sun doth shine E'en to the world's remote confine\n\nVerse 2\nHe, who Himself all things did make,\nA servant's form vouchsafed to take,\nThat He as man mankind might win,\nAnd save His creatures from their sin.\n\nVerse 3\nThe grace of God, th'Almighty Lord,\nOn the chaste mother was outpoured a virgin pure and undefiled\nIn wondrous wise conceived a child.\n\nVerse 4\nThe holy maid became th'abode And temple of the living God;\nAnd she, who knew not man,\nwas blest With God's own Word made manifest.\n\nVerse 5\nThe noble mother bare a Son,\nFor so did Gabriel's promise run,\nWhom John confessed and leapt with joy,\nEre yet the mother knew her boy.\n\nVerse 6\nIn a rude manger, stretched on hay, In poverty content He lay;\nWith milk was fed the Lord of all, Who feeds the ravens when they call.\n\nVerse 7\nTh' angelic choir rejoice, and raise Their voice to God in songs of praise;\nTo humble shepherds is proclaimed The Shepherd who the world hath framed.\n\nVerse 8\nHonor to Thee, O Christ, be paid, Pure offspring of a holy maid,\nWith Father and with Holy Ghost, Till time in time's abyss be lost.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-now-rest-beneath-night-s-shadow","title":"Now Rest Beneath Night's Shadow","language":"en","writers":"Paul Gerhardt, 1648. Translation composite before","music":"Heinrich Isaac","year":1648,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"INNSBRUCK","themes":["Hymn","Evening"],"lyrics":"Verse 1\nNow rest beneath night's shadow The woodland, field, and meadow,\nThe world in slumber lies;\nBut Thou, my heart, awake thee,\nTo prayer and song betake thee;\nLet praise to thy Creator rise.\n\nVerse 2\nThe radiant sun hath vanished,\nHis golden rays are banished By night, the foe of day;\nBut Christ, the Sun of gladness,\nDispelling all my sadness,\nWithin my heart holds constant sway.\n\nVerse 3\nThe rule of day is over And shining jewels cover\nThe heaven's boundless blue.\nThus I shall shine in heaven,\nWhere crowns of gold are given To all who faithful prove and true.\n\nVerse 4\nTo rest my body hasteth,\nAside its garments casteth,\nTypes of mortality;\nThese I put off and ponder How\nChrist will give me yonder A robe of glorious majesty.\n\nVerse 5\nLord Jesus, who dost love me,\nOh, spread Thy wings above me And shield me from alarm!\nThough evil would assail me,\nThy mercy will not fail me:\nI rest in Thy protecting arm.\n\nVerse 6\nMy loved ones, rest securely, For God this night will surely\nFrom peril guard your heads. Sweet slumbers may He send you\nAnd bid His hosts attend you And through the night watch o'er your beds.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-now-the-light-has-gone-away","title":"Now the Light Has Gone Away","language":"en","writers":"Frances Ridley Havergal","music":"from Liederbuch für Kleinkinder-Schulen","year":1869,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"MÜDE BIN ICH, GEH ZUR RUH","themes":["Hymn"],"lyrics":"Verse 1\nNow the light has gone away;\nFather, listen while I pray,\nAsking Thee to watch and keep And to send me quiet sleep.\n\nVerse 2\nJesus, Savior, wash away All that has been wrong today;\nHelp me every day to be Good and gentle, more like Thee.\n\nVerse 3\nLet my near and dear ones be Always near and dear to Thee.\nOh, bring me and all I love To Thy happy home above.\n\nVerse 4\nNow my evening praise I give;\nThou didst die that I might live.\nAll my blessings come from Thee;\nOh, how good Thou art to me!\n\nVerse 5\nThou, my best and kindest Friend,\nThou wilt love me to the end.\nLet me love Thee more and more,\nAlways better than before.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-chief-of-cities-bethlehem","title":"O Chief of Cities Bethlehem","language":"en","writers":"Aurelius Clemens Prudentius (348-413). v. 1,2,4 Translated by N. B. Smithers, 1879, v. 3 Translated by C. W. Douglas, v.5 Translated by John, Marquess of Bute","music":"Michael Praetorius","year":1879,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"PUER NOBIS NASCITUR","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nO chief of cities,\nBethlehem, Of David's crown the fairest gem,\nBut more to us than David's name,\nIn you, as man, the Savior came.\n\nVerse 2\nBeyond the sun in splendor bright,\nAbove you stands a wondrous light\nProclaiming from the conscious skies That here,\nin flesh, the Godhead lies.\n\nVerse 3\nThe wise men, seeing Him so fair,\nBow low before Him,\nand with prayer Their treasured eastern gifts unfold Of incense,\nmyrrh, and royal gold.\n\nVerse 4\nThe golden tribute owns Him King,\nBut frankincense to God they bring,\nAnd last, prophetic sign, with myrrh,\nThey shadow forth His sepulcher.\n\nVerse 5\nO Jesus, whom the Gentiles see,\nWith Father, Spirit, One in Three:\nTo You, O God, be glory giv'n By saints on earth and saints in Heav'n.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-come-all-ye-faithful","title":"O Come, All Ye Faithful","language":"en","writers":"John F. Wade, circa 1743. v.1-3, 6 Translated by Frederick Oakeley, 1841; v. 4, 5 Translated by William T. Brooke (1848-1917)","music":"John F. Wade","year":1743,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ADESTE FIDELES","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nO come, all ye faithful, joyful and triumphant,\nO come ye, O come ye, to Bethlehem.\nCome and behold Him, born the King of angels;\nO come, let us a\n\nChorus\ndore Him, O come, let us adore Him,\nO come, let us adore Him, Christ the Lord.\n\nVerse 2\nTrue God of true God,\nLight from Light Eternal,\nLo, He shuns not the Virgin's womb;\nSon of the Father, begotten, not created;\n\nVerse 3\nSing, choirs of angels, sing in exultation;\nO sing, all ye citizens of heav'n above!\nGlory to God, glory in the highest;\n\nVerse 4\nSee how the shepherds, summoned to His cradle,\nLeaving their flocks, draw nigh to gaze;\nWe too will thither bend our joyful footsteps;\n\nVerse 5\nLo! star led chieftains,\nMagi, Christ adoring, Offer Him incense, gold, and myrrh;\nWe to the Christ Child bring our hearts' oblations.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-o-come-o-come-emmanuel","title":"O Come O Come Emmanuel","language":"en","writers":"various, combined by unknown author approx 12th Century, Translated by John Mason Neale","music":"15th Century French processional","year":1851,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"VENI EMMANUEL","themes":["Hymn"],"lyrics":"Verse 1\nO come, O come,\nEmmanuel, And ransom captive Israel,\nThat mourns in lonely exile here Until the Son of God appear.\n\nChorus\nRejoice! Rejoice! Emmanuel shall come to thee, O Israel.\n\nVerse 2\nO come, Thou Wisdom from on high,\nWho orderest all things mightily;\nTo us the path of knowledge show,\nAnd teach us in her ways to go.\n\nVerse 3\nO come, Thou Rod of Jesse, free Thine own from Satan's tyranny;\nFrom depths of hell Thy people save,\nAnd give them vict'ry ov'r the grave.\n\nVerse 4\nO come, Thou Dayspring,\ncome and cheer Our spirits by Thine advent here;\nDisperse the gloomy clouds of night,\nAnd death's dark shadows put to flight.\n\nVerse 5\nO come, Thou Key of David, come,\nAnd open wide our heav'nly home;\nMake safe the way that leads on high,\nAnd close the path to misery.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-o-day-of-rest-and-gladness","title":"O Day of Rest And Gladness","language":"en","writers":"Christopher Wordsworth","music":"traditional German found in \"Memminger Tabulaturbuche\", 17th Century","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"WOODBIRD","themes":["Hymn"],"lyrics":"Verse 1\nO day of rest and gladness, o day of joy and light,\nO balm of care and sadness, most beautiful, most bright:\nOn thee, the high and lowly, through ages joined in tune,\nSing holy, holy, holy, to the great God Triune.\n\nVerse 2\nOn thee, at the creation, the light first had its birth;\nOn thee, for our salvation,\nChrist rose from depths of earth;\nOn thee, our Lord, victorious, the Spirit sent from heaven,\nAnd thus on thee, most glorious, a triple light was given.\n\nVerse 3\nThou art a port, protected from storms that round us rise;\nA garden, intersected with streams of paradise;\nThou art a cooling fountain in life's dry, dreary sand;\nFrom thee, like Pisgah's mountain, we view our promised land.\n\nVerse 4\nThou art a holy ladder, where angels go and come;\nEach Sunday finds us gladder, nearer to heaven, our home;\nA day of sweet refection, thou art a day of love,\nA day of resurrection from earth to things above.\n\nVerse 5\nToday on weary nations the heavenly manna falls;\nTo holy convocations the silver trumpet calls,\nWhere Gospel light is glowing with pure and radiant beams,\nAnd living water flowing, with soul refreshing streams.\n\nVerse 6\nNew graces ever gaining from this our day of rest,\nWe reach the rest remaining to spirits of the blessed.\nTo Holy Ghost be praises, to Father, and to Son;\nThe church her voice upraises to Thee, blessed Three in One.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-o-father-all-creating","title":"O Father, All Creating","language":"en","writers":"John Ellerton","music":"Samuel Sebastian Wesley","year":1876,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"AURELIA","themes":["Hymn"],"lyrics":"Verse 1\nO Father, all creating,\nWhose wisdom, love,\nand pow'r First bound two lives together In Eden's primal hour,\nToday to these Thy children Thy earliest gifts renew:\nA home by Thee made happy,\nA love by Thee kept true.\n\nVerse 2\nO Savior, Guest most bounteous Of old in Galilee,\nVouchsafe today Thy presence With these who call on Thee;\nTheir store of earthly gladness Transform to heav'nly wine,\nAnd teach them, in the tasting To know the gift is Thine.\n\nVerse 3\nO Spirit of the Father,\nBreathe on them from above,\nSo mighty in Thy pureness,\nSo tender in Thy love;\nThat, guarded by Thy presence,\nFrom sin and strife kept free,\nTheir lives may own Thy guidance,\nTheir hearts be rul'd by Thee.\n\nVerse 4\nExcept Thou build it,\nFather, The house is built in vain;\nExcept Thou, Savior, bless it,\nThe joy will turn to pain;\nBut naught can break the union Of hearts in Thee made one,\nAnd love Thy Spirit hallow'd Is endless love begun.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-o-for-a-thousand-tongues","title":"O For A Thousand Tongues","language":"en","writers":"Charles Wesley","music":"Carl G. Gläser","year":1740,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"AZMON","themes":["Hymn"],"lyrics":"Verse 1\nO for a thousand tongues to sing My great Redeemer's praise,\nThe glories of my God and King,\nThe triumphs of His grace!\n\nVerse 2\nMy gracious Master and my God,\nAssist me to proclaim,\nTo spread through all the earth abroad The honors of Thy name.\n\nVerse 3\nJesus! the name that charms our fears,\nThat bids our sorrows cease;\n'Tis music in the sinner's ears,\n'Tis life, and health, and peace.\n\nVerse 4\nHe breaks the pow'r of canceled sin,\nHe sets the prisoner free;\nHis blood can make the foulest clean,\nHis blood availed for me.\n\nVerse 5\nHe speaks, and, listening to His voice,\nNew life the dead receive,\nThe mournful, broken hearts rejoice,\nThe humble poor believe.\n\nVerse 6\nHear Him, ye deaf; His praise, ye dumb,\nYour loosened tongues employ;\nYe blind, behold your Savior come,\nAnd leap, ye lame, for joy.\n\nVerse 7\nIn Christ your Head, you then shall know,\nShall feel your sins forgiven;\nAnticipate your heaven below,\nAnd own that love is heaven.\n\nVerse 8\nGlory to God, and praise and love\nBe ever, ever given,\nBy saints below and saints above,\nThe church in earth and heaven.\n\nVerse 9\nOn this glad day the glorious Sun\nOf Righteousness arose;\nOn my benighted soul He shone\nAnd filled it with repose.\n\nVerse 10\nSudden expired the legal strife,\n'Twas then I ceased to grieve;\nMy second, real, living life\nI then began to live.\n\nVerse 11\nThen with my heart I first believed,\nBelieved with faith divine,\nPower with the Holy Ghost received\nTo call the Savior mine.\n\nVerse 12\nI felt my Lord's atoning blood\nClose to my soul applied;\nMe, me He loved, the Son of God,\nFor me, for me He died!\n\nVerse 13\nI found and owned His promise true,\nAscertained of my part,\nMy pardon passed in heaven I knew\nWhen written on my heart.\n\nVerse 14\nLook unto Him, ye nations, own\nYour God, ye fallen race;\nLook, and be saved through faith alone,\nBe justified by grace.\n\nVerse 15\nSee all your sins on Jesus laid:\nThe Lamb of God was slain,\nHis soul was once an offering made\nFor every soul of man.\n\nVerse 16\nAwake from guilty nature's sleep,\nAnd Christ shall give you light,\nCast all your sins into the deep,\nAnd wash the Æthiop white.\n\nVerse 17\nHarlots and publicans and thieves\nIn holy triumph join!\nSaved is the sinner that believes\nFrom crimes as great as mine.\n\nVerse 18\nMurderers and all ye hellish crew,\nYe sons of lust and pride,\nBelieve the Savior died for you;\nFor me the Savior died.\n\nVerse 19\nWith me, your chief, ye then shall know,\nShall feel your sins forgiven;\nAnticipate your heaven below,\nAnd own that love is heaven.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11","Verse 12","Verse 13","Verse 14","Verse 15","Verse 16","Verse 17","Verse 18","Verse 19"],"source":"Open Hymnal Project"},{"id":"oh-o-holy-blessed-trinity","title":"O Holy, Blessed Trinity","language":"en","writers":"Martin Behm, 1608. Translated by C. H. L. Schuette","music":"Nikolaus Hermann","year":1608,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"O HEILIGE DREIFALTIGKEIT","themes":["Hymn","Trinity"],"lyrics":"Verse 1\nO Holy, Blessed Trinity,\nDivine, Essential Unity, God Father,\nSon, and Holy Ghost,\nBe Thou this day my Guide and Host.\n\nVerse 2\nMy soul and body keep from harm,\nO'er all I have extend Thine arm,\nThat Satan may not cause distress Nor bring me shame or wretchedness.\n\nVerse 3\nThe Father's might shield me this day,\nThe Son's pure wisdom cheer my way,\nThe Holy Spirit's light divine Illume my heart's benighted shrine.\n\nVerse 4\nMy Maker, strengthen Thou my heart,\nO my Redeemer, help impart,\nBlest Comforter, keep at my side That faith and love in me abide.\n\nVerse 5\nLord, bless and keep Thou me as Thine;\nLord, make Thy face upon me shine;\nLord, lift Thy countenance on me\nAnd give me peace-sweet peace, from Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-holy-spirit-enter-in","title":"O Holy Spirit, Enter In","language":"en","writers":"Michael Schirmer, 1650 except verse 2 by unknown author circa 1660. Verses 1, 4, 6-8 translated by by Catherine Winkworth, 1863. Remaining verses unknown translator before","music":"Phillipp Nicolai","year":1650,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"WIE SCHÖN LEUCHTET","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nO Holy Spirit, enter in,\nAnd in our hearts Thy work begin Thy Temple deign to make us;\nSun of the soul,\nThou Light divine, Around and in us brightly shine,\nTo joy and gladness wake us.\nThat we to Thee Truly living,\nTo Thee giving Prayer unceasing May in love be still increasing.\n\nVerse 2\nGive to Thy Word impressive pow'r That in our hearts,\nfrom this good hour,\nAs fire it may be glowing;\nThat we confess the Father,\nSon, And Thee, the Spirit,\nThree in One, Thy glory ever showing.\nStay Thou, guide now Our souls ever that they never May forsake Thee.\nBut by faith their refuge make Thee.\n\nVerse 3\nThou fountain whence all wisdom flows\nWhich God on pious hearts bestows,\nGrant us Thy consolation.\nThat in our pure faith's unity We faithful witnesses may be\nOf grace that brings salvation.\nHear us, cheer us,\nBy Thy teaching; let our preaching,\nAnd our labor Praise Thee,\nLord, and serve our neighbor.\n\nVerse 4\nLeft to ourselves, we shall but stray;\nO lead us on the narrow way,\nWith wisest counsel guide us;\nAnd give us steadfastness, that we May ever faithful prove to Thee,\nWhatever woes betide us;\nLord now Heal Thou All hearts broken,\nAnd betoken Thou art near us,\nWhom we trust to light and cheer us.\n\nVerse 5\nThy heav'nly strength sustain our heart\nThat we may act the valiant part With Thee as our Reliance;\nBe Thou our Refuge and our Shield That we may never quit the field,\nBut stand in bold defiance.\nDescend, defend From all errors And earth's terrors\nThy salvation Be our constant consolation.\n\nVerse 6\nO mighty Rock, O Source of life,\nLet Thy dear Word 'mid doubt and strife\nBe so within us burning,\nThat we be faithful unto death,\nIn Thy pure love and holy faith,\nFrom Thee true wisdom learning!\nThy grace And peace\nOn us shower; By Thy power\nChrist confessing,\nLet us win our Savior's blessing.\n\nVerse 7\nO gentle Dew, from Heav'n now fall\nWith pow'r upon the hearts of all,\nThy tender love instilling,\nThat heart to heart more closely bound,\nFruitful in kindly deeds be found,\nThe law of love fulfilling;\nThe Lord, Discord\nShall not grieve Thee; We recieve Thee;\nWhere Thou livest.\nPeace, and love, and joy Thou givest.\n\nVerse 8\nGrant that our days, while life shall last,\nIn purest holiness be passed,\nBe Thou our Strength forever;\nGrant that our hearts henceforth be free\nFrom sinful lust and vanity\nWhich us from Thee must sever.\nKeep Thou pure Now\nFrom offenses Heart and senses.\nBlessed Spirit!\nLet us heavenly life inherit.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-o-little-town-of-bethlehem","title":"O Little Town of Bethlehem","language":"en","writers":"Phillips Brooks","music":"Lewis H. Redner","year":1867,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ST. LOUIS","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nO little town of Bethlehem, how still we see thee lie!\nAbove thy deep and dreamless sleep the silent stars go by.\nYet in thy dark streets shineth the everlasting Light;\nThe hopes and fears of all the years are met in thee tonight.\n\nVerse 2\nFor Christ is born of Mary, and gathered all above,\nWhile mortals sleep, the angels keep their watch of wond'ring love.\nO morning stars together, proclaim the holy birth,\nAnd praises sing to God the King, and peace to men on earth!\n\nVerse 3\nHow silently, how silently, the wondrous Gift is giv'n;\nSo God imparts to human hearts the blessings of His Heav'n.\nNo ear may hear His coming, but in this world of sin,\nWhere meek souls will receive Him still, the dear Christ enters in.\n\nVerse 4\nWhere children pure and happy pray to the blessèd Child,\nWhere misery cries out to Thee,\nSon of the mother mild;\nWhere charity stands watching and faith holds wide the door,\nThe dark night wakes, the glory breaks, and Christmas comes once more.\n\nVerse 5\nO holy Child of Bethlehem, descend to us, we pray;\nCast out our sin, and enter in, be born in us today.\nWe hear the Christmas angels the great glad tidings tell;\nO come to us, abide with us, our Lord Emmanuel!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-lord-how-shall-i-meet-thee","title":"O Lord, How Shall I Meet Thee","language":"en","writers":"Paul Gerhardt, 1653. translator unknown","music":"Johann Crüger","year":1653,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"WIE SOLL ICH DICH EMPFANGE","themes":["Hymn"],"lyrics":"Verse 1\nO Lord, how shall I meet Thee,\nHow welcome Thee aright?\nAll nations long to see Thee,\nMy Hope, my heart's Delight!\nO kindle, Lord, most holy,\nThy lamp within my breast,\nTo do in spirit lowly All that may please Thee best.\n\nVerse 2\nThy Zion palms is strewing,\nAnd branches fresh and fair;\nMy heart, its pow'rs renewing,\nAn anthem shall prepare.\nMy soul puts off her sadness Thy glories to proclaim;\nWith all her strength and gladness She fain would serve Thy Name.\n\nVerse 3\nWhat hast Thou left ungranted To give me glad relief?\nWhen soul and body panted In utmost depth of grief,\nIn deepest degradation, Devoid of joy and peace,\nThen, Thou, my soul's Salvation,\nDidst come to bring release.\n\nVerse 4\nI lay in fetters groaning,\nThou com'st to set me free;\nI stood, my shame bemoaning,\nThou com'st to honor me.\nA glory Thou dost give me,\nA treasure safe on high,\nThat will not fail nor leave me As earthly riches fly.\n\nVerse 5\nLove caused Thine incarnation Love brought Thee down to me;\nThy thirst for my salvation Procured my liberty.\nO love beyond all telling,\nThat led Thee to embrace,\nIn love all love excelling,\nOur lost and fallen race!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-lord-i-am-not-worthy","title":"O Lord, I Am Not Worthy","language":"en","writers":"from Landshuter Gesangbuch, 1777. Translation unknown, before","music":"traditional air, before","year":1777,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"NON DIGNUS","themes":["Hymn"],"lyrics":"Verse 1\nO Lord, I am not worthy That Thou should'st come to me,\nBut speak the words of comfort,\nMy spirit healed shall be.\n\nVerse 2\nO Lord, Thou art all holy,\nThe angels Thee adore;\nHow, then, ought I sincerely My wrongs and sins deplore!\n\nVerse 3\nBut when Thou soon wilt enter My heart, my sinful heart,\nThen heal me, be my shelter,\nFor Thou my Savior art.\n\nVerse 4\nO Lord, how can I thank Thee For such a gift as this?\nA gift which truly filleth My soul with heav'nly bliss!\n\nVerse 5\nI praise Thee, I extol Thee,\nI love Thee O my Sire,\nTill once in joy and glory,\nIn heav'n I Thee admire.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-lord-my-soul-convicted","title":"O Lord My Soul Convicted","language":"en","writers":"James Maxwell","music":"from \"Musikalisches Handbuch\", Hamburg","year":1759,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"WINCHESTER NEW","themes":["Hymn"],"lyrics":"Verse 1\nO Lord, my soul convicted stands Of breaking all Thy ten commands:\nAnd on me justly might'st Thou pour Thy wrath in one eternal show'r.\n\nVerse 2\nBut thanks to God,\nits loud alarms Have warn'd me of approaching harms;\nAnd now, O Lord, my wants I see,\nLost and undone, I come to Thee.\n\nVerse 3\nI know my fig leaf righteousness Can ne'er Thy broken law redress;\nYet in the gospel plan I see,\nThere's hope of pardon e'en for me.\n\nVerse 4\nThere, I behold with wonder,\nLord! That Christ hath to Thy law restor'd\nThose honors on th'atoning day,\nWhich guilty sinners took away.\n\nVerse 5\nAmazing wisdom, pow'r and love,\nDisplay'd to rebels from above!\nDo Thou, O Lord,\nmy faith increase To love and trust Thy plan of grace.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-o-lord-of-heav-n-and-earth-and-sea","title":"O Lord of Heav'n and Earth and Sea","language":"en","writers":"Christopher Wordsworth","music":"Johann D. Meyer","year":1863,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"ES IST KEIN TAG","themes":["Hymn"],"lyrics":"Verse 1\nO Lord of Heav'n and earth and sea,\nTo Thee all praise and glory be;\nHow shall we show our love to Thee, Who givest all?\n\nVerse 2\nThe golden sunshine, vernal air,\nSweet flow'rs and fruits,\nThy love declare; Where harvests ripen,\nThou art there, Who givest all.\n\nVerse 3\nFor peaceful homes and healthful days,\nFor all the blessings earth displays,\nWe owe Thee thankfulness and praise, Who givest all.\n\nVerse 4\nThou didst not spare Thine only Son,\nBut gav'st Him for a world undone,\nAnd freely, with that blessèd One, Thou givest all.\n\nVerse 5\nThou giv'st the Spirit's blessèd dow'r,\nSpirit of life and love and pow'r,\nAnd dost His sev'nfold graces show'r Upon us all.\n\nVerse 6\nFor souls redeemed, for sins forgiv'n,\nFor means of grace and hopes of Heav'n,\nFather, all praise to Thee be giv'n,\nWho givest all.\n\nVerse 7\nWe lose what on ourselves we spend,\nWe have as treasure without end\nWhatever, Lord, to Thee we lend,\nWho givest all.\n\nVerse 8\nTo Thee, from Whom we all derive\nOur life, our gifts, our power to give:\nO may we ever with Thee live,\nWho givest all.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-o-lord-we-praise-thee","title":"O Lord We Praise Thee","language":"en","writers":"Martin Luther, 1524. Translation composite","music":"traditional German c. 1400 found in Klug's Geistliche Lieder, Wittenberg","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"GOTT SEI GELOBET UND GEBENEDEIET","themes":["Hymn"],"lyrics":"Verse 1\nO Lord, we praise Thee, bless Thee, and adore Thee,\nIn thanksgiving bow before Thee Thou with Thy body and\nThy blood didst nourish Our weak souls that they may flourish:\nO Lord, have mercy!\nMay Thy body, Lord, born of Mary,\nThat our sins and sorrows did carry,\nAnd Thy blood for us plead In all trial, fear, and need:\nO Lord, have mercy!\n\nVerse 2\nThy holy body into death was given,\nLife to win for us in heaven.\nNo greater love than this to Thee could bind us;\nMay this feast thereof remind us!\nO Lord, have mercy!\nLord, Thy kindness did so constrain Thee\nThat Thy blood should bless and sustain me.\nAll our debt Thou hast paid;\nPeace with God once more is made:\nO Lord, have mercy.\n\nVerse 3\nMay God bestow on us His grace and favor\nTo please Him with our behavior\nAnd live as brethren here in love and union\nNor repent this blest Communion!\nO Lord, have mercy!\nLet not Thy good Spirit forsake us;\nGrant that heav'nly-minded He make us;\nGive Thy Church, Lord, to see Days of peace and unity:\nO Lord, have mercy!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-o-love-how-deep-how-broad-how-high","title":"O Love, How Deep, How Broad, How High","language":"en","writers":"Unknown, 15th Century; Translated by Benjamin Webb, 1852, alt","music":"traditional English","year":1852,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"DEO GRACIAS","themes":["Hymn"],"lyrics":"Verse 1\nO love, how deep, how broad, how high,\nHow passing thought and fantasy,\nThat God, the Son of God,\nshould take Our mortal form for mortals' sake!\n\nVerse 2\nHe sent no angel to our race Of higher or of lower place,\nBut wore the robe of human frame And He Himself, to this world came.\n\nVerse 3\nNor willed He only to appear;\nHis pleasure was to tarry here;\nAnd God and Man with man would be The space of thirty years and three.\n\nVerse 4\nFor us baptized, for us He bore His holy fast and hungered sore,\nFor us temptations sharp He knew;\nFor us the tempter overthrew.\n\nVerse 5\nFor us He prayed; for us He taught;\nFor us His daily works He wrought;\nBy words and signs and actions thus Still seeking not Himself, but us.\n\nVerse 6\nFor us to wicked men betrayed,\nScourged, mocked, in crown of thorns arrayed,\nFor us He bore the cross's death,\nFor us at length gave up His breath.\n\nVerse 7\nFor us He rose from death again;\nFor us He went on high to reign;\nFor us He sent His Spirit here,\nTo guide, to strengthen, and to cheer.\n\nVerse 8\nAll honor, laud, and glory be,\nO Jesus, virgin-born to Thee!\nAll glory, as is ever meet\nTo Father and to Paraclete.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8"],"source":"Open Hymnal Project"},{"id":"oh-o-sacred-head-now-wounded","title":"O Sacred Head, Now Wounded","language":"en","writers":"Bernard of Clairvaux, 1153. Translated by James W. Alexander","music":"Hans Leo Hassler, 1601. Adapted by J.S. Bach","year":1153,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"PASSION CHORALE","themes":["Hymn","Lent"],"lyrics":"Verse 1\nO sacred Head, now wounded, with grief and shame weighed down,\nNow scornfully surrounded with thorns,\nThine only crown; O sacred Head,\nwhat glory, what bliss till now was Thine!\nYet, though despised and gory,\nI joy to call Thee mine.\n\nVerse 2\nWhat Thou, my Lord, hast suffered, was all for sinners' gain;\nMine, mine was the transgression, but Thine the deadly pain.\nLo, here I fall, my Savior!\n'Tis I deserve Thy place;\nLook on me with Thy favor, vouchsafe to me Thy grace.\n\nVerse 3\nMen mock and taunt and jeer Thee,\nThou noble countenance,\nThough mighty worlds shall fear Thee and flee before Thy glance.\nHow art thou pale with anguish, with sore abuse and scorn!\nHow doth Thy visage languish that once was bright as morn!\n\nVerse 4\nNow from Thy cheeks has vanished their color once so fair;\nFrom Thy red lips is banished the splendor that was there.\nGrim death, with cruel rigor, hath robbed Thee of Thy life;\nThus Thou hast lost Thy vigor,\nThy strength in this sad strife.\n\nVerse 5\nMy burden in Thy Passion,\nLord, Thou hast borne for me,\nFor it was my transgression which brought this woe on Thee.\nI cast me down before Thee, wrath were my rightful lot;\nHave mercy, I implore Thee;\nRedeemer, spurn me not!\n\nVerse 6\nWhat language shall I borrow to thank Thee, dearest friend,\nFor this Thy dying sorrow, Thy pity without end?\nO make me Thine forever, and should I fainting be,\nLord, let me never, never outlive my love to Thee.\n\nVerse 7\nMy Shepherd, now receive me; my Guardian, own me Thine.\nGreat blessings Thou didst give me, O source of gifts divine.\nThy lips have often fed me with words of truth and love;\nThy Spirit oft hath led me to heavenly joys above.\n\nVerse 8\nHere I will stand beside Thee, from Thee I will not part;\nO Savior, do not chide me! When breaks Thy loving heart,\nWhen soul and body languish in death's cold, cruel grasp,\nThen, in Thy deepest anguish, Thee in mine arms I'll clasp.\n\nVerse 9\nThe joy can never be spoken, above all joys beside,\nWhen in Thy body broken I thus with safety hide.\nO Lord of Life, desiring Thy glory now to see,\nBeside Thy cross expiring, I'd breathe my soul to Thee.\n\nVerse 10\nMy Savior, be Thou near me when death is at my door;\nThen let Thy presence cheer me, forsake me nevermore!\nWhen soul and body languish, oh, leave me not alone,\nBut take away mine anguish by virtue of Thine own!\n\nVerse 11\nBe Thou my consolation, my shield when I must die;\nRemind me of Thy passion when my last hour draws nigh.\nMine eyes shall then behold Thee, upon Thy cross shall dwell,\nMy heart by faith enfolds Thee. Who dieth thus dies well.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10","Verse 11"],"source":"Open Hymnal Project"},{"id":"oh-o-that-the-lord-would-guide-my-ways","title":"O That The Lord Would Guide My Ways","language":"en","writers":"Isaac Watts, 1719, alt","music":"William H. Havergal","year":1719,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"EVAN","themes":["Hymn"],"lyrics":"Verse 1\nO that the Lord would guide my ways To keep His statutes still!\nO that my God would grant me grace To know and do His will!\n\nVerse 2\nO send Thy Spirit down to write Thy law upon my heart!\nNor let my tongue indulge deceit,\nNor act the liar's part.\n\nVerse 3\nFrom vanity turn off mine eyes;\nLet no corrupt design,\nNor covetous desires arise Within this soul of mine.\n\nVerse 4\nOrder my footsteps by Thy Word,\nAnd make my heart sincere;\nLet sin have no dominion,\nLord, But keep my conscience clear.\n\nVerse 5\nAssist my soul, too apt to stray,\nA stricter watch to keep;\nAnd should I e'er forget Thy way,\nRestore Thy wand'ring sheep.\n\nVerse 6\nMake me to walk in Thy commands, 'Tis a delightful road;\nNor let my head, or heart, or hands, Offend against my God.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-o-the-deep-deep-love-of-jesus","title":"O The Deep, Deep Love of Jesus","language":"en","writers":"S. Trevor Francis","music":"Thomas J. Williams","year":1875,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"EBENEZER","themes":["Hymn"],"lyrics":"Verse 1\nO the deep, deep love of Jesus, vast, unmeasured, boundless, free!\nRolling as a mighty ocean in its fullness over me!\nUnderneath me, all around me,\nis the current of Thy love Leading onward,\nleading homeward to Thy glorious rest above!\n\nVerse 2\nO the deep, deep love of Jesus, spread His praise from shore to shore!\nHow He loveth, ever loveth, changeth never, nevermore!\nHow He watches o'er His loved ones, died to call them all His own;\nHow for them He intercedeth, watcheth o'er them from the throne!\n\nVerse 3\nO the deep, deep love of Jesus, love of every love the best!\n'Tis an ocean full of blessing,\n'tis a haven giving rest!\nO the deep, deep love of Jesus,\n'tis a heav'n of heav'ns to me;\nAnd it lifts me up to glory, for it lifts me up to Thee!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-o-wondrous-type-o-vision-fair","title":"O Wondrous Type, O Vision Fair","language":"en","writers":"From the \"Sarum Breviary\", 1495. Translated by John Mason Neale","music":"traditional English","year":1495,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"DEO GRACIAS","themes":["Hymn"],"lyrics":"Verse 1\nO wondrous type! O vision fair Of glory that the Church may share,\nWhich Christ upon the mountain shows,\nwhere brighter than the sun He glows!\n\nVerse 2\nFrom age to age the tale declare,\nHow with the three disciples there,\nWhere Moses and Elijah meet,\nThe Lord holds converse high and sweet.\n\nVerse 3\nThe law and prophets there have place,\nTwo chosen witnesses of grace;\nThe Father's voice from out the cloud proclaims His only Son aloud.\n\nVerse 4\nWith shining face and bright array,\nChrist deigns to manifest today\nWhat glory shall be theirs above who joy in God with perfect love.\n\nVerse 5\nAnd faithful hearts are raised on high by this great vision's mystery;\nFor which in joyful strains we raise the voice of prayer,\nthe hymn of praise.\n\nVerse 6\nO Father, with th'Eternal Son,\nand Holy Spirit, ever One,\nVouchsafe to bring us by Thy grace\nto see Thy glory face to face.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-of-the-father-s-love-begotten","title":"Of The Father's Love Begotten","language":"en","writers":"Aurelius Prudentius Clemens, 5th Century. Verses 1, 4-8 translated by John Mason Neale, 1854. Verses 2-3, 9 translated by Henry Williams Baker","music":"Latin Plainsong, 13th Century","year":1854,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"DIVINUM MYSTERIUM","themes":["Hymn"],"lyrics":"Verse 1\nOf the Father's love begotten Ere the worlds began to be,\nHe is Alpha and Omega,\nHe the source, the ending He,\nOf the things that are, that have been,\nAnd that future years shall see, Evermore and evermore!\n\nVerse 2\nAt His Word they were created;\nHe commanded; it was done:\nHeav'n and earth and depths of ocean In their threefold order one;\nAll that grows beneath the shining Of the moon and burning sun,\nEvermore and evermore!\n\nVerse 3\nHe is found in human fashion,\nDeath and sorrow here to know,\nThat the race of Adam's children,\nDoomed by law to endless woe,\nMay not henceforth die and perish In the dreadful gulf below,\nEvermore and evermore!\n\nVerse 4\nOh that birth forever blessèd!\nWhen the virgin, full of grace,\nBy the Holy Ghost conceiving,\nBare the Savior of our race;\nAnd the Babe, the world's Redeemer,\nFirst revealed His sacred face, Evermore and evermore!\n\nVerse 5\nO ye heights of heav'n adore Him;\nAngel hosts, His praises sing;\nPow'rs, dominions, bow before Him, and extol our God and King:\nLet no tongue on earth be silent,\nEvery voice in concert ring, Evermore and evermore!\n\nVerse 6\nHe is here, Whom seers in old time Chanted of, while ages ran;\nWhom the writings of the prophets Promised since the world began:\nThen foretold, now manifested, to receive the praise of man,\nEvermore and evermore!\n\nVerse 7\nRighteous Judge of souls departed, Righteous King of them that live,\nOn the Father's throne exalted None in might with Thee may strive;\nWho at last in vengeance coming Sinners from Thy face shalt drive,\nEvermore and evermore!\n\nVerse 8\nThee let old men, Thee let young men, Thee let choirs of infants sing;\nThee the matrons and the virgins, And the children answering:\nLet their guileless songs re-echo, And the heart its music bring,\nEvermore and evermore!\n\nVerse 9\nChrist, to Thee with God the Father, And, O Holy Ghost, to Thee,\nHymn and chant with high thanksgiving, And unwearied praises be:\nHonor, glory, and dominion, And eternal victory,\nEvermore and evermore!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9"],"source":"Open Hymnal Project"},{"id":"oh-oh-blest-the-house","title":"Oh, Blest the House","language":"en","writers":"Christoph C. L. von Pfeil, 1735. Translated by Catherine Winkworth, 1863, alt","music":"from Klug's Geistliche Lieder","year":1735,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"WO GOTT ZUM HAUS","themes":["Hymn"],"lyrics":"Verse 1\nOh blest the house, whate'er befall,\nWhere Jesus Christ is All in All;\nYea, if He were not dwelling there,\nHow poor and dark and void it were!\n\nVerse 2\nOh blest that house where faith ye find,\nAnd all within have set their mind\nTo trust their God and serve Him still,\nAnd do in all His holy will.\n\nVerse 3\nBlest, where their prayers shall daily rise\nAs fragrant incense to the skies,\nWhile in their lives the world is taught\nThat forms without the heart are naught.\n\nVerse 4\nBlest, where the busy hands fulfil Their proper task with ready skill,\nWhile through their different works ye see One spirit run of unity.\n\nVerse 5\nBlest such a house, it prospers well,\nIn peace and joy the parents dwell,\nAnd in their children's lot is shown How richly God can bless His own.\n\nVerse 6\nThen here will I and mine to-day\nA solemn covenant make, and say,--\nThough all the world forsake Thy Word,\nI and my house will serve the Lord.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-on-jordan-s-bank-the-baptist-s-cry","title":"On Jordan's Bank the Baptist's Cry","language":"en","writers":"Charles Coffin, 1736. st. 1-3 translated by John Chandler, 1837; st 4-5 translator unknown","music":"Michael Praetorius","year":1736,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"PUER NOBIS NASCITUR","themes":["Hymn"],"lyrics":"Verse 1\nOn Jordan's bank the Baptist's cry Announces that the Lord is nigh;\nCome, then, and hearken,\nfor he brings Glad tidings from the King of kings!\n\nVerse 2\nThen cleansed be every breast from sin;\nMake straight the way for God within;\nPrepare we in our hearts a home,\nWhere such a mighty Guest may come.\n\nVerse 3\nFor Thou art our Salvation,\nLord, Our Refuge, and our great Reward.\nWithout Thy grace our souls must fade\nAnd wither like a flow'r decayed.\n\nVerse 4\nStretch forth Thine hand, to heal our sore,\nAnd make us rise and fall no more;\nOnce more upon Thy people shine,\nAnd fill the world with love divine.\n\nVerse 5\nTo Him Who left the throne of Heav'n To save mankind,\nall praise be giv'n;\nLike praise be to the Father done,\nAnd Holy Spirit, Three in One.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-on-what-has-now-been-sown","title":"On What Has Now Been Sown","language":"en","writers":"John Newton","music":"s 148th' John Darwall","year":1779,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"DARWALL","themes":["Hymn"],"lyrics":"Verse 1\nOn what has now been sown Thy blessing,\nLord, bestow; The pow'r is Thine alone To make it spring and grow.\nDo Thou in grace the harvest raise,\nAnd Thou alone shalt have the praise.\n\nVerse 2\nTo Thee our wants are known,\nFrom Thee are all our pow'rs;\nAccept what is Thine own And pardon what is ours.\nOur praises, Lord,\nand prayers receive And to Thy Word a blessing give.\n\nVerse 3\nOh, grant that each of us Now met before\nThee here May meet together thus\nWhen Thou and Thine appear And follow Thee to Heav'n, our home.\nE'en so, Amen, Lord Jesus, come!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-one-thing-s-needful","title":"One Thing's Needful","language":"en","writers":"Johann H. Schröder, 1697. Translated by Frances E. Cox, 1841, alt","music":"Adam Krieger (1634-1666)","year":1697,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"EINS IST NOT","themes":["Hymn"],"lyrics":"Verse 1\nOne thing's needful: then,\nLord Jesus, Keep this one thing in my mind;\nAll beside, though first it please us,\nSoon a grievous yoke we find:\nBeneath it the heart is still fretting and striving,\nNo true, lasting happiness ever deriving.\nThe gain of this one thing all loss can requite\nAnd teach me in all things to find true delight.\n\nVerse 2\nSoul, wilt thou this one thing find thee?\nSeek not midst created things;\nWhat is earthly, leave behind thee, over nature stretch thy wings;\nFor where God and man both in One are united,\nWith God's perfect fullness the heart is delighted;\nThere, there is the worthiest lot and the best,\nMy One and my All, and my Joy, and my Rest.\n\nVerse 3\nHow were Mary's thoughts devoted,\nHer eternal joy to find,\nAs intent each word she noted,\nAt her Savior's feet reclined:\nHow kindled her heart, how devout was its feeling,\nWhile hearing the lessons that Christ was revealing;\nFor Jesus all earthly concerns she forgot,\nAnd all was repaid in that one happy lot.\n\nVerse 4\nThus my longings, heav'nward tending,\nJesus, rest alone on Thee;\nHelp me, thus on Thee depending,\nSavior! come and dwell in me:\nAlthough all the world should forsake and forget Thee,\nIn love I will follow Thee, ne'er will I quit Thee;\nFor Jesus, both Spirit and life is Thy Word,\nAnd is there a joy which Thou dost not afford?\n\nVerse 5\nWisdom's highest noblest treasure,\nJesus, lies conceal'd in Thee;\nGrant that this may still the measure Of my will and actions be:\nHumility there and simplicity reigning,\nMy steps shall in wisdom for ever be training;\nOh! if I of Christ have this knowledge divine,\nThe fullness of heavenly wisdom is mine.\n\nVerse 6\nChrist, Thou art the sole oblation\nThat I'll bring before my God;\nIn his sight I've acceptation\nOnly through Thy streaming blood:\nImmaculate righteousness now I've acquired,\nSince Thou on the tree of the cross hast expired;\nThe robe of salvation for ever is mine,\nIn this shall my faith through eternity shine.\n\nVerse 7\nLet my soul, in full exemption,\nWake up in Thy likeness now;\nThou art made to me redemption,\nMy sanctification Thou.\nWhatever I need for my Journey to Heaven\nIn Thee, I my Savior, is unto me given.\nOh! let me all perishing pleasures forgo,\nAnd Thy life, O Jesus! alone let me know.\n\nVerse 8\nWhere should else my hopes be centered?\nGrace o'erwhelms me with its flood;\nThou, my Savior, once hast enter'd\nHoliest heaven through Thy blood:\nEternal redemption for sinners there finding,\nFrom hell's dark dominion my spirit unbinding,\nTo me perfect freedom Thy entrance has brought,\nAnd childlike to cry, \"Abba, Father,\" I'm taught.\n\nVerse 9\nChrist Himself, my Shepherd, feeds me,\nPeace and joy my spirit fill;\nIn a pasture green He leads me\nForth beside the waters still:\nOh! naught to my soul is so sweet and reviving,\nAs thus unto Jesus alone to be living;\nTrue happiness this, and this only supplies,\nThrough faith on my Savior to fasten my eyes.\n\nVerse 10\nTherefore, Jesus, my Salvation,\nThou my One, my All shalt be;\nProve my fix'd determination,\nRoot out all hypocrisy:\nLook well if on sin's slippery paths I am hasting,\nAnd lead me, O Lord, in the way everlasting;\nThis one thing is needful, all others are vain,\nI count all but loss that I Christ may obtain.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9","Verse 10"],"source":"Open Hymnal Project"},{"id":"oh-open-now-thy-gates-of-beauty","title":"Open Now Thy Gates of Beauty","language":"en","writers":"Benjamin Schmolck, 1730. Translated by Catherine Winkworth","music":"Joachim Neander","year":1730,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"UNSER HERRSCHER","themes":["Hymn"],"lyrics":"Verse 1\nOpen now thy gates of beauty,\nZion, let me enter there,\nWhere my soul in joyful duty Waits for Him Who answers prayer.\nOh, how blessèd is this place,\nFilled with solace, light and grace!\n\nVerse 2\nLord, my God, I come before Thee,\nCome Thou also unto me;\nWhere we find Thee and adore Thee,\nThere a heav'n on earth must be.\nTo my heart, oh, enter Thou,\nLet it be Thy temple now!\n\nVerse 3\nHere Thy praise is gladly chanted,\nHere Thy seed is duly sown;\nLet my soul, where it is planted,\nBring forth precious sheaves alone,\nSo that all I hear may be Fruitful unto life in me.\n\nVerse 4\nThou my faith increase and quicken,\nLet me keep Thy gift divine,\nHowsoe'er temptations thicken;\nMay Thy Word still o'er me shine As my guiding star through life,\nAs my comfort in my strife.\n\nVerse 5\nSpeak, O God, and I will hear Thee,\nLet Thy will be done indeed;\nMay I undisturbed draw near Thee While Thou dost Thy people feed.\nHere of life the fountain flows,\nHere is balm for all our woes.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-our-father-thou-in-heaven-above","title":"Our Father Thou in Heaven Above","language":"en","writers":"Martin Luther, 1539. Translation composite","music":"attr. Martin Luther, found in Valentin Schumann's Geistliche Lieder, Leipzig","year":1539,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"VATER UNSER IM HIMMELREICH","themes":["Hymn"],"lyrics":"Verse 1\nOur Father, Thou in heav'n above,\nWho biddest us to dwell in love,\nAs brethren of one family,\nTo cry in ev'ry need to Thee,\nTeach us no thoughtless word to say,\nBut from our inmost heart to pray.\n\nVerse 2\nThy name be hallowed.\nHelp us, Lord, In purity to keep Thy Word,\nThat to the glory of Thy Name We walk before Thee free from blame.\nLet no false doctrine us pervert;\nAll poor, deluded souls convert.\n\nVerse 3\nThy kingdom come. Thine let it be In time and in eternity.\nLet Thy good Spirit e'er be nigh Our hearts with graces to supply.\nBreak Satan's pow'r, defeat his rage;\nPreserve Thy Church from age to age.\n\nVerse 4\nThy gracious will on earth be done\nAs 'tis in heav'n before Thy throne;\nObedience in our weal and woe And patience in all grief bestow.\nCurb flesh and blood and ev'ry ill That sets itself against Thy will.\n\nVerse 5\nGive us this day our daily bread And let us all be clothed and fed.\nFrom war and strife be our Defense,\nFrom famine and from pestilence,\nThat we may live in godly peace,\nFree from all care and avarice.\n\nVerse 6\nForgive our sins, Lord, we implore,\nRemove from us their burden sore,\nAs we their trespasses forgive\nWho by offenses us do grieve.\nThus let us dwell in charity\nAnd serve our brother willingly.\n\nVerse 7\nInto temptation lead us not.\nWhen evil foes against us plot\nAnd vex our souls on every hand,\nOh, give us strength that we may stand\nFirm in the faith, a well-armed host,\nThrough comfort of the Holy Ghost!\n\nVerse 8\nFrom evil, Lord, deliver us;\nThe times and days are perilous.\nRedeem us from eternal death,\nAnd when we yield our dying breath,\nConsole us, grant us calm release,\nAnd take our souls to Thee in peace.\n\nVerse 9\nAmen, that is, So shall it be.\nConfirm our faith and hope in Thee\nThat we may doubt not, but believe\nWhat here we ask we shall receive.\nThus in Thy name and at Thy word\nWe say: Amen. Oh, hear us, Lord! Amen.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9"],"source":"Open Hymnal Project"},{"id":"oh-our-god-our-help-in-ages-past","title":"Our God, Our Help In Ages Past","language":"en","writers":"Isaac Watts","music":"William Croft","year":1719,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"ST. ANNE","themes":["Hymn"],"lyrics":"Verse 1\nOur God, our help in ages past,\nOur hope for years to come,\nOur shelter from the stormy blast,\nAnd our eternal home.\n\nVerse 2\nUnder the shadow of Thy throne Thy saints have dwelt secure;\nSufficient is Thine arm alone,\nAnd our defense is sure.\n\nVerse 3\nBefore the hills in order stood,\nOr earth received her frame,\nFrom everlasting Thou art God,\nTo endless years the same.\n\nVerse 4\nThy Word commands our flesh to dust,\n'Return, ye sons of men:' All nations rose from earth at first,\nAnd turn to earth again.\n\nVerse 5\nA thousand ages in Thy sight Are like an evening gone;\nShort as the watch that ends the night Before the rising sun.\n\nVerse 6\nThe busy tribes of flesh and blood,\nWith all their lives and cares,\nAre carried downwards by the flood,\nAnd lost in following years.\n\nVerse 7\nTime, like an ever rolling stream,\nBears all its sons away;\nThey fly, forgotten, as a dream\nDies at the opening day.\n\nVerse 8\nLike flowery fields the nations stand\nPleased with the morning light;\nThe flowers beneath the mower's hand\nLie withering ere 'tis night.\n\nVerse 9\nOur God, our help in ages past,\nOur hope for years to come,\nBe Thou our guard while troubles last,\nAnd our eternal home.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7","Verse 8","Verse 9"],"source":"Open Hymnal Project"},{"id":"oh-out-of-the-deep-i-cry-to-thee","title":"Out of the Deep I Cry to Thee","language":"en","writers":"Martin Luther, 1524. Translated by Arthur Tozer Russell (1806-1874)","music":"Martin Luther from Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"AUS TIEFER NOT (LUTHER)","themes":["Hymn"],"lyrics":"Verse 1\nOut of the deep I cry to Thee;\nO Lord God, hear my crying:\nIncline Thy gracious ear to me,\nWith prayer to Thee applying.\nFor if Thou fix Thy searching eye On all sin and iniquity,\nWho, Lord, can stand before Thee?\n\nVerse 2\nBut love and grace with Thee prevail,\nO God, our sins forgiving;\nThe holiest deeds can naught avail Of all before Thee living.\nBefore Thee none can boast him clear;\nTherefore must each Thy judgment fear,\nAnd live on Thy compassion.\n\nVerse 3\nFor this, my hope in God shall rest,\nNaught building on my merit;\nMy heart confides, of Him possest,\nHis goodness stays my spirit.\nHis precious word assureth me;\nMy solace, my sure Rock is he,\nWhereon my soul abideth.\n\nVerse 4\nAnd though I wait the livelong night And till the morn returneth,\nMy heart undoubting trusts His might Nor in impatience mourneth.\nBorn of His Spirit,\nIsrael In the right Way thus fareth well,\nAnd on his God reposeth\n\nVerse 5\nWhat though our sins are manifold?\nSupreme His mercy reigneth;\nNo limit can His hand withhold,\nWhere evil most obtaineth.\nHe the good Shepherd is alone,\nWho Israel will redeem and own, Forgiving all transgression.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-over-kidron-jesus-treadeth","title":"Over Kidron Jesus Treadeth","language":"en","writers":"Thomas Hansen Kingo, 1689. Translated by J. Jeffrey, before","music":"Ludvig Mathias Lindeman","year":1689,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"OVER KEDRON JESUS TRAEDER","themes":["Hymn"],"lyrics":"Verse 1\nOver Kidron Jesus treadeth To His passion for us all;\nEvery human eye be weeping,\nTears of bitter grief let fall!\nRound His Spirit flock the foes,\nPlace their shafts and bend their bows,\nAiming at the Savior solely,\nWhile the world forsakes Him wholly.\n\nVerse 2\nDavid once, with heart afflicted,\nCrossed the Kidron's narrow strand,\nClouds of gloom and grief about him When an exile from his land.\nBut, O Jesus, blacker now Bends the cloud above Thy brow,\nHasting to death's dreary portals For the shame and sin of mortals.\n\nVerse 3\nSee how, anguish struck,\nHe falleth Prostrate, and with struggling breath,\nThree times on His God He calleth,\nPraying that the bitter death And the cup of doom may go,\nStill He cries, in all His woe:\n\"Not My will, but Thine,\nO Father!\" And the angels round Him gather.\n\nVerse 4\nSee how, in that hour of darkness,\nBattling with the evil pow'r,\nAgonies untold assail Him,\nOn His soul the arrows show'r;\nAll the garden flow'rs are wet With the drops of bloody sweat,\nFrom His anguished frame distilling —\nWorld's redemption thus fulfilling!\n\nVerse 5\nBut, O flow'rs, so sadly watered By this pure and precious dew,\nIn some blessed hour your blossoms 'Neath the olive shadows grew!\nEden's garden did not bear Aught that can with you compare,\nFor the blood, thus freely given,\nMakes my soul the heir of heaven.\n\nVerse 6\nWhen as flow'rs themselves I wither, When I droop and fade like grass,\nWhen the life-streams through my pulses Dull and ever duller pass,\nWhen at last they cease to roll, Then, to cheer my sinking soul,\nGrace of Jesus, be Thou given- Source of triumph! pledge of heaven!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-pass-me-not-o-gentle-savior","title":"Pass Me Not, O Gentle Savior","language":"en","writers":"Fanny J. Crosby","music":"William Howard Doane","year":1868,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"PASS ME NOT O GENTLE SAVIOR","themes":["Hymn"],"lyrics":"Verse 1\nPass me not, O gentle Savior,\nHear my humble cry;\nWhile on others Thou art calling,\nDo not pass me by.\n\nChorus\nSavior, Savior, Hear my humble cry;\nWhile on others Thou art calling,\nDo not pass me by.\n\nVerse 2\nLet me at Thy throne of mercy Find a sweet relief,\nKneeling there in deep contrition; Help my unbelief.\n\nVerse 3\n3, Trusting only in Thy merit,\nWould I seek Thy face;\nHeal my wounded, broken spirit,\nSave me by Thy grace.\n\nVerse 4\nThou the Spring of all my comfort,\nMore than life to me,\nWhom have I on earth beside Thee?\nWhom in Heav'n but Thee?","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-praise-god-from-whom-all-blessings-flow","title":"Praise God From Whom All Blessings Flow","language":"en","writers":"Thomas Ken","music":"Genevan Psalter, attr. Louis Bourgeois","year":1674,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"OLD 100TH","themes":["Hymn"],"lyrics":"Verse 1\nPraise God, from Whom all blessings flow;\nPraise Him, all creatures here below;\nPraise Him above, ye heav'nly host;\nPraise Father, Son, and Holy Ghost.","arrangement":["Verse 1"],"source":"Open Hymnal Project"},{"id":"oh-praise-my-soul-the-king-of-heaven","title":"Praise My Soul The King Of Heaven","language":"en","writers":"Henry F. Lyte","music":"John Goss","year":1834,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"PRAISE MY SOUL","themes":["Hymn"],"lyrics":"Verse 1\nPraise, my soul, the King of heaven;\nTo His feet thy tribute bring.\nRansomed, healed, restored, forgiven,\nEvermore His praises sing:\nAlleluia! Alleluia! Praise the everlasting King.\n\nVerse 2\nPraise Him for His grace and favor To our fathers in distress.\nPraise Him still the same as ever,\nSlow to chide, and swift to bless.\nAlleluia! Alleluia! Glorious in His faithfulness.\n\nVerse 3\nFather like He tends and spares us;\nWell our feeble frame He knows.\nIn His hands He gently bears us,\nRescues us from all our foes.\nAlleluia! Alleluia! Widely yet His mercy flows.\n\nVerse 4\nFrail as summer's flower we flourish,\nBlows the wind and it is gone;\nBut while mortals rise and perish Our God lives unchanging on,\nPraise Him, Praise Him,\nHallelujah Praise the High Eternal One!\n\nVerse 5\nAngels, help us to adore Him;\nYe behold Him face to face;\nSun and moon, bow down before Him,\nDwellers all in time and space.\nAlleluia! Alleluia! Praise with us the God of grace.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-praise-the-lord-ye-heavens-adore-him","title":"Praise The Lord, Ye Heavens Adore Him","language":"en","writers":"verses 1-2, unknown, 1796. verse 3 Edward Osler","music":"Franz Joseph Haydn","year":1796,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"AUSTRIA (HAYDN)","themes":["Hymn"],"lyrics":"Verse 1\nPraise the Lord, ye heav'ns, adore Him;\nPraise Him, angels in the height.\nSun and moon, rejoice before Him;\nPraise Him, all ye stars of light.\nPraise the Lord, for He hath spoken;\nWorlds His mighty voice obeyed.\nLaws which never shall be broken For their guidance He hath made.\n\nVerse 2\nPraise the Lord, for He is glorious;\nNever shall His promise fail.\nGod hath made His saints victorious;\nSin and death shall not prevail.\nPraise the God of our salvation;\nHosts on high, His pow'r proclaim.\nHeav'n and earth and all creation,\nLaud and magnify His name.\n\nVerse 3\nWorship, honor, glory, blessing,\nLord, we offer unto Thee.\nYoung and old, Thy praise expressing,\nIn glad homage bend the knee.\nAll the saints in Heav'n adore Thee;\nWe would bow before Thy throne.\nAs Thine angels serve before Thee,\nSo on earth Thy will be done.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-praise-to-the-lord-the-almighty","title":"Praise To The Lord, The Almighty","language":"en","writers":"Joachim Neander, 1680. Translated by Catherine Winkworth","music":"from Ander Theil des Erneuerten Gesangbuch","year":1680,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"LOBE DEN HERREN","themes":["Hymn"],"lyrics":"Verse 1\nPraise to the Lord, the Almighty, the King of creation!\nO my soul, praise Him, for He is thy health and salvation!\nAll ye who hear, now to His temple draw near;\nPraise Him in glad adoration.\n\nVerse 2\nPraise to the Lord,\nWho o'er all things so wondrously reigneth,\nShelters thee under His wings, yea, so gently sustaineth!\nHast thou not seen how thy desires have been\nGranted in what He ordaineth\n\nVerse 3\nPraise to the Lord,\nWho hath fearfully, wondrously, made thee;\nHealth hath vouchsafed and, when heedlessly falling, hath stayed thee.\nWhat need or grief ever hath failed of relief?\nWings of His mercy did shade thee.\n\nVerse 4\nPraise to the Lord,\nWho doth prosper thy work and defend thee;\nSurely His goodness and mercy here daily attend thee.\nPonder anew what the Almighty can do,\nIf with His love He befriend thee.\n\nVerse 5\nPraise to the Lord,\nWho, when tempests their warfare are waging,\nWho, when the elements madly around thee are raging,\nBiddeth them cease, turneth their fury to peace,\nWhirlwinds and waters assuaging.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-rejoice-my-heart-be-glad-and-sing","title":"Rejoice, My Heart, Be Glad and Sing","language":"en","writers":"Paul Gerhardt, 1653. Translation composite","music":"Johann Balthasar König","year":1653,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"ICH SINGE DIR MIT HERZ","themes":["Hymn"],"lyrics":"Verse 1\nRejoice, my heart, be glad and sing,\nA cheerful trust maintain;\nFor God, the Source of everything,\nThy Portion shall remain.\n\nVerse 2\nHe is thy Treasure,\nHe thy Joy, Thy Life and Light and Lord,\nThy Counselor when doubts annoy,\nThy Shield and great Reward.\n\nVerse 3\nWhy spend the day in blank despair,\nIn restless thought the night?\nOn thy Creator cast thy care;\nHe makes thy burdens light.\n\nVerse 4\nDid not His love and truth and pow'r Watch o'er thy childhood day?\nHas He not oft in threat'ning hour Turned dreaded ills away?\n\nVerse 5\nHis wisdom never plans in vain,\nNe'er falters or mistakes;\nAll that His counsels did ordain A happy ending makes.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-rejoice-o-pilgrim-throng","title":"Rejoice, O Pilgrim Throng","language":"en","writers":"Edward H. Plumptre, 1865, alt","music":"Arthur H. Messiter","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"MARION","themes":["Hymn"],"lyrics":"Verse 1\nRejoice, O pilgrim throng!\nRejoice, give thanks, and sing;\nYour festal banner wave on high,\nThe cross of Christ your King.\n\nChorus\nRejoice, rejoice, rejoice, Give thanks and sing.\n\nVerse 2\nWith all the angel choirs,\nWith all the saints on earth,\nPour out the strains of joy and bliss,\nTrue rapture, noblest mirth.\n\nVerse 3\nWith voice as full and strong As ocean's surging praise,\nSend forth the hymns our fathers loved,\nThe psalms of ancient days.\n\nVerse 4\nStill lift your standard high,\nStill march in firm array,\nAs warriors through the darkness toil,\nTill dawns the golden day.\n\nVerse 5\nYes, on through life's long path,\nStill chanting as ye go;\nFrom youth to age, by night and day,\nIn gladness and in woe.\n\nVerse 6\nYes onward, onward still With hymn, and chant and song,\nThrough gate, and porch and columned aisle, The hallowed pathways throng.\n\nVerse 7\nAt last the march shall end; The wearied ones shall rest;\nThe pilgrims find their Father's house, Jerusalem the bless'd.\n\nVerse 8\nThen on, ye pure in heart! Rejoice, give thanks and sing!\nYour festal banner wave on high, The cross of Christ your King.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus","Verse 7","Chorus","Verse 8","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-rescue-the-perishing","title":"Rescue the Perishing","language":"en","writers":"Fanny Crosby, 1869, alt","music":"William Howard Doane","year":1869,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"RESCUE THE PERISHING","themes":["Hymn"],"lyrics":"Verse 1\nRescue the perishing, care for the dying,\nSnatch them in pity from sin and the grave;\nWeep o'er the erring one, lift up the fallen,\nTell them of Jesus, the mighty to save. Rescue the perishing,\n\nChorus\ncare for the dying,\nJesus is merciful, Jesus will save.\n\nVerse 2\nThough they are slighting Him, still He is waiting,\nWaiting the penitent child to receive;\nPlead with them earnestly, plead with them gently;\nHe will forgive they should only believe.\n\nVerse 3\nDown in the human heart, crushed by the tempter,\nFeelings lie buried that grace can restore;\nTouched by a loving heart, wakened by kindness,\nChords that were broken will vibrate once more.\n\nVerse 4\nRescue the perishing, duty demands it;\nStrength for thy labor the Lord will provide;\nBack to the narrow way patiently win them;\nTell the poor wand'rer a Savior has died.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-rock-of-ages","title":"Rock of Ages","language":"en","writers":"Augustus Montague Toplady","music":"Thomas Hastings","year":1776,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"TOPLADY","themes":["Hymn"],"lyrics":"Verse 1\nRock of Ages, cleft for me,\nLet me hide myself in Thee;\nLet the water and the blood,\nFrom Thy wounded side which flowed,\nBe of sin the double cure;\nSave from wrath and make me pure.\n\nVerse 2\nNot the labor of my hands Can fulfill Thy law's demands;\nCould my zeal no respite know,\nCould my tears forever flow,\nAll for sin could not atone;\nThou must save, and Thou alone.\n\nVerse 3\nNothing in my hand I bring,\nSimply to the cross I cling;\nNaked, come to Thee for dress;\nHelpless look to Thee for grace;\nFoul, I to the fountain fly;\nWash me, Savior, or I die.\n\nVerse 4\nWhile I draw this fleeting breath,\nWhen mine eyes shall close in death,\nWhen I soar to worlds unknown,\nSee Thee on Thy judgment throne,\nRock of Ages, cleft for me,\nLet me hide myself in Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-salvation-unto-us-has-come","title":"Salvation Unto Us Has Come","language":"en","writers":"Paul Speratus, 1523. Translation composite","music":"traditional German circa 1400 from Etlich Christlich Lider, Wittenberg","year":1523,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"ES IST DAS HEIL UNS KOMMEN HER","themes":["Hymn"],"lyrics":"Verse 1\nSalvation unto us has come By God's free grace and favor;\nGood works cannot avert our doom,\nThey help and save us never.\nFaith looks to Jesus Christ alone,\nWho did for all the world atone;\nHe is our one Redeemer.\n\nVerse 2\nWhat God did in His law demand And none to Him could render\nCaused wrath and woe on every hand For man,\nthe vile offender.\nOur flesh has not those pure desires The spirit of the Law requires,\nAnd lost is our condition.\n\nVerse 3\nIt was a false,\nmisleading dream That God His Law had given\nSo sinners could themselves redeem And by their works gain Heaven.\nThe Law is but a mirror bright\nTo bring the inbred sin to light That lurks within our nature.\n\nVerse 4\nFrom sin our flesh could not abstain Sin held its sway unceasing;\nThe task was useless and in vain,\nOur guilt was e'er increasing.\nNone can remove sin's poisoned dart Or purify our guileful heart?\nSo deep is our corruption.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-savior-like-a-shepherd-lead-us","title":"Savior, Like A Shepherd Lead Us","language":"en","writers":"attr. Dorothy Ann Thrupp","music":"William B. Bradbury","year":1836,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"BRADBURY","themes":["Hymn"],"lyrics":"Verse 1\nSavior, like a shepherd lead us, much we need Thy tender care;\nIn Thy pleasant pastures feed us, for our use Thy folds prepare.\nBlessèd Jesus, blessèd Jesus!\nThou hast bought us,\nThine we are. Blessèd Jesus, blessèd Jesus!\nThou hast bought us, Thine we are.\n\nVerse 2\nWe are Thine, Thou dost befriend us, be the guardian of our way;\nKeep Thy flock, from sin defend us, seek us when we go astray.\nBlessèd Jesus, blessèd Jesus!\nHear, O hear us when we pray.\nBlessèd Jesus, blessèd Jesus!\nHear, O hear us when we pray.\n\nVerse 3\nThou hast promised to receive us, poor and sinful though we be;\nThou hast mercy to relieve us, grace to cleanse and pow'r to free.\nBlessèd Jesus, blessèd Jesus!\nWe will early turn to Thee.\nBlessèd Jesus, blessèd Jesus!\nWe will early turn to Thee.\n\nVerse 4\nEarly let us seek Thy favor, early let us do Thy will;\nBlessèd Lord and only Savior, with Thy love our bosoms fill.\nBlessèd Jesus, blessèd Jesus!\nThou hast loved us, love us still.\nBlessèd Jesus, blessèd Jesus!\nThou hast loved us, love us still.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-savior-of-the-nations-come","title":"Savior Of The Nations Come","language":"en","writers":"Ambrose of Milan, c. 397. Translated to German by Martin Luther, 1524. Translated from German to English by William M. Reynolds","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"NUN KOMM, DER HEIDEN HEILAND","themes":["Hymn"],"lyrics":"Verse 1\nSavior of the nations, come;\nVirgin's Son, here make Thy home!\nMarvel now, O heav'n and earth,\nThat the Lord chose such a birth.\n\nVerse 2\nNot by human flesh and blood;\nBy the Spirit of our God Was the Word of God made flesh,\nWoman's offspring, pure and fresh.\n\nVerse 3\nWondrous birth! O wondrous Child Of the virgin undefiled!\nThough by all the world disowned,\nStill to be in heaven enthroned.\n\nVerse 4\nFrom the Father forth He came And returneth to the same,\nCaptive leading death and hell High the song of triumph swell!\n\nVerse 5\nThou, the Father's only Son,\nHast o'er sin the vict'ry won.\nBoundless shall Thy kingdom be;\nWhen shall we its glories see?\n\nVerse 6\nBrightly doth Thy manger shine,\nGlorious is its light divine.\nLet not sin o'ercloud this light;\nEver be our faith thus bright.\n\nVerse 7\nPraise to God the Father sing,\nPraise to God the Son, our King,\nPraise to God the Spirit be\nEver and eternally.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-savior-when-in-dust-to-thee","title":"Savior When In Dust To Thee","language":"en","writers":"Robert Grant, 1815, alt","music":"Joseph Parry","year":1815,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ABERYSTWYTH (PARRY)","themes":["Hymn"],"lyrics":"Verse 1\nSavior, when in dust to Thee Low we bow th'adoring knee,\nWhen, repentant, to the skies Scarce we lift our weeping eyes,\nO by all the pains and woes Suffered once for man below,\nBending from Thy throne on high,\nHear our penitential cry!\n\nVerse 2\nBy Thy helpless infant years,\nBy Thy life of want and tears,\nBy Thy days of sore distress In the savage wilderness,\nBy the dread mysterious hour Of th'insulting tempter's pow'r,\nTurn, O turn a fav'ring eye,\nHear our penitential cry!\n\nVerse 3\nBy the sacred griefs that wept O'er the grave where Laz'rus slept,\nBy the boding tears that flowed Over Salem's loved abode,\nBy the anguished sigh that told Treachery lurked within Thy fold,\nFrom Thy seat above the sky,\nHear our penitential cry!\n\nVerse 4\nBy Thine hour of dire despair,\nBy Thine agony of prayer,\nBy the cross, the nail, the thorn,\nPiercing spear, and torturing scorn,\nBy the gloom that veiled the skies O'er the dreadful sacrifice,\nListen to our humble cry,\nHear our penitential cry!\n\nVerse 5\nBy Thy deep expiring groan,\nBy the sad sepulchral stone,\nBy the vault whose dark abode Held in vain the rising God,\nO from earth to heaven restored,\nMighty, reascended Lord, Listen,\nlisten to the sigh Of our penitential cry!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-savior-who-thy-flock-art-feeding","title":"Savior, Who Thy Flock Art Feeding","language":"en","writers":"William Augustus Mühlenberg","music":"from Johann Thommen's Musicalischer Christenschatz, Basel","year":1826,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"BATTY","themes":["Hymn"],"lyrics":"Verse 1\nSavior, who Thy flock art feeding With the Shepherd's kindest care,\nAll the feeble gently leading,\nWhile the lambs Thy bosom share.\n\nVerse 2\nNow, these little ones receiving,\nFold them in Thy gracious arm;\nThere, we know, Thy Word believing,\nOnly there secure from harm.\n\nVerse 3\nNever, from Thy pasture roving,\nLet them be the lion's prey;\nLet Thy tenderness, so loving,\nKeep them through life's dang'rous way.\n\nVerse 4\nThen within Thy fold eternal Let them find a resting place,\nFeed in pastures ever vernal,\nDrink the rivers of Thy grace.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-see-amid-the-winter-s-snow","title":"See Amid the Winter's Snow","language":"en","writers":"Edward Caswall","music":"John Goss","year":1851,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"HUMILITY","themes":["Hymn"],"lyrics":"Verse 1\nSee amid the winter's snow,\nBorn for us on earth below,\nSee, the gentle Lamb appears,\nPromised from eternal years.\n\nChorus\nHail that ever blessèd morn,\nHail redemption's happy dawn,\nSing through all Jerusalem:\nChrist is born in Bethlehem.\n\nVerse 2\nLo, within a manger lies He Who built the starry skies;\nHe Who, thronèd in height sublime,\nSits amid the cherubim.\n\nVerse 3\nSay, you holy shepherds, say,\nTell your joyful news today.\nWhy have you now left your sheep On the lonely mountain steep?\n\nVerse 4\n\"As we watched at dead of night,\nLo, we saw a wondrous light;\nAngels singing 'Peace on earth' Told us of the Savior's birth.\"\n\nVerse 5\nSacred Infant, all divine,\nWhat a tender love was Thine,\nThus to come from highest bliss Down to such a world as this.\n\nVerse 6\nTeach, O teach us, holy Child,\nBy Thy face so meek and mild,\nTeach us to resemble Thee,\nIn Thy sweet humility.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-see-the-lord-ascends-in-triumph","title":"See, The Lord Ascends In Triumph","language":"en","writers":"Christopher Wordsworth, 1862, alt","music":"Henry Thomas Smart","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"REX GLORIAE","themes":["Hymn"],"lyrics":"Verse 1\nSee, the Lord ascends in triumph; see the King in royal state,\nRiding on the clouds,\nHis chariot, To His heav'nly palace gate.\nHark! the choirs of angel voices Joyful alleluias sing,\nAnd the portals high are lifted To receive their heav'nly King.\nHoly Ghost, Illuminator, shed Thy beams upon our eyes,\nHelp us to look up with Stephen, and to see beyond the skies,\nWhere the Son of Man in glory Standing is at God's right hand,\nBeck'ning on His martyr army, succoring His faithful band.\n\nVerse 2\nWho is this that comes in glory, with the trump of jubilee?\nLord of battles, God of armies,\nHe has gained the victory.\nHe Who on the cross did suffer,\nHe who from the grave arose,\nHe has vanquished sin and Satan,\nHe by death has spoiled His foes.\nSee Him, Who is gone before us,\nHeav'nly mansions to prepare,\nSee Him, who is ever pleading For us with prevailing prayer,\nSee Him, who with sound of trumpet, and with His angelic train,\nSummoning the world to judgment, on the clouds will come again.\n\nVerse 3\nWhile He lifts His hands in blessing,\nHe is parted from His friends While their eager eyes behold Him,\nHe upon the cloud ascends;\nHe Who walked with God and pleased Him,\npreaching truth and doom to come,\nHe, our Enoch, is translated to His everlasting home.\nRaise us up from earth to Heaven, give us wings of faith and love,\nGales of holy aspirations wafting us to realms above;\nThat, with hearts and minds uplifted,\nwe with Christ our Lord may dwell,\nWhere He sits enthroned in glory in His heav'nly Citadel.\n\nVerse 4\nNow our heav'nly Aaron enters, with His blood, within the veil;\nJoshua now is come to Canaan, and the kings before Him quail;\nNow He plants the tribes of Israel in their promised resting place;\nNow our great Elijah offers double portion of His grace.\nSo at last, when He appeareth, we from out our graves may spring,\nWith our youth renewed like eagles, flocking round our Heav'nly King.\nCaught up on the clouds of Heaven, and may meet Him in the air,\nRise to realms where He is reigning, and may reign for ever there.\n\nVerse 5\nHe has raised our human nature in the clouds to God's right hand;\nThere we sit in heav'nly places, there with Him in glory stand:\nJesus reigns, adored by angels; man with God is on the throne;\nMighty Lord, in Thine ascension we by faith behold our own.\nGlory be to God the Father,\nGlory be to God the Son,\nDying, ris'n, ascending for us, who the heav'nly realm has won;\nGlory to the Holy Spirit,\nTo One God in Persons Three;\nGlory both in earth and Heaven, glory, endless glory, be.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-silent-night","title":"Silent Night","language":"en","writers":"Josef Mohr, 1818. stanzas 1,3 Translated by John Freeman Young, 1863. stanzas 2,4 translator anonymous","music":"Franz Xaver Gruber","year":1818,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"STILLE NACHT","themes":["Hymn","Christmas","Evening"],"lyrics":"Verse 1\nSilent night, holy night,\nAll is calm, all is bright Round yon virgin mother and Child.\nHoly Infant, so tender and mild,\nSleep in heavenly peace,\nSleep in heavenly peace.\n\nVerse 2\nSilent night, holy night,\nShepherds quake at the sight;\nGlories stream from heaven afar,\nHeavenly hosts sing Alleluia!\nChrist the Savior is born,\nChrist the Savior is born!\n\nVerse 3\nSilent night, holy night,\nSon of God, love's pure light;\nRadiant beams from Thy holy face With the dawn of redeeming grace,\nJesus, Lord, at Thy birth,\nJesus, Lord, at Thy birth.\n\nVerse 4\nSilent night, holy night Wondrous star, lend thy light;\nWith the angels let us sing,\nAlleluia to our King;\nChrist the Savior is born,\nChrist the Savior is born!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-sing-o-sing-this-blessed-morn","title":"Sing, O Sing, This Blessed Morn","language":"en","writers":"Christopher Wordsworth","music":"William Henry Monk","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"NATIVITY","themes":["Hymn"],"lyrics":"Verse 1\nSing, O sing, this blessed morn,\nUnto us a Child is born,\nUnto us a Son is giv'n,\nGod Himself comes down from Heav'n.\n\nChorus\nSing, O sing, this blessed morn,\nJesus Christ today is born.\n\nVerse 2\nJesus Christ, the King of kings,\nMaker of all worldly things,\nNow descends from Heav'n to Earth,\nTo restore us by His birth;\n\nVerse 3\nGod of God, and Light of Light,\nComes with mercies infinite;\nJoining in a wondrous plan Heav'n to earth and God to Man;\n\nVerse 4\nGod with us, Emmanuel,\nDeigns for ever now to dwell;\nHe on Adam's fallen race Sheds the fullness of His Grace;\n\nVerse 5\nTruth and Mercy show their face,\nAnd with loving kiss embrace;\nRighteousness looks down from Heav'n,\nGod is pleased and Man forgiv'n;\n\nVerse 6\nGod comes down that man may rise, Lifted far above the skies\nHe is Son of Man, that we Sons of God in Him may be;\n\nVerse 7\nHuman flesh is now become Christ's abode, the Godhead's home;\nRoyal Palace, sacred shrine For the Majesty Divine;\n\nVerse 8\nNow we rise, from prison free; On we march to victory,\nJoyful banners are unfurled; 'Tis the Birthday of the World;\n\nVerse 9\nNow behold the rising Sun Hath His glorious race begun;\nNow the Bridegroom from above Weds the Bride, with heavenly love;\n\nVerse 10\nO renew us, Lord, we pray, With Thy Spirit day by day;\nThat we ever one may be With the Father, and with Thee;\n\nVerse 11\nSing, O sing this blessed Morn, Jesus Christ to-day is born;\nGlory to the Father give, Praise the Son in whom we live;\nGlory to the Spirit be, Godhead One, and Persons Three.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus","Verse 6","Chorus","Verse 7","Chorus","Verse 8","Chorus","Verse 9","Chorus","Verse 10","Chorus","Verse 11","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-songs-of-thankfulness-and-praise","title":"Songs of Thankfulness and Praise","language":"en","writers":"Christopher Wordsworth","music":"s Windsor', George Job Elvey","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. GEORGE","themes":["Hymn"],"lyrics":"Verse 1\nSongs of thankfulness and praise,\nJesus, Lord, to Thee we raise,\nManifested by the star To the sages from afar;\nBranch of royal David's stem In Thy birth at Bethlehem;\nAnthems be to Thee addressed,\nGod in man made manifest.\n\nVerse 2\nManifest at Jordan's stream,\nProphet, Priest, and King supreme;\nAnd at Cana, wedding guest,\nIn Thy Godhead manifest;\nManifest in pow'r divine,\nChanging water into wine;\nAnthems be to Thee addressed,\nGod in man made manifest.\n\nVerse 3\nManifest in making whole Palsied limbs and fainting soul;\nManifest in valiant fight,\nQuelling all the devil's might;\nManifest in gracious will,\nEver bringing good from ill;\nAnthems be to Thee addressed,\nGod in man made manifest.\n\nVerse 4\nSun and moon shall darkened be,\nStars shall fall, the heav'ns shall flee,\nChrist will then like lightning shine,\nAll will see His glorious sign:\nAll will then the trumpet hear;\nAll will see the Judge appear;\nThou by all wilt be confessed,\nGod in man made manifest.\n\nVerse 5\nGrant us grace to see Thee,\nLord, Mirrored in Thy holy Word;\nMay we imitate Thee now,\nAnd be pure, as pure art Thou;\nThat we like to Thee may be At Thy great Epiphany;\nAnd may praise Thee, ever blest,\nGod in man made manifest.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-souls-of-men-why-will-ye-scatter","title":"Souls of Men! Why Will Ye Scatter","language":"en","writers":"Frederick William Faber, 1862, alt","music":"traditional Dutch found in \"Oude en Nieuwe Hollantse Boerenlities en Contradansen\"","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"IN BABILONE","themes":["Hymn"],"lyrics":"Verse 1\nSouls of men! why will ye scatter Like a crowd of frightened sheep?\nFoolish hearts! why will ye wander From a love so true and deep?\nWas there ever kinder shepherd Half so gentle, half so sweet,\nAs the Savior who would have us Come and gather round His feet?\n\nVerse 2\nIt is God: His love looks mighty,\nBut is mighti'r than it seems;\n'Tis our Father: and His fondness Goes far out beyond our dreams.\nThere's a wideness in God's mercy,\nLike the wideness of the sea;\nThere's a kindness in His justice,\nWhich is more than liberty.\n\nVerse 3\nThere is no place where earth's sorrows\nAre more felt than up in Heav'n;\nThere is no place where earth's failings\nHave such wondrous judgment giv'n.\nThere is welcome for the sinner,\nGrace poured out as in a flood There is mercy with the Savior;\nThere is healing in His blood.\n\nVerse 4\nThere is grace enough for thousands Of new worlds as great as this;\nThere is room for fresh creations In that upper home of bliss.\nFor the love of God is broader Than the measure of man's mind;\nAnd the heart of the Eternal Is most wonderfully kind.\n\nVerse 5\nThere is plentiful redemption In Christ's blood that has been shed;\nThere is joy for all the members In the sorrows of the Head.\nNot just all we owe to Jesus;\nIt is something more than all;\nGreater good because of evil,\nLarger mercy through the fall.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-stricken-smitten-and-afflicted","title":"Stricken, Smitten, and Afflicted","language":"en","writers":"Thomas Kelly","music":"from Geistliches Volkslied","year":1804,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"O MEIN JESU, ICH MUSS STERBEN","themes":["Hymn"],"lyrics":"Verse 1\nStricken, smitten, and afflicted,\nSee Him dying on the tree!\n'Tis the Christ by man rejected;\nYes, my soul, 'tis He,\n'tis He! 'Tis the long expected prophet,\nDavid's Son, yet David's Lord;\nProofs I see sufficient of it:\n'Tis a true and faithful Word.\n\nVerse 2\nTell me, ye who hear Him groaning,\nWas there ever grief like His?\nFriends through fear His cause disowning,\nFoes insulting his distress:\nMany hands were raised to wound Him,\nNone would interpose to save;\nBut the deepest stroke that pierced\nHim Was the stroke that Justice gave.\n\nVerse 3\nYe who think of sin but lightly,\nNor suppose the evil great,\nHere may view its nature rightly,\nHere its guilt may estimate.\nMark the Sacrifice appointed!\nSee Who bears the awful load!\n'Tis the Word, the Lord's Anointed,\nSon of Man, and Son of God.\n\nVerse 4\nHere we have a firm foundation,\nHere the refuge of the lost.\nChrist the Rock of our salvation,\nChrist the Name of which we boast.\nLamb of God for sinners wounded!\nSacrifice to cancel guilt!\nNone shall ever be confounded Who on Him their hope have built.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-take-my-life-and-let-it-be","title":"Take My Life And Let It Be","language":"en","writers":"Frances R. Havergal","music":"Wolfgang Amadeus Mozart (1756-1791)","year":1874,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"MOZART","themes":["Hymn"],"lyrics":"Verse 1\nTake my life, and let it be consecrated,\nLord, to Thee. Take my moments and my days;\nlet them flow in ceaseless praise.\n\nVerse 2\nTake my hands, and let them move at the impulse of Thy love.\nTake my feet, and let them be swift and beautiful for Thee.\n\nVerse 3\nTake my voice, and let me sing always, only, for my King.\nTake my lips, and let them be filled with messages from Thee.\n\nVerse 4\nTake my silver and my gold; not a mite would I withhold.\nTake my intellect, and use every pow'r as Thou shalt choose.\n\nVerse 5\nTake my will, and make it Thine; it shall be no longer mine.\nTake my heart, it is Thine own; it shall be Thy royal throne.\n\nVerse 6\nTake my love, my Lord, I pour at Thy feet its treasure store.\nTake myself, and I will be ever, only, all for Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-take-thou-my-hand-and-lead-me","title":"Take Thou My Hand and Lead Me","language":"en","writers":"Julie Katharina von Hausmann, 1862. Translated by Rev. Julius Herman Edward Horstmann (1869-1954), before","music":"Friedrich Silcher","year":1862,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"SO NIMM DENN MEINE HÄNDE","themes":["Hymn"],"lyrics":"Verse 1\nTake Thou my hand, and lead me o'er life's rough way,\nwith Heav'nly Manna feed me from day to day.\nAlone my footsteps falter and straggle wide,\nLord who my life canst alter be Thou my guide.\n\nVerse 2\nTake Thou my heart and hide it in folds of grace\nThough pain or woe betide it to know Thy face Draw,\nLord, of Thy good pleasure Thy child to Thee,\nAnd grant me faith's full measure though naught I see.\n\nVerse 3\nThough oft I think Thou hidest Thy wondrous might,\nStill to my goal Thou guidest me through dark night,\nTake, then, my hands and lead me till life is o'er,\nWith heav'nly manna feed me forevermore.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-take-up-thy-cross-the-savior-said","title":"'Take Up Thy Cross', the Savior Said","language":"en","writers":"Charles W. Everest","music":"George Rhau","year":1833,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"NUN LASST UNS DEN LEIB BEGRABEN","themes":["Hymn","Lent"],"lyrics":"Verse 1\n\"Take up thy cross,\" the Savior said,\n\"If thou wouldst My disciple be;\nDeny thyself, the world forsake,\nAnd humbly follow after Me.\"\n\nVerse 2\nTake up thy cross, let not its weight Fill thy weak spirit with alarm;\nHis strength shall bear thy spirit up,\nAnd brace thy heart and nerve thine arm.\n\nVerse 3\nTake up thy cross, nor heed the shame,\nNor let thy foolish pride rebel;\nThy Lord for thee the cross endured,\nAnd saved thy soul from death and hell.\n\nVerse 4\nTake up thy cross then in His strength,\nAnd calmly sin's wild deluge brave,\n'Twill guide thee to a better home,\nIt points to glory o'er the grave.\n\nVerse 5\nTake up thy cross and follow Christ,\nNor think til death to lay it down;\nFor only those who bear the cross May hope to wear the glorious crown.\n\nVerse 6\nTo Thee, great Lord, the One in Three,\nAll praise forevermore ascend:\nO grant us in our home to see\nThe heavenly life that knows no end.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-that-men-a-godly-life-might-live","title":"That Men a godly Life Might Live","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"gen zehu GebotIn Gottes Namen fahren wir' circa 1200s found in Erfurt Enchiridion","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"DIES SIND DIE HEIL","themes":["Hymn"],"lyrics":"Verse 1\nThat man a godly life might live,\nGod did these ten commandments give By His true servant Moses,\nhigh Upon the mount Sinai. Have mercy, Lord.\n\nVerse 2\nI am thy God and Lord alone,\nNo other God besides Me own;\nOn My great mercy venture thee,\nWith all thy heart love thou Me.\n\nVerse 3\nBy idle word and speech profane Take not My holy Name in vain;\nAnd praise not aught as good and true But what God doth say and do.\n\nVerse 4\nHallow the day which God hath blest,\nThat thou and all thy house may rest;\nKeep hand and heart from labor free,\nThat God may so work in thee.\n\nVerse 5\nGive to thy parents honor due,\nBe dutiful and loving too;\nAnd help them when their strength decays\nSo shalt thou have length of days.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-advent-of-our-god","title":"The Advent of Our God","language":"en","writers":"Charles Coffin, 1736. translated by John Chandler, 1837, alt","music":"Aaron Williams","year":1736,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ST. THOMAS","themes":["Hymn","Advent"],"lyrics":"Verse 1\nThe advent of our God Shall be our theme for prayer Come,\nlet us meet him on the road And place for Him prepare.\n\nVerse 2\nThe everlasting Son Incarnate stoops to be,\nHimself the servant's form puts on To set His people free.\n\nVerse 3\nCome, Zion's daughter, rise To meet your lowly King,\nNor let your faithless heart despise The peace He comes to bring.\n\nVerse 4\nAs judge, on clouds of light,\nHe soon will come again And all\nHis scattered saints unite With Him on high to reign.\n\nVerse 5\nBefore the dawning day Let sin be put to flight;\nNo longer let the law hold sway,\nBut walk in freedom's light.\n\nVerse 6\nAll glory to the Son\nWho comes to set us free,\nWith Father, Spirit, ever One,\nThrough all eternity.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-the-bridegroom-soon-will-call-us","title":"The Bridegroom Soon Will Call Us","language":"en","writers":"Johann Walther, 1552. Translated by Matthias Loy","music":"from Musae Sionae XII (or VII), Michael Praetorius","year":1552,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ACT GOTT VOM HIMMELREICHE","themes":["Hymn"],"lyrics":"Verse 1\nThe Bridegroom soon will call us,\nCome, all ye wedding guests!\nMay not His voice appall us,\nWhile slumber binds our breasts;\nMay all our lamps be burning,\nAnd oil be found in store,\nThat we, with Him returning,\nMay open find the door.\n\nVerse 2\nThere shall we see delighted Our dear Redeemer's face,\nWho leads our souls benighted To glory by His grace;\nThe patriarchs shall meet us,\nThe prophets' holy band,\nApostles, martyrs, greet us In that celestial land.\n\nVerse 3\nThey will not blush to own us As brothers, sisters dear,\nLove ever will be shown us When we with them appear;\nWe all shall come before Him,\nWho for us Man became,\nAs Lord and God adore Him,\nAnd ever bless His Name.\n\nVerse 4\nOur Father, rich in blessing,\nWill give us crowns of gold And, to His bosom pressing,\nImpart a bliss untold,\nWill welcome with embraces Of never ending love,\nAnd deck us with His graces In blissful realms above.\n\nVerse 5\nIn yonder home shall never Be silent music's voice;\nWith hearts and lips forever We shall in God rejoice;\nThe angels shall adore Him,\nAll saints shall sing His praise,\nAnd bring with joy before Him Their sweetest heav'nly lays.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-church-s-one-foundation","title":"The Church's One Foundation","language":"en","writers":"Samuel John Stone","music":"Samuel Sebastian Wesley","year":1866,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"AURELIA","themes":["Hymn"],"lyrics":"Verse 1\nThe Church's one foundation Is Jesus Christ her Lord,\nShe is His new creation By water and the Word.\nFrom heav'n He came and sought her To be His holy bride;\nWith His own blood He bought her And for her life He died.\n\nVerse 2\nShe is from every nation,\nYet one o'er all the earth;\nHer charter of salvation,\nOne Lord, one faith, one birth;\nOne holy Name she blesses,\nPartakes one holy food,\nAnd to one hope she presses,\nWith every grace endued.\n\nVerse 3\nThe Church shall never perish!\nHer dear Lord to defend,\nTo guide, sustain, and cherish,\nIs with her to the end:\nThough there be those who hate her,\nAnd false sons in her pale,\nAgainst or foe or traitor She ever shall prevail.\n\nVerse 4\nThough with a scornful wonder Men see her sore oppressed,\nBy schisms rent asunder,\nBy heresies distressed: Yet saints their watch are keeping,\nTheir cry goes up,\n'How long?' And soon the night of weeping Shall be the morn of song!\n\nVerse 5\n'Mid toil and tribulation,\nAnd tumult of her war,\nShe waits the consummation Of peace forevermore;\nTill, with the vision glorious,\nHer longing eyes are blest,\nAnd the great Church victorious Shall be the Church at rest.\n\nVerse 6\nYet she on earth hath union\nWith God the Three in One,\nAnd mystic sweet communion\nWith those whose rest is won,\nWith all her sons and daughters\nWho, by the Master's hand\nLed through the deathly waters,\nRepose in Eden land.\n\nVerse 7\nO happy ones and holy!\nLord, give us grace that we\nLike them, the meek and lowly,\nOn high may dwell with Thee:\nThere, past the border mountains,\nWhere in sweet vales the Bride\nWith Thee by living fountains\nForever shall abide!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-the-comforter-has-come","title":"The Comforter Has Come","language":"en","writers":"Frank Bottome","music":"William J. Kirkpatrick","year":1890,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"THE COMFORTER HAS COME","themes":["Hymn"],"lyrics":"Verse 1\nO spread the tidings 'round, wherever man is found,\nWherever human hearts and human woes abound;\nLet ev'ry Christian tongue proclaim the joyful sound:\nThe Comforter has come!\n\nChorus\nThe Comforter has come,\nThe Comforter has come!\nThe Holy Ghost from heav'n,\nThe Father's promise giv'n;\nO spread the tidings 'round,\nWherever man is found:\nThe Comforter has come!\n\nVerse 2\nThe long, long night is past, the morning breaks at last,\nAnd hush'd the dreadful wail and fury of the blast,\nAs o'er the golden hills the day advances fast!\nThe Comforter has come!\n\nVerse 3\nLo, the great King of kings, with healing in His wings,\nTo ev'ry captive soul a full deliv'rance brings;\nAnd thro' the vacant cells the song of triumph rings;\nThe Comforter has come!\n\nVerse 4\nO boundless love divine!\nhow shall this tongue of mine\nTo wond'ring mortals tell the matchless grace divine;\nThat I, a child of hell, should in His image shine!\nThe Comforter has come!\n\nVerse 5\nSing, till the echoes fly above the vaulted sky,\nAnd all the saints above to all below reply,\nIn strains of endless love the song that ne'er will die:\nThe Comforter has come!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-day-is-surely-drawing-near","title":"The Day is Surely Drawing Near","language":"en","writers":"Bartholomäus Ringwaldt, 1565. Translated by Phillip A. Peter, 1872, alt","music":"from Klug's Geistliche Lieder, Wittenberg","year":1565,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ES IST GEWISSLICH AN DER ZEIT","themes":["Hymn"],"lyrics":"Verse 1\nThe day is surely drawing near,\nWhen God's Son, the Anointed,\nShall with great majesty appear,\nAs Judge of all appointed.\nAll mirth and laughter then shall cease\nWhen flames on flames will still increase,\nAs Scripture truly teacheth.\n\nVerse 2\nA trumpet loud shall then resound,\nAnd all the earth be shaken;\nThen all who in their graves are found Shall from their sleep awaken.\nBut all that live shall in that hour,\nBy the Almighty's boundless pow'r Be changed at His commanding.\n\nVerse 3\nA book is opened then to all,\nA record truly telling What each hath done, both great and small,\nWhen he on earth was dwelling;\nAnd every heart be clearly seen,\nAnd all be known as they have been,\nIn thoughts and words and actions.\n\nVerse 4\nThen woe to those who scorned the Lord,\nAnd sought but carnal pleasures,\nWho here despised His precious Word,\nAnd loved their earthly treasures!\nWith shame and trembling they will stand,\nAnd at the Judge's stern command To Satan be delivered.\n\nVerse 5\nO Jesus, who my debt didst pay\nAnd for my sin wast smitten Within the Book of Life,\noh, may My name be also written!\nI will not doubt;\nI trust in Thee,\nFrom Satan Thou hast made me free And from all condemnation.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-first-noel","title":"The First Noel","language":"en","writers":"Traditional English carol, possibly dating from as early as the 13th Century","music":"Traditional English carol, possibly dating from as early as the 13th Century","year":1911,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"THE FIRST NOEL","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nThe first Noel the angel did say\nWas to certain poor shepherds in fields as they lay;\nIn fields where they lay tending their sheep,\nOn a cold winter's night that was so deep.\n\nChorus\nNoel, Noel, Noel, Noel,\nBorn is the King of Israel.\n\nVerse 2\nThey lookèd up and saw a star Shining in the east, beyond them far;\nAnd to the earth it gave great light,\nAnd so it continued both day and night.\n\nVerse 3\nAnd by the light of that same star\nThree Wise Men came from country far;\nTo seek for a King was their intent,\nAnd to follow the star wherever it went.\n\nVerse 4\nThis star drew nigh to the northwest,\nOver Bethlehem it took its rest;\nAnd there it did both stop and stay,\nRight over the place where Jesus lay.\n\nVerse 5\nThen did they know assuredly Within that house the King did lie;\nOne entered it them for to see,\nAnd found the Babe in poverty.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-galilean-fishers-toil","title":"The Galilean Fishers Toil","language":"en","writers":"Christopher Wordsworth, 1865, alt","music":"from Day's Psalter","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"OLD 137TH","themes":["Hymn"],"lyrics":"Verse 1\nThe Galilean fishers toil all night, and nothing take;\nBut Jesus comes,-a wondrous spoil is lifted from the lake.\nLord, when our labors are in vain and vain the help of men,\nWhen fruitless is our care and pain,\nCome blessed Jesus then!\n\nVerse 2\nThe night is dark, the surges fill the bark, the wild winds roar;\nBut Jesus comes and all is still,-the ship is at the shore.\nO Lord, when storms around us howl, and all is dark and drear,\nIn all the tempests of the soul,\nO blessed Jesus hear.\n\nVerse 3\nA frail one, thrice denying Thee saw mercy in Thine eyes,\nThe penitent upon the tree was borne to Paradise.\nIn hours of sin and deep distress o show us,\nLord, Thy Face, In penitential loneliness,\nO give us Jesus grace!\n\nVerse 4\nThe faithful few retire in fear to their closed upper room;\nBut suddenly with joyful cheer they see their Master come.\nLord come to us, unloose our bands and bid our terrors cease,\nLift over us Thy blessed hands,\nSpeak, holy Jesus Peace!\n\nVerse 5\nIn days, when faith will scarce be found, and wolves be in the fold,\nWhen sin and sorrow will abound and charity wax cold,\nThen hear Thy saints, who to Thee pray to bring them to their home,\nHear when the Bride and Spirit say,\n\"Come, Blessed Jesus, Come!\"","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-god-of-abraham-praise","title":"The God of Abraham Praise","language":"en","writers":"Daniel ben Judah, circa 1400. Paraphrased by Thomas Olivers","music":"Traditional Hebrew","year":1400,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"YIGDAL","themes":["Hymn"],"lyrics":"Verse 1\nThe God of Abr'ham praise,\nWho reigns enthroned above;\nAncient of everlasting days, and God of Love;\nJehovah, great I AM! by earth and Heav'n confessed;\nI bow and bless the sacred Name forever blessed.\n\nVerse 2\nThe God of Abr'ham praise,\nat Whose supreme command\nFrom earth I rise and seek the joys at His right hand;\nI all on earth forsake, its wisdom, fame, and pow'r;\nAnd Him my only Portion make, my Shield and Tow'r.\n\nVerse 3\nThe God of Abr'ham praise,\nWhose all sufficient grace Shall guide me all my happy days,\nin all my ways.\nHe calls a worm His friend,\nHe calls Himself my God!\nAnd He shall save me to the end, thro' Jesus' blood.\n\nVerse 4\nHe by Himself has sworn;\nI on His oath depend,\nI shall, on eagle wings upborne, to Heav'n ascend.\nI shall behold His face;\nI shall His pow'r adore,\nAnd sing the wonders of His grace forevermore.\n\nVerse 5\nTho' nature's strength decay, and earth and hell withstand,\nTo Canaan's bounds I urge my way, at His command.\nThe wat'ry deep I pass, with Jesus in my view;\nAnd thro' the howling wilderness my way pursue.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-gospel-shows-the-father-s-grace","title":"The Gospel Shows The Father's Grace","language":"en","writers":"Matthias Loy","music":"from Cantionale Germanicum, Dresden","year":1863,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"HERR JESU CHRIST, DICT ZU UNS WEND","themes":["Hymn"],"lyrics":"Verse 1\nThe Gospel shows the Father's grace,\nWho sent his Son to save our race,\nProclaims how Jesus lived and died That man might thus be justified.\n\nVerse 2\nIt sets the Lamb before our eyes,\nWho made th'atoning sacrifice,\nAnd calls the souls with guilt oppressed\nTo come and find eternal rest.\n\nVerse 3\nIt brings the Savior's righteousness Our souls to robe in royal dress;\nFrom all our guilt it brings release\nAnd gives the troubled conscience peace.\n\nVerse 4\nIt is the pow'r of God to save From sin and Satan and the grave;\nIt works the faith,\nwhich firmly clings To all the treasures which it brings.\n\nVerse 5\nIt bears to all the tidings glad And bids their hearts no more be sad;\nThe heavy laden souls it cheers And banishes their guilty fears.\n\nVerse 6\nMay we in faith its tidings learn\nNor thanklessly its blessings spurn;\nMay we in faith its truth confess\nAnd praise the Lord our Righteousness!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-the-king-shall-come","title":"The King Shall Come","language":"en","writers":"Unknown author. Translated by John Brownlie","music":"John Wyeth","year":1907,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"CONSOLATION","themes":["Hymn"],"lyrics":"Verse 1\nThe King shall come when morning dawns,\nAnd light triumphant breaks;\nWhen beauty gilds the eastern hills,\nAnd life to joy awakes.\n\nVerse 2\nNot as of old a little child To bear, and fight, and die,\nBut crowned with glory like the sun That lights the morning sky.\n\nVerse 3\nO brighter than the rising morn When He, victorious, rose,\nAnd left the lonesome place of death,\nDespite the rage of foes.\n\nVerse 4\nO brighter than that glorious morn Shall this fair morning be,\nWhen Christ, our King, in beauty comes,\nAnd we His face shall see.\n\nVerse 5\nThe King shall come when morning dawns,\nAnd earth's dark night is past;\nO haste the rising of that morn,\nThe day that aye shall last.\n\nVerse 6\nAnd let the endless bliss begin,\nBy weary saints foretold,\nWhen right shall triumph over wrong,\nAnd truth shall be extolled.\n\nVerse 7\nThe King shall come when morning dawns,\nAnd light and beauty brings:\nHail, Christ the Lord! Thy people pray,\nCome quickly, King of kings.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-the-lily-of-the-valley","title":"The Lily of the Valley","language":"en","writers":"C. W. Fry, 1881, alt","music":"William S. Hays","year":1881,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"SALVATION","themes":["Hymn"],"lyrics":"Verse 1\nI've found a friend in Jesus,\nHe's everything to me,\nHe's the fairest of ten thousand to my soul;\nThe Lily of the Valley,\nin Him alone I see All I need to cleanse and make me fully whole.\nIn sorrow He's my comfort, in trouble He's my stay;\nHe tells me every care on Him to roll. He's the Lily\n\nChorus\nof the Valley, the Bright and Morning Star,\nHe's the fairest of ten thousand to my soul.\n\nVerse 2\nHe all my grief has taken, and all my sorrows borne;\nIn temptation He's my strong and mighty tow'r;\nI'll all for Him forsake now,\nI'll all my idols tear From my heart for now He keeps me by His pow'r.\nThough all the world forsake me, and Satan tempt me sore,\nThrough Jesus I shall safely reach the goal. He's the Lily\n\nVerse 3\nHe'll never, never leave me, nor yet forsake me here,\nSo I live by faith and do His blessed will;\nA wall of fire about me,\nI've nothing now to fear,\nWith His manna He my hungry soul shall fill.\nWhen crown'd at last in glory,\nI'll see His blessed face,\nWhere rivers of delight shall ever roll. He's the Lily","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-lord-s-my-shepherd","title":"The Lord's My Shepherd","language":"en","writers":"Psalm 23 from the Scottish Psalter, 1650 alt. by James Leith Macbeth Bain","music":"Air' James Leith Macbeth Bain, 1915, alt","year":1650,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"MAROSA","themes":["Hymn"],"lyrics":"Verse 1\nThe Lord's my shepherd I'll not want,\nHe makes me down to lie In pastures green\nHe leadeth me The quiet waters by.\nHe leadeth me, He leadeth me,\nThe quiet waters by,\nIn pastures green He leadeth me The quiet waters by.\n\nVerse 2\nMy soul He doth restore again,\nAnd me to walk doth make.\nWithin the paths of blessedness,\nE'en for His Own Name's sake;\nHis Own Name's sake,\nHis Own Name's sake,\nE'en for His Own Name's sake;\nWithin the paths of blessedness,\nE'en for His Own Name's sake.\n\nVerse 3\nYea, though I walk in death's dark vale,\nYet will I fear no ill,\nFor Thou art with me, and Thy rod And staff me comfort still;\nI'll fear no ill,\nI'll fear no ill,\nYet will I fear no ill,\nFor Thou art with me, and Thy rod And staff me comfort still.\n\nVerse 4\nMy table Thou hast furnished well In presence of my foes;\nMy head Thou dost with oil anoint,\nAnd my cup overflows;\nIt overflows, It overflows,\nAnd my cup overflows;\nMy head Thou dost with oil anoint,\nAnd my cup overflows.\n\nVerse 5\nGoodness and mercy all my days Will surely follow me:\nAnd in my Father's heart always My dwelling place shall be;\nMy dwelling place, My dwelling place,\nMy dwelling place shall be,\nAnd in my Father's heart always My dwelling place shall be.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-love-of-god","title":"The Love of God","language":"en","writers":"Frederick Martin Lehman","music":"Frederick Martin Lehman","year":1917,"rights":"public-domain","copyright":"Public domain","defaultKey":"Db","bpm":null,"tune":"THE LOVE OF GOD","themes":["Hymn"],"lyrics":"Verse 1\nThe love of God is greater far Than tongue or pen can ever tell,\nIt goes beyond the highest star,\nAnd reaches to the lowest hell;\nThe guilty pair, bowed down with care,\nGod gave His Son to win;\nHis erring child, He reconciled,\nAnd pardoned from his sin.\n\nChorus\nOh love of God, how rich and pure!\nHow measureless and strong!\nIt shall forevermore endure,\nThe saints' and angels' song.\n\nVerse 2\nWhen hoary time shall pass away,\nAnd earthly thrones and kingdoms fall;\nWhen men who here refuse to pray,\nOn rocks and hills and mountains call;\nGod's love, so sure, shall still endure,\nAll measureless and strong;\nRedeeming grace to Adam's race — The saints' and angels' song.\n\nVerse 3\nCould we with ink the ocean fill,\nAnd were the skies of parchment made,\nWere every stalk on earth a quill And every man a scribe by trade;\nTo write the love of God above Would drain the ocean dry;\nNor could the scroll contain the whole,\nTho' stretched from sky to sky.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-mouth-of-fools-doth-god-confess","title":"The Mouth of Fools Doth God Confess","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"from Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ES SPRICHT DER UNWEISEN MUND","themes":["Hymn"],"lyrics":"Verse 1\nThe mouth of fools doth God confess,\nBut while their lips draw nigh Him,\nTheir heart is full of wickedness,\nAnd all their deeds deny Him.\nCorrupt are they, and every one Abominable works hath done;\nThere is not one welldoer.\n\nVerse 2\nThe Lord looked down from his high tow'r On all mankind below Him,\nTo see if any owned His pow'r,\nAnd truly sought to know Him;\nWho all their understanding bent To search His holy Word,\nintent To do his will in earnest.\n\nVerse 3\nBut none there was who walked with God,\nFor all aside had slidden,\nDelusive paths of folly trod,\nAnd followed lusts forbidden;\nNot one there was who practiced good,\nAnd yet they deemed, in haughty mood,\nTheir deeds must surely please Him.\n\nVerse 4\nHow long, by folly blindly led,\nWill ye oppress the needy,\nAnd eat my people up like bread?\nSo fierce are ye, and greedy!\nIn God they put no trust at all,\nNor will on Him in trouble call,\nBut be their own providers.\n\nVerse 5\nTherefore their heart is never still,\nA falling leaf dismays them;\nGod is with him who doth His will,\nWho trusts him and obeys Him;\nBut ye the poor man's hope despise,\nAnd laugh at him, e'en when he cries,\nThat God is his sure comfort.\n\nVerse 6\nWho shall to Israel's outcast race From Zion bring salvation?\nGod will himself at length show grace, And loose the captive nation;\nThat will he do by Christ their King; Let Jacob then be\nglad and sing, And Israel be joyful.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-the-old-rugged-cross","title":"The Old Rugged Cross","language":"en","writers":"George Bennard","music":"George Bennard","year":1913,"rights":"public-domain","copyright":"Public domain","defaultKey":"Bb","bpm":null,"tune":"THE OLD RUGGED CROSS","themes":["Hymn","Lent"],"lyrics":"Verse 1\nOn a hill far away stood an old rugged cross,\nThe emblem of suff'ring and shame;\nAnd I love that old cross where the dearest and best\nFor a world of lost sinners was slain. So I'll\n\nChorus\ncherish the old rugged cross,\nTill my trophies at last I lay down;\nI will cling to the old rugged cross,\nAnd exchange it some day for a crown.\n\nVerse 2\nO that old rugged cross, so despised by the world,\nHas a wondrous attraction for me;\nFor the dear Lamb of God left\nHis glory above To bear it to dark Calvary.\n\nVerse 3\nIn that old rugged cross, stained with blood so divine,\nA wondrous beauty I see,\nFor 'twas on that old cross Jesus suffered and died,\nTo pardon and sanctify me.\n\nVerse 4\nTo the old rugged cross I will ever be true;\nIts shame and reproach gladly bear;\nThen He'll call me some day to my home far away,\nWhere His glory forever I'll share.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-people-that-in-darkness-sat","title":"The People That in Darkness Sat","language":"en","writers":"John Morison","music":"Nikolaus Hermann","year":1781,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"LOBT GOTT, IHR CHRISTEN ALLZUGLEICH","themes":["Hymn"],"lyrics":"Verse 1\nThe people that in darkness sat A glorious light have seen;\nThe light has shined on them who long In shades of death have been.\nIn shades of death have been.\n\nVerse 2\nTo hail Thee, Sun of Righteousness,\nThe gath'ring nations come;\nThey joy as when the reapers bear Their harvest treasures home.\nTheir harvest treasures home.\n\nVerse 3\nFor Thou their burden dost remove And break the tyrant's rod\nAs in the day when Midian fell Before the sword of God.\nBefore the sword of God.\n\nVerse 4\nTo us a Child of hope is born,\nTo us a Son is giv'n,\nAnd on His shoulder ever rests All pow'r in earth and heav'n.\nAll pow'r in earth and heav'n.\n\nVerse 5\nHis name shall be the Prince of Peace,\nThe Everlasting Lord, The Wonderful, the Counselor.\nThe God by all adored.\nThe God by all adored.\n\nVerse 6\nHis righteous government and power\nShall over all extend;\nOn judgment and on justice based,\nHis reign shall have no end.\n\nVerse 7\nLord Jesus, reign in us, we pray,\nAnd make us Thine alone,\nWho with the Father ever art\nAnd Holy Spirit, one.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-the-star-proclaims-the-king-is-here","title":"The Star Proclaims the King is Here","language":"en","writers":"Coelius Sedulius, c. 450. German version by M. Luther, 1543. English translation by John Mason Neale","music":"from Klug's Geistliche Lieder, Wittenberg","year":1543,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"WO GOTT ZUM HAUS","themes":["Hymn"],"lyrics":"Verse 1\nThe star proclaims the King is here;\nBut, Herod, why this senseless fear?\nHe takes no realms of earth away Who gives the realms of heav'nly day.\n\nVerse 2\nThe wiser Magi see from far And follow on His guiding star;\nAnd led by light,\nto light they press And by their gifts their God confess.\n\nVerse 3\nWithin the Jordan's crystal flood\nIn meekness stands the Lamb of God And,\nsinless, sanctifies the wave,\nMankind from sin to cleanse and save.\n\nVerse 4\nAt Cana first His pow'r is shown;\nHis might the blushing waters own And, changing as He speaks the word,\nFlow wine, obedient to their Lord.\n\nVerse 5\nAll glory, Jesus, be to Thee For this Thy glad epiphany;\nWhom with the Father we adore And Holy Ghost forevermore.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-the-strife-is-o-er-the-battle-done","title":"The Strife Is O'er, The Battle Done","language":"en","writers":"from Symphonia Sirenum Selectarum, Köln, 1695; translated by Francis Pott","music":"Giovanni P. da Palestrina","year":1695,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"VICTORY","themes":["Hymn"],"lyrics":"Verse 1\nAlleluia, Alleluia, Alleluia. The strife is o'er, the battle done;\nThe triumph of the Lord is won;\nO Let the song of praise be sung: Alleluia!\n\nChorus\nAlleluia, Alleluia, Alleluia.\n\nVerse 2\nAlleluia, Alleluia, Alleluia.\nThe pow'rs of death have done their worst;\nand Jesus hath His foes dispersed;\nLet shouts of praise and joy outburst: Alleluia!\n\nVerse 3\nAlleluia, Alleluia, Alleluia. On that third morn\nHe rose again In glorious majesty to reign;\nO let us swell the joyful strain. Alleluia!\n\nVerse 4\nAlleluia, Alleluia, Alleluia. He closed the yawning gates of hell;\nThe bars from heav'ns high portals fell;\nLet songs of joy His triumphs tell. Alleluia!\n\nVerse 5\nAlleluia, Alleluia, Alleluia. Lord, by the stripes which wounded Thee,\nFrom death's dread sting Thy servants free,\nThat we may live, and sing to Thee. Alleluia!","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus","Verse 5","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-the-winds-and-billows-loudly-roar","title":"The Winds and Billows Loudly Roar","language":"en","writers":"Christopher Wordsworth","music":"John Wyeth","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"CONSOLATION","themes":["Hymn"],"lyrics":"Verse 1\nThe winds and billows loudly roar\nWe flounder in the deep Our bark is frail,\nfar off the shore,\nAnd Jesus is asleep.\n\nVerse 2\n\"Save us, we perish,\nLord,\" they cry; To Thee we fly for aid;\n\"Awake! awake!\" they say; but why So faithless and afraid?\n\nVerse 3\nHis head is pillow'd on the stern,\nAs Man He is asleep;\nAs God He all things does discern,\nAnd endless vigils keep.\n\nVerse 4\nHe does the elements control;\nBy His Almighty Will.\nThe angry waves their surges roll;\nAnd at His Word are still.\n\nVerse 5\nO ye, who in the Church's Bark O'er life's rough ocean sail,\nWhen all around is drear and dark, and human efforts fail,\n\nVerse 6\nTouch not, with rude, irreverent hands,\nAnd coward faithlessness,\nHim, who the winds and waves commands;\nBut wait in quietness.\n\nVerse 7\nO never, never when distressed,\nTo doubtful means resort;\nChrist's Bark, when on the billow's crest,\nIs safe as in the port.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-there-s-a-great-day-coming","title":"There's a Great Day Coming","language":"en","writers":"Will L. Thompson","music":"Will L. Thompson","year":1886,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"THERES A GREAT DAY COMING","themes":["Hymn"],"lyrics":"Verse 1\nThere's a great day coming,\nA great day coming,\nThere's a great day coming by and by;\nWhen the saints and the sinners shall be parted right and left,\n\nChorus\nAre you ready for that day to come?\nAre you ready? Are you ready?\nAre you ready for the judgment day?\nAre you ready? Are you ready?\nFor the judgment day?\n\nVerse 2\nThere's a bright day coming,\nA bright day coming,\nThere's a bright day coming by and by;\nBut its brightness shall only come to them that love the Lord,\n\nVerse 3\nThere's a sad day coming,\nA sad day coming,\nThere's a sad day coming by and by;\nWhen the sinner shall hear his doom,\n\"Depart, I know ye not,\"","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-thine-arm-o-lord-in-days-of-old","title":"Thine Arm, O Lord, in Days of Old","language":"en","writers":"Traditional","music":"traditional English","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"KINGSFOLD","themes":["Hymn"],"lyrics":"Verse 1\nThine arm, O Lord, in days of old, was strong to heal and save;\nIt triumphed o'er disease and death, o'er darkness and the grave.\nTo Thee they went, the blind, the dumb, the palsied and the lame,\nThe leper with his tainted life, the sick with fevered frame.\n\nVerse 2\nAnd lo! Thy touch brought life and health,\ngave speech, and strength and sight;\nAnd youth renewed and fear relieved owned Thee, the Lord of light;\nAnd now, O Lord, be near to bless,\nAlmighty as of yore,\nIn crowded street, by restless couch, as by Gennesaret's shore.\n\nVerse 3\nBe Thou our great Deliverer still,\nThou Lord of life and death;\nRestore and quicken, soothe and bless, with Thine almighty breath.\nTo hands that work and eyes that see, give wisdom's heavenly lore,\nThat whole and sick, and weak and strong, may praise Thee evermore.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-thou-who-at-thy-first-eucharist","title":"Thou, Who at Thy First Eucharist","language":"en","writers":"William H. Turton","music":"William Henry Monk","year":1881,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"UNDE ET MEMORES","themes":["Hymn"],"lyrics":"Verse 1\nThou, who at Thy first Eucharist didst pray\nThat all Thy Church might be forever one,\nGrant us at ev'ry Eucharist to say With longing heart and soul,\n\"Thy will be done.\" O may we all one bread, one body be,\nThrough this blest sacrament of unity.\n\nVerse 2\nFor all Thy Church,\nO Lord, we intercede;\nMake Thou our sad divisions soon to cease;\nDraw us the nearer each to each, we plead,\nBy drawing all to Thee,\nO Prince of Peace;\nThus may we all one bread, one body be,\nThrough this blest sacrament of unity.\n\nVerse 3\nWe pray Thee too for wand'rers from Thy fold;\nO bring them back, good Shepherd of the sheep,\nBack to the faith which saints believed of old,\nBack to the Church which still that faith doth keep;\nSoon may we all one bread, one body be,\nThrough this blest sacrament of unity.\n\nVerse 4\nSo, Lord, at length when sacraments shall cease,\nMay we be one with all Thy Church above,\nOne with Thy saints in one unbroken peace,\nOne with Thy saints in one unbounded love;\nMore blessèd still,\nin peace and love to be One with the Trinity in unity.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-though-in-the-midst-of-life-we-be","title":"Though in the Midst of Life We Be","language":"en","writers":"v.1 Medieval sequence, vs 2,3 Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"Medieval sequence altered by Martin Luther. Found in Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"MITTEN WIR IM LEBEN SIND","themes":["Hymn"],"lyrics":"Verse 1\nThough in midst of life we be,\nSnares of death surround us;\nWhere shall we for succor flee,\nLest our foes confound us?\nTo Thee alone, our Savior.\nWe mourn our grievous sin which hath\nStirr'd the fire of Thy fierce wrath.\nHoly and gracious God!\nHoly and mighty God!\nHoly and all-merciful Savior!\nThou eternal God! Save us,\nLord, from sinking In the deep and bitter flood. Kyrie eleison.\n\nVerse 2\nWhilst in midst of death we be,\nHell's grim jaws o'ertake us;\nWho from such distress will free.\nWho secure will make us?\nThou only, Lord, canst do it!\nIt moves Thy tender heart to see Our great sin and misery.\nHoly and gracious God!\nHoly and mighty God!\nHoly and all-merciful Savior!\nThou eternal God!\nLet not hell dismay us With its deep and burning flood. Kyrie eleison.\n\nVerse 3\nInto hell's fierce agony Sin doth headlong drive us:\nWhere shall we for succor flee,\nWho, O, who will hide us?\nThou only, blessed Saviour.\nThy precious blood was shed to win Peace and pardon for our sin.\nHoly and gracious God!\nHoly and mighty God!\nHoly and all-merciful Savior!\nLet us not, we pray,\nFrom the true faith's comfort\nFall in our last need away. Kyrie eleison.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-through-the-night-of-doubt-and-sorrow","title":"Through the Night of Doubt and Sorrow","language":"en","writers":"Bernhardt S. Ingemann, 1826. Translated by Sabine Baring-Gould","music":"Henry Thomas Smart","year":1826,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"REX GLORIAE","themes":["Hymn","Evening"],"lyrics":"Verse 1\nThrough the night of doubt and sorrow Onward goes the pilgrim band,\nSinging songs of expectation,\nMarching to the Promised Land.\nClear before us through the darkness\nGleams and burns the guiding light:\nBrother clasps the hand of brother,\nStepping fearless through the night.\n\nVerse 2\nOne the light of God's own presence,\nO'er His ransomed people shed,\nChasing far the gloom and terror,\nBright'ning all the path we tread:\nOne the object of our journey,\nOne the faith which never tires,\nOne the earnest looking forward,\nOne the hope our God inspires.\n\nVerse 3\nOne the strain that lips of thousands Lift as from the heart of one;\nOne the conflict, one the peril One the march in God begun:\nOne the gladness of rejoicing On the far eternal shore,\nWhere the One Almighty Father Reigns in love for evermore.\n\nVerse 4\nOnward, therefore, pilgrim brothers,\nOnward, with the cross our aid!\nBear its shame, and fight its battle,\nTill we rest beneath its shade.\nSoon shall come the great awaking,\nSoon the rending of the tomb;\nThen the scatt'ring of all shadows,\nAnd the end of toil and gloom.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-tis-good-lord-to-be-here","title":"Tis Good, Lord, To Be Here","language":"en","writers":"Joseph Armitage Robinson","music":"adapted from Johann Sebastian Bach, 1750, by John Goss","year":1888,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"POTSDAM","themes":["Hymn"],"lyrics":"Verse 1\n'Tis good, Lord, to be here,\nThy glory fills the night;\nThy face and garments, like the sun,\nShine with unborrowed light.\n\nVerse 2\n'Tis good, Lord, to be here,\nThy beauty to behold Where Moses and Elijah stand,\nThy messengers of old.\n\nVerse 3\nFulfiller of the past,\nPromise of things to be,\nWe hail Thy body glorified And our redemption see.\n\nVerse 4\nBefore we taste of death,\nWe see Thy Kingdom come;\nWe fain would hold the vision bright And make this hill our home.\n\nVerse 5\n'Tis good, Lord, to be here.\nYet we may not remain;\nBut since Thou bidst us leave the mount,\nCome with us to the plain.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-tis-midnight-and-on-olive-s-brow","title":"'Tis Midnight and On Olive's Brow","language":"en","writers":"William Bingham Tappan","music":"John Bacchus Dykes","year":1822,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ST. CROSS","themes":["Hymn","Evening"],"lyrics":"Verse 1\n'Tis midnight, and on Olive's brow\nThe star is dimmed that lately shone;\n'Tis midnight, in the garden now The suff'ring Savior prays alone.\n\nVerse 2\n'Tis midnight, and from all removed Immanuel wrestles,\nlone, with fears;\nE'en the disciple whom He loved\nHeeds not his Master's grief and tears.\n\nVerse 3\n'Tis midnight, from the heav'nly plains\nAre borne the songs that angels know;\nUnheard by mortals are the strains\nThat sweetly soothe the Savior's woe.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-to-avert-from-men-god-s-wrath","title":"To Avert From Men God's Wrath","language":"en","writers":"Latin c. 1400, sometimes attr. John Hus. Translated Christian Ignatius Latrobe","music":"Richard Redhead","year":1400,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"GETHSEMANE","themes":["Hymn"],"lyrics":"Verse 1\nTo avert from men God's wrath Jesus suffered in our stead;\nBy an ignominious death He a full atonement made;\nAnd by His most precious blood,\nBrought us, sinners, nigh to God.\n\nVerse 2\nThat we never should forget This great Love on us bestowed,\nHe gave us His flesh to eat, and to drink His precious blood;\nAll who sick and needy are May receive in Him a share.\n\nVerse 3\nHither each afflicted soul May repair, though filled with grief;\nTo the sick, not to the whole, the Physician brings relief;\nFear not, therefore, but draw nigh,\nChrist will all your wants supply.\n\nVerse 4\nHe who in self-righteousness Fixes any hope or stay,\nHas not on a wedding dress,\nAnd with shame is sent away;\nTo the hungry, weary heart,\nHe will food and rest impart.\n\nVerse 5\nBut examine first your case,\nWhether you be in the faith;\nDo you long for pard'ning grace?\nIs your only hope His death?\nThen, howe'er your soul's oppressed,\nCome, you are a worthy guest.\n\nVerse 6\nHe who Jesus' mercy knows, Is from wrath and envy freed;\nLove unto our neighbor shows That we are His flock indeed;\nThus we may in all our ways Show forth our Redeemer's praise.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-to-god-be-the-glory","title":"To God Be The Glory","language":"en","writers":"Fanny Crosby","music":"William Howard Doane","year":1875,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"TO GOD BE THE GLORY","themes":["Hymn"],"lyrics":"Verse 1\nTo God be the glory, great things He has done;\nSo loved He the world that He gave us His Son\nWho yielded His life an atonement for sin,\nAnd opened the life gate that all may go in.\n\nChorus\nPraise the Lord, praise the Lord,\nLet the earth hear His voice!\nPraise the Lord, praise the Lord,\nLet the people rejoice!\nO come to the Father, through Jesus the Son,\nAnd give Him the glory, great things He has done.\n\nVerse 2\nO perfect redemption, the purchase of blood,\nTo every believer the promise of God;\nThe vilest offender who truly believes,\nThat moment from Jesus a pardon receives.\n\nVerse 3\nGreat things He has taught us, great things He has done,\nAnd great our rejoicing through Jesus the Son;\nBut purer, and higher, and greater will be Our wonder,\nour transport, when Jesus we see.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-to-jordan-came-our-lord-the-christ","title":"To Jordan Came Our Lord, The Christ","language":"en","writers":"Martin Luther, 1541. Translated by Richard Massie","music":"Johann Walter","year":1541,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"CHRIST, UNSER HERR","themes":["Hymn"],"lyrics":"Verse 1\nTo Jordan came our Lord the Christ,\nTo do God's pleasure willing,\nAnd there was by Saint John baptized,\nAll righteousness fulfilling;\nThere did He consecrate a bath To wash away transgression,\nAnd quench the bitterness of death By His own blood and passion;\nHe would a new life give us.\n\nVerse 2\nSo hear ye all, and well perceive What God doth call baptism,\nAnd what a Christian should believe Who error shuns and schism:\nThat we should water use, the Lord Declareth it His pleasure;\nNot simple water, but the Word And Spirit without measure;\nHe is the true Baptizer.\n\nVerse 3\nTo show us this,\nHe hath His Word With signs and symbols given;\nOn Jordan's banks was plainly heard The Father's voice from Heaven:\n\"This is My well-beloved Son,\nIn whom My soul delighteth;\nHear Him.\" Yea, hear Him every one Whom He Himself inviteth,\nHear and obey His teaching.\n\nVerse 4\nIn tender manhood Jesus straight To holy Jordan wendeth;\nThe Holy Ghost from Heaven's gate In dovelike shape descendeth;\nThat thus the truth be not denied,\nNor should our faith e'er waver,\nThat the Three Persons all preside,\nAt baptism's holy laver,\nAnd dwell with the believer.\n\nVerse 5\nThus Jesus His disciples sent:\nGo teach ye every nation,\nThat lost in sin they must repent;\nAnd flee from condemnation:\nHe that believes and is baptized,\nObtains a mighty blessing;\nA newborn man, no more he dies,\nEternal life possessing, A joyful heir of Heaven.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-to-shepherds-as-they-watched-by-night","title":"To Shepherds As They Watched By Night","language":"en","writers":"Martin Luther, 1543. translated by Richard Massie","music":"traditional German from Schumann's Geistliche Lieder, Leipzig","year":1543,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"VOM HIMMEL HOCH","themes":["Hymn","Christmas","Evening"],"lyrics":"Verse 1\nTo shepherds as they watched by night\nAppeared a host of angels bright;\nBehold the tender Babe, they said,\nIn yonder lowly manger laid.\n\nVerse 2\nAt Bethlehem, in David's town,\nAs Micah did of old make known;\n'Tis Jesus Christ, your Lord and King,\nWho doth to all salvation bring.\n\nVerse 3\nOh, then rejoice that through His Son God is with sinners now at one;\nMade like yourselves of flesh and blood,\nYour Brother is th'eternal God.\n\nVerse 4\nWhat harm can sin and death then do?\nThe true God now abides with you.\nLet hell and Satan rage and chafe,\nChrist is your Brother ye are safe.\n\nVerse 5\nNot one He will or can forsake Who Him his confidence doth make.\nLet all his wiles the Tempter try,\nYou may his utmost pow'rs defy.\n\nVerse 6\nYe shall and must at last prevail;\nGod's own ye are, ye cannot fail.\nTo God forever sing your praise\nWith joy and patience all your days.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-today-thy-mercy-calls-me","title":"Today Thy Mercy Calls Me","language":"en","writers":"Oswald Allen, 1861, alt","music":"Friedrich K. Anthes","year":1861,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"ANTHES","themes":["Hymn"],"lyrics":"Verse 1\nToday Thy mercy calls me to wash away my sin;\nHowever great my trespass, whate'er I may have been;\nHowever long from mercy I may have turned away,\nThy blood, O Christ, can wash me, and make me clean today.\n\nVerse 2\nToday Thy gate is open,\nand all who enter in Shall find a Father's welcome,\nand pardon for their sin;\nThe past shall be forgotten, a present joy be given;\nA future grace be promised, a glorious crown in Heav'n.\n\nVerse 3\nToday the Father calls me, the Holy Spirit waits,\nThe blessèd angels gather around the heav'nly gates;\nNo question will be asked me, how often I have come;\nAlthough I oft have wandered, it is my Father's home.\n\nVerse 4\nO all embracing mercy, thou ever open door,\nWhat shall I do without thee when heart and eyes run o'er?\nWhen all things seem against me, to drive me to despair,\nI know one gate is open, one ear will hear my prayer.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-twas-on-that-dark-that-doleful-night","title":"'Twas On That Dark, That Doleful Night","language":"en","writers":"Isaac Watts","music":"John Bacchus Dykes","year":1709,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"ST. CROSS","themes":["Hymn","Evening"],"lyrics":"Verse 1\n'Twas on that dark,\nthat doleful night When pow'rs of earth and hell arose\nAgainst the Son of God's delight,\nAnd friends betrayed Him to His foes:\n\nVerse 2\nBefore the mournful scene began,\nHe took the bread, and blessed, and brake:\nWhat love through all His actions ran!\nWhat wondrous words of grace He spake!\n\nVerse 3\n\"This is My body, broke for sin;\nReceive and eat the living food:\" Then took the cup,\nand blessed the wine;\n\"'Tis the new cov'nant in My blood.\"\n\nVerse 4\nFor us His flesh with nails was torn,\nHe bore the scourge,\nHe felt the thorn;\nAnd justice poured upon His head Its heavy vengeance in our stead.\n\nVerse 5\nFor us His vital blood was spilt,\nTo buy the pardon of our guilt,\nWhen, for black crimes of biggest size,\nHe gave His soul a sacrifice.\n\nVerse 6\n\"Do this,\" He cried, \"till time shall end,\nIn memory of your dying friend;\nMeet at My table, and record\nThe love of your departed Lord.\"\n\nVerse 7\nJesus, Thy feast we celebrate,\nWe show Thy death, we sing Thy name,\nTill Thou return, and we shall eat\nThe marriage supper of the Lamb.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"},{"id":"oh-under-his-wings","title":"Under His Wings","language":"en","writers":"William Orcutt Cushing","music":"Ira David Sankey","year":1896,"rights":"public-domain","copyright":"Public domain","defaultKey":"Db","bpm":null,"tune":"UNDER HIS WINGS","themes":["Hymn"],"lyrics":"Verse 1\nUnder His wings I am safely abiding,\nThough the night deepens and tempests are wild,\nStill I can trust Him;\nI know He will keep me,\nHe has redeemed me, and I am His child.\n\nChorus\nUnder His wings, under His wings,\nWho from His love can sever?\nUnder His wings my soul shall abide, Safely abide forever.\n\nVerse 2\nUnder His wings, what a refuge in sorrow!\nHow the heart yearningly turns to His rest!\nOften when earth has no balm for my healing,\nThere I find comfort, and there I am blessed.\n\nVerse 3\nUnder His wings, oh, what precious enjoyment!\nThere will I hide till life's trials are o'er;\nSheltered, protected, no evil can harm me,\nResting in Jesus, I'm safe evermore.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-wake-awake-for-night-is-flying","title":"Wake, Awake, for Night Is Flying","language":"en","writers":"Phillipp Nicolai, 1599. Translated by Catherine Winkworth","music":"Phillip Nicolai","year":1599,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"WACHET AUF","themes":["Hymn","Evening"],"lyrics":"Verse 1\nWake, awake, for night is flying;\nThe watchmen on the heights are crying:\nAwake, Jerusalem, at last!\nMidnight hears the welcome voices And at the thrilling cry rejoices;\nCome forth, ye virgins, night is past;\nThe Bridegroom comes, awake;\nYour lamps with gladness take;\nAlleluia! And for His marriage feast prepare\nFor ye must go and meet Him there.\n\nVerse 2\nZion hears the watchmen singing,\nAnd all her heart with joy is springing;\nShe wakes, she rises from her gloom;\nFor her Lord comes down all glorious,\nThe strong in grace, in truth victorious.\nHer Star is ris'n, her Light is come.\nAh come, Thou blessed One,\nGod's own beloved Son:\nAlleluia! We follow till the halls we see\nWhere Thou hast bid us sup with Thee\n\nVerse 3\nNow let all the heav'ns adore Thee,\nAnd saints and angels sing before Thee,\nWith harp and cymbal's clearest tone;\nOf one pearl each shining portal,\nWhere we are with the choir immortal\nOf angels round Thy dazzling throne;\nNor eye hath seen,\nnor ear hath yet attained to hear What there is ours,\nbut we rejoice and sing to Thee Our hymn of joy eternally.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-we-all-believe-in-one-true-god","title":"We All Believe in One True God","language":"en","writers":"Medieval text expanded by Martin Luther, 1524. Translation composite","music":"Medieval tune altered by Martin Luther. Found in Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"WIR GLAUBEN ALL AN EINEN GOTT, SCHOEPFER","themes":["Hymn"],"lyrics":"Verse 1\nWe all believe in one true God,\nWho created earth and heaven,\nThe Father, who to us in love Hath the right of children given.\nHe both soul and body feedeth,\nAll we need He doth provide us;\nHe through snares and perils leadeth,\nWatching that no harm betide us.\nHe careth for us day and night,\nAll things are governed by His might.\n\nVerse 2\nWe all believe in Jesus Christ,\nHis own Son, our Lord, possessing An equal Godhead, throne, and might,\nSource of every grace and blessing.\nBorn of Mary, virgin mother,\nBy the power of the Spirit,\nMade true man, our elder Brother,\nThat the lost might life inherit;\nWas crucified for sinful men And raised by God to life again.\n\nVerse 3\nWe all confess the Holy Ghost,\nWho sweet grace and comfort giveth And with the\nFather and the Son In eternal glory liveth;\nWho the Church, His own creation,\nKeeps in unity of spirit.\nHere forgiveness and salvation Daily come through Jesus' merit.\nAll flesh shall rise, and we shall be In bliss with God eternally.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-we-gather-together","title":"We Gather Together","language":"en","writers":"Anonymous circa 1597. Translated Theodore Baker","music":"Traditional Dutch","year":1597,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"KREMSER","themes":["Hymn"],"lyrics":"Verse 1\nWe gather together to ask the Lord's blessing;\nHe chastens and hastens His will to make known.\nThe wicked oppressing now cease from distressing.\nSing praises to His Name;\nHe forgets not His own.\n\nVerse 2\nBeside us to guide us, our God with us joining,\nOrdaining, maintaining His kingdom divine;\nSo from the beginning the fight we were winning;\nThou, Lord, were at our side, all glory be Thine!\n\nVerse 3\nWe all do extol Thee,\nThou Leader triumphant, And pray that Thou still our Defender will be.\nLet Thy congregation escape tribulation;\nThy Name be ever praised!\nO Lord, make us free!","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-we-give-thee-but-thine-own","title":"We Give Thee But Thine Own","language":"en","writers":"William W. How","music":"William H. Monk (1823-1889)","year":1864,"rights":"public-domain","copyright":"Public domain","defaultKey":"G","bpm":null,"tune":"ENERGY","themes":["Hymn"],"lyrics":"Verse 1\nWe give Thee but Thine own,\nWhate'er the gift may be;\nAll that we have is Thine alone,\nA trust, O Lord, from Thee.\n\nVerse 2\nMay we Thy bounties thus As stewards true receive,\nAnd gladly, as Thou blessest us,\nTo Thee our firstfruits give.\n\nVerse 3\nO hearts are bruised and dead,\nAnd homes are bare and cold,\nAnd lambs for whom the Shepherd bled Are straying from the fold.\n\nVerse 4\nTo comfort and to bless,\nTo find a balm for woe,\nTo tend the lone and fatherless Is angels' work below.\n\nVerse 5\nThe captive to release,\nTo God the lost to bring,\nTo teach the way of life and peace?\nIt is a Christlike thing.\n\nVerse 6\nAnd we believe Thy Word,\nThough dim our faith may be;\nWhate'er for Thine we do, O Lord,\nWe do it unto Thee.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-we-know-thee-who-thou-art","title":"We Know Thee Who Thou Art","language":"en","writers":"William Bright","music":"John Pyke Hullah","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"SELLINGE","themes":["Hymn"],"lyrics":"Verse 1\nWe know Thee who Thou art,\nLord Jesus, Mary's Son;\nWe know the yearnings of Thy heart To end Thy work begun.\n\nVerse 2\nThat sacred fount of grace,\n'Mid all the bliss of Heav'n,\nHas joy whene'er we seek Thy face,\nAnd kneel to be forgiv'n.\n\nVerse 3\nBrought home from ways perverse,\nAt peace Thine arms within,\nWe pray Thee, shield us from the curse Of falling back to sin.\n\nVerse 4\nWe dare not ask to live Henceforth from trials free;\nBut oh! when next they tempt us, give More strength to cling to Thee.\n\nVerse 5\nWe know Thee who Thou art,\nOur own redeeming Lord;\nBe Thou by will, and mind, and heart, Accepted, loved, adored.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-we-now-implore-god-the-holy-ghost","title":"We Now Implore God the Holy Ghost","language":"en","writers":"v.1 ancient German. verses 2-4 Martin Luther, 1524. Translation composite","music":"ancient German found in Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"NUN BITTEN WIR DEN HEILIGEN GEIST","themes":["Hymn","Pentecost"],"lyrics":"Verse 1\nWe now implore God the Holy Ghost For the true faith,\nwhich we need the most,\nThat in our last moments He may befriend us And,\nas homeward we journey, attend us. Lord, have mercy.\n\nVerse 2\nShine in our hearts,\nO most precious Light,\nThat we Jesus Christ may know aright,\nClinging to our Savior, whose blood hath bought us.\nWho again to our homeland hath brought us. Lord, have mercy.\n\nVerse 3\nThou sacred Love, grace on us bestow,\nSet our hearts with heav'nly fire aglow\nThat with hearts united we love each other,\nOf one mind, in peace with ev'ry brother. Lord, have mercy!\n\nVerse 4\nThou highest Comfort in ev'ry need,\nGrant that neither shame nor death we heed,\nThat e'en then our courage may never fail us When the\nFoe shall accuse and assail us. Lord, have mercy!","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-were-you-there","title":"Were You There?","language":"en","writers":"African-American Spiritual, before","music":"African-American Spiritual, before","year":1899,"rights":"public-domain","copyright":"Public domain","defaultKey":"E","bpm":null,"tune":"WERE YOU THERE","themes":["Hymn"],"lyrics":"Verse 1\nWere you there when they crucified my Lord?\nWere you there when they crucified my Lord?\nSometimes it causes me to tremble, tremble, tremble.\nWere you there when they crucified my Lord?\n\nVerse 2\nWere you there when they nailed Him to the tree?\nWere you there when they nailed Him to the tree?\nSometimes it causes me to tremble, tremble, tremble.\nWere you there when they nailed Him to the tree?\n\nVerse 3\nWere you there when they pierced Him in the side?\nWere you there when they pierced Him in the side?\nOh! Sometimes it causes me to tremble, tremble, tremble.\nWere you there when they pierced Him in the side?\n\nVerse 4\nWere you there when the sun refused to shine?\nWere you there when the sun refused to shine?\nSometimes it causes me to tremble, tremble, tremble.\nWere you there when the sun refused to shine?\n\nVerse 5\nWere you there when they laid Him in the tomb?\nWere you there when they laid Him in the tomb?\nSometimes it causes me to tremble, tremble, tremble.\nWere you there when they laid Him in the tomb?\n\nVerse 6\nWere you there when God raised Him from the tomb?\nWere you there when God raised Him from the tomb?\nOh! Sometimes it causes me to tremble, tremble, tremble.\nWere you there when God raised Him from the tomb?","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-what-a-friend-we-have-in-jesus","title":"What A Friend We Have In Jesus","language":"en","writers":"Joseph M. Scriven","music":"Charles C. Converse","year":1855,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"UNTITLED","themes":["Hymn"],"lyrics":"Verse 1\nWhat a Friend we have in Jesus, all our sins and griefs to bear!\nWhat a privilege to carry everything to God in prayer!\nO what peace we often forfeit,\nO what needless pain we bear,\nAll because we do not carry everything to God in prayer.\n\nVerse 2\nHave we trials and temptations?\nIs there trouble anywhere?\nWe should never be discouraged; take it to the Lord in prayer.\nCan we find a friend so faithful who will all our sorrows share?\nJesus knows our every weakness; take it to the Lord in prayer.\n\nVerse 3\nAre we weak and heavy laden, cumbered with a load of care?\nPrecious Savior, still our refuge, take it to the Lord in prayer.\nDo your friends despise, forsake you?\nTake it to the Lord in prayer!\nIn His arms He'll take and shield you; you will find a solace there.\n\nVerse 4\nBlessed Savior, Thou hast promised\nThou wilt all our burdens bear May we ever,\nLord, be bringing all to Thee in earnest prayer.\nSoon in glory bright unclouded there will be no need for prayer Rapture,\npraise and endless worship will be our sweet portion there.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4"],"source":"Open Hymnal Project"},{"id":"oh-what-child-is-this","title":"What Child Is This?","language":"en","writers":"William Chatterton Dix","music":"16th Century English Traditional","year":1865,"rights":"public-domain","copyright":"Public domain","defaultKey":"D","bpm":null,"tune":"GREENSLEEVES","themes":["Hymn","Christmas"],"lyrics":"Verse 1\nWhat Child is this who, laid to rest On Mary's lap is sleeping?\nWhom angels greet with anthems sweet,\nWhile shepherds watch are keeping?\nThis, this is Christ the King,\nWhom shepherds guard and angels sing;\nHaste, haste, to bring Him laud,\nThe Babe, the Son of Mary.\n\nVerse 2\nWhy lies He in such mean estate,\nWhere ox and ass are feeding?\nGood Christians, fear, for sinners here The silent Word is pleading.\nNails, spear shall pierce Him through,\nThe cross be borne for me, for you.\nHail, hail the Word made flesh,\nThe Babe, the Son of Mary.\n\nVerse 3\nSo bring Him incense, gold and myrrh,\nCome peasant, king to own Him;\nThe King of kings salvation brings,\nLet loving hearts enthrone Him.\nRaise, raise a song on high,\nThe virgin sings her lullaby.\nJoy, joy for Christ is born,\nThe Babe, the Son of Mary.","arrangement":["Verse 1","Verse 2","Verse 3"],"source":"Open Hymnal Project"},{"id":"oh-when-i-survey-the-wondrous-cross","title":"When I Survey the Wondrous Cross","language":"en","writers":"Isaac Watts","music":"John Hatton","year":1707,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"DUKE STREET","themes":["Hymn","Lent"],"lyrics":"Verse 1\nWhen I survey the wondrous cross On which the Prince of Glory died,\nMy richest gain I count but loss,\nAnd pour contempt on all my pride.\n\nVerse 2\nForbid it, Lord, that I should boast,\nSave in the death of Christ my God!\nAll the vain things that charm me most,\nI sacrifice them to His blood.\n\nVerse 3\nSee from His head,\nHis hands, His feet,\nSorrow and love flow mingled down!\nDid e'er such love and sorrow meet,\nOr thorns compose so rich a crown?\n\nVerse 4\nHis dying crimson, like a robe,\nSpreads o'er His body on the tree;\nThen I am dead to all the globe,\nAnd all the globe is dead to me.\n\nVerse 5\nWere the whole realm of nature mine,\nThat were a present far too small;\nLove so amazing, so divine,\nDemands my soul, my life, my all.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-when-the-roll-is-called-up-yonder","title":"When The Roll Is Called Up Yonder","language":"en","writers":"James Milton Black","music":"James Milton Black","year":1893,"rights":"public-domain","copyright":"Public domain","defaultKey":"Ab","bpm":null,"tune":"WHEN THE ROLL IS CALLED UP YONDER","themes":["Hymn"],"lyrics":"Verse 1\nWhen the trumpet of the Lord shall sound, and time shall be no more,\nAnd the morning breaks, eternal, bright and fair;\nWhen the saved of earth shall gather over on the other shore,\nAnd the roll is called up yonder, I'll be there.\n\nChorus\nWhen the roll is called up yonder,\nWhen the roll is called up yonder,\nWhen the roll is called up yonder,\nWhen the roll is called up yonder, I'll be there.\n\nVerse 2\nOn that bright and cloudless morning when the dead in\nChrist shall rise,\nAnd the glory of His resurrection share;\nWhen His chosen ones shall gather to their home beyond the skies,\n\nVerse 3\nLet us labor for the Master from the dawn till setting sun,\nLet us talk of all His wondrous love and care;\nThen when all of life is over, and our work on earth is done,","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-where-he-leads-me","title":"Where He Leads Me","language":"en","writers":"Edward (or Ernest) William Blandy","music":"attr. John Samuel Norris (1844-1907) or Philip Paul Bliss (1838-1876)","year":1890,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"BLANDY","themes":["Hymn"],"lyrics":"Verse 1\nI can hear my Savior calling,\nI can hear my Savior calling,\nI can hear my Savior calling,\n\"Take thy cross and follow, follow Me.\"\n\nChorus\nWhere He leads me I will follow,\nWhere He leads me I will follow,\nWhere He leads me I will follow;\nI'll go with Him, with Him, all the way.\n\nVerse 2\nI'll go with Him through the garden,\nI'll go with Him through the garden,\nI'll go with Him through the garden,\nI'll go with Him, with Him all the way.\n\nVerse 3\nI'll go with Him through the judgment,\nI'll go with Him through the judgment,\nI'll go with Him through the judgment,\nI'll go with Him, with Him all the way.\n\nVerse 4\nHe will give me grace and glory,\nHe will give me grace and glory,\nHe will give me grace and glory,\nAnd go with me, with me all the way.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-while-o-er-our-guilty-land-o-lord","title":"While O'er Our Guilty Land, O Lord","language":"en","writers":"verses 1-3, Samuel Davies, 1769. alt. verses 4-6, Brian J. Dumont, 15 Nov 2010","music":"Henry K. Oliver","year":1769,"rights":"public-domain","copyright":"Public domain","defaultKey":"F","bpm":null,"tune":"FEDERAL STREET","themes":["Hymn"],"lyrics":"Verse 1\nWhile o'er our guilty land,\nO Lord, We view the terrors of Your sword,\nO where can all the helpless fly?\nTo whom but You direct their cry?\n\nVerse 2\nOn You, our guardian God, we call;\nBefore Your throne of grace we fall;\nBut is there no deliv'rance there?\nAnd must we perish in despair?\n\nVerse 3\nSee, we repent, we weep, we mourn;\nTo our forsaken God we turn;\nO spare our guilty country,\nspare The Church which You have planted there.\n\nVerse 4\nWe are the old, the sick, the lame;\nWe blind and deaf cry Jesus' Name.\nWe plead Your mercy for His sake,\nAnd trust that You will not forsake.\n\nVerse 5\nChrist is our only righteousness,\nHis death for us is our redress.\nYour promise stronger than our sin;\nBlot out O Lord what we have been.\n\nVerse 6\nWe are your children after all,\nRedeemed by Christ after the fall.\nMarked with Your Name in Baptism,\nOur home remains in Your Kingdom.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6"],"source":"Open Hymnal Project"},{"id":"oh-whiter-than-snow","title":"Whiter Than Snow","language":"en","writers":"James Nicholson","music":"William Gustavus Fischer","year":1872,"rights":"public-domain","copyright":"Public domain","defaultKey":"A","bpm":null,"tune":"WHITER THAN SNOW","themes":["Hymn"],"lyrics":"Verse 1\nLord Jesus, I long to be perfectly whole;\nI want Thee forever to live in my soul,\nBreak down ev'ry idol, cast out ev'ry foe;\nNow wash me and I shall be whiter than snow.\n\nChorus\nWhiter than snow, yes, whiter than snow;\nNow wash me, and I shall be whiter than snow.\n\nVerse 2\nLord Jesus, look down from Thy throne in the skies,\nAnd help me to make a complete sacrifice;\nI give up myself, and whatever I know,\nNow wash me and I shall be whiter than snow.\n\nVerse 3\nLord Jesus, for this I most humbly entreat,\nI wait, blessed Lord, at Thy crucified feet,\nBy faith, for my cleansing,\nI see Thy blood flow,\nNow wash me and I shall be whiter than snow.\n\nVerse 4\nLord Jesus, Thou seest I patiently wait,\nCome now, and within me a new heart create;\nTo those who have sought Thee,\nThou never said'st ''No,''\nNow wash me and I shall be whiter than snow.","arrangement":["Verse 1","Chorus","Verse 2","Chorus","Verse 3","Chorus","Verse 4","Chorus"],"source":"Open Hymnal Project"},{"id":"oh-wilt-thou-o-man-live-happily","title":"Wilt Thou, O Man, Live Happily","language":"en","writers":"Martin Luther, 1524. Translated by Richard Massie, 1854, alt","music":"attr. Martin Luther. Found in Walter's Geistliche Gesangbüchlein","year":1524,"rights":"public-domain","copyright":"Public domain","defaultKey":"C","bpm":null,"tune":"MENSCH, WILLT DU LEBEN SELIGICH","themes":["Hymn"],"lyrics":"Verse 1\nWilt thou, O man, live happily,\nAnd dwell with God eternally,\nThe ten commandments keep,\nfor thus Our God Himself biddeth us. Kyr' eleison!\n\nVerse 2\nI am the Lord and God! take heed No other god doth thee mislead;\nThy heart shall trust alone in Me,\nMy kingdom then thou shalt be.\n\nVerse 3\nHonor My Name in word and deed,\nAnd call on Me in time of need:\nHallow the Sabbath, that I may Work in thy heart on that day.\n\nVerse 4\nObedient always, next to Me,\nTo father and to mother be;\nKill no man: even anger dread;\nKeep sacred thy marriage bed.\n\nVerse 5\nSteal not, nor do thy neighbor wrong\nBy bearing witness with false tongue;\nThy neighbor's wife desire thou not,\nNor grudge him aught he hath got.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5"],"source":"Open Hymnal Project"},{"id":"oh-within-the-father-s-house","title":"Within the Father's House","language":"en","writers":"James Russell Woodford","music":"Johann Balthasar König","year":1863,"rights":"public-domain","copyright":"Public domain","defaultKey":"Eb","bpm":null,"tune":"FRANCONIA","themes":["Hymn"],"lyrics":"Verse 1\nWithin the Father's house The Son hath found His home;\nAnd to His temple suddenly The Lord of Life hath come.\n\nVerse 2\nThe doctors of the law Gaze on the wondrous child,\nAnd marvel at His gracious words Of wisdom undefiled.\n\nVerse 3\nYet not to them is giv'n The mighty truth to know,\nTo lift the fleshly veil which hides Incarnate God below.\n\nVerse 4\nThe secret of the Lord Escapes each human eye,\nAnd faithful pond'ring hearts await The full epiphany.\n\nVerse 5\nLord, visit Thou our souls,\nAnd teach us by Thy grace Each dim revealing of\nThyself With loving awe to trace;\n\nVerse 6\nTill from our darkened sight\nThe cloud shall pass away,\nAnd on the cleansèd soul shall burst\nThe everlasting day.\n\nVerse 7\nTill we behold Thy face,\nAnd know, as we are known,\nThee, Father, Son, and Holy Ghost,\nCo-equal Three in One.","arrangement":["Verse 1","Verse 2","Verse 3","Verse 4","Verse 5","Verse 6","Verse 7"],"source":"Open Hymnal Project"}];
